window.GLOSSIKA_B1 = {"book":1,"lessons":[{"lesson":1,"range":[1,100],"items":[{"n":1,"zh":"今天天气真好。","en":"The weather's nice today.","it":"Oggi il tempo è bello.","ipa":"ɔ̣dʤ‿ il tẹmpo ɛ̣ bɛ̣lːo."},{"n":2,"zh":"我不富裕。","en":"I'm not rich.","it":"Non sono ricco (♀ricca).","ipa":"non sọno rịkːo (♀rịkːa)."},{"n":3,"zh":"这个包很重。","en":"This bag's heavy.","it":"Questa borsa è pesante.","ipa":"kwɛ̣sta bọrsa ɛ̣ pezạnte."},{"n":4,"zh":"这些包都很重。","en":"These bags are heavy.","it":"Queste borse sono pesanti.","ipa":"kwɛ̣ste bọrse sọno pezạnti."},{"n":5,"zh":"看看，那是我的朋友。","en":"Look, there's my friend.","it":"Guarda, c'è il mio amico (♀la mia amica).","ipa":"ɡwạrda, ʧɛ̣ il mịo amịko (♀la mịa amịka)."},{"n":6,"zh":"我和我哥哥是很好的网球选手。","en":"My brother and I are good tennis players.","it":"Io e mio fratello siamo due bravi giocatori di tennis.","ipa":"ịo e mịo fratɛ̣lːo sjạmo dụe brạvi ʤokatọri di tɛ̣nːis."},{"n":7,"zh":"他妈妈在家，他在学校。","en":"His mother's at home. He's at school.","it":"Sua madre è a casa. Lui è a scuola.","ipa":"sụa mạdre ɛ̣ a kạza. lụj ɛ̣ a skwɔ̣la."},{"n":8,"zh":"她的孩子们都在学校。","en":"Her children are at school.","it":"I suoi figli sono a scuola.","ipa":"i swɔ̣j fịʎːi sọno a skwɔ̣la."},{"n":9,"zh":"我是一名出租车司机。","en":"I'm a taxi driver.","it":"Io sono tassista.","ipa":"ịo sọno tasːịsta."},{"n":10,"zh":"我姐姐是护士。","en":"My sister's a nurse.","it":"Mia sorella è infermiera.","ipa":"mịa sorɛ̣lːa ɛ̣ infermjẹra."},{"n":11,"zh":"他生病了，他在床上。","en":"He's sick. He's in bed.","it":"Lui è malato. È a letto.","ipa":"lụj ɛ̣ malạto. ɛ̣ a lɛ̣tːo."},{"n":12,"zh":"我不饿，但我渴。","en":"I'm not hungry, but I'm thirsty.","it":"Io non ho fame, ma ho sete.","ipa":"ịo non ɔ fạme, ma ɔ sẹte."},{"n":13,"zh":"他年纪很大，98岁了。","en":"He's a very old man. He's ninety-eight (98) years old.","it":"Lui è un uomo molto vecchio. Ha novantotto (98) anni.","ipa":"lụj ɛ̣ un wɔ̣mo mọlto vɛ̣kːjo. a novantɔ̣tːo (98) ạnːi."},{"n":14,"zh":"这些椅子不漂亮，但很舒服。","en":"These chairs aren't beautiful, but they're comfortable.","it":"Queste sedie non sono bellissime, ma sono comode.","ipa":"kwɛ̣ste sẹdje non sọno belːịsːime, ma sọno kɔ̣mode."},{"n":15,"zh":"今天天气暖和，阳光明媚。","en":"The weather's warm and sunny today.","it":"Oggi fa caldo e c'è il sole.","ipa":"ɔ̣dʤi fa kạldo e ʧɛ̣ il sọle."},{"n":16,"zh":"你迟到了。——不，我没！我提前了。","en":"You're late. — No, I'm not! I'm early.","it":"Tu sei in ritardo. — No, non sono in ritardo! Io sono in anticipo.","ipa":"tu sɛ̣j in ritạrdo. — nɔ, non sọno in ritạrdo. ịo sọno in antịʧipo."},{"n":17,"zh":"她不在家，她在工作。","en":"She isn't home. She's at work.","it":"Lei non è a casa. È al lavoro.","ipa":"lɛ̣j non ɛ̣ a kạza. ɛ̣ al lavọro."},{"n":18,"zh":"这是你的外套。","en":"Here's your coat.","it":"Ecco il tuo cappotto.","ipa":"ɛ̣kːo il tụo kapːɔ̣tːo"},{"n":19,"zh":"你叫什么名字？","en":"What's your name?","it":"Come ti chiami?","ipa":"kọme ti kjạmi?"},{"n":20,"zh":"我叫艾伦。","en":"My name's Alan.","it":"Io mi chiamo Alan.","ipa":"ịo mi kjạmo (…)."},{"n":21,"zh":"你来自哪里？","en":"Where are you from?","it":"Di dove sei?","ipa":"di dọve sɛ̣j?"},{"n":22,"zh":"我来自纽约。","en":"I'm from New York.","it":"Io sono di New York.","ipa":"ịo sọno di (…) (…)."},{"n":23,"zh":"你多大了？","en":"How old are you?","it":"Quanti anni hai?","ipa":"kwạnti ạnːi ạj?"},{"n":24,"zh":"我20岁。","en":"I'm twenty (20) years old.","it":"Io ho vent'anni.","ipa":"ịo ɔ ventạnːi."},{"n":25,"zh":"你是做什么工作的？","en":"What's your job?","it":"Che lavoro fai?","ipa":"ke lavọro fạj?"},{"n":26,"zh":"我是一名老师。","en":"I'm a teacher.","it":"Faccio l'insegnante.","ipa":"fạtʧo linseɲːạnte."},{"n":27,"zh":"你最喜欢的颜色是什么？","en":"What's your favorite color?","it":"Qual è il tuo colore preferito?","ipa":"kwạl ɛ̣ il tụo kolọre preferịto?"},{"n":28,"zh":"我最喜欢的颜色是蓝色。","en":"My favorite color is blue.","it":"Il mio colore preferito è il blu.","ipa":"il mịo kolọre preferịto ɛ̣ il blu."},{"n":29,"zh":"你对什么感兴趣？","en":"What are you interested in?","it":"Quali sono i tuoi interessi?","ipa":"kwạli sọno i twɔ̣j interɛ̣sːi?"},{"n":30,"zh":"我对音乐感兴趣。","en":"I'm interested in music.","it":"Mi interesso di musica.","ipa":"m‿ interɛ̣sːo di mụzika."},{"n":31,"zh":"今天天气很热。","en":"It's hot today.","it":"Fa caldo oggi.","ipa":"fa kạld‿ ɔ̣dʤi."},{"n":32,"zh":"今天天气不热。","en":"It isn't hot today.","it":"Oggi non fa caldo.","ipa":"ɔ̣dʤi non fa kạldo."},{"n":33,"zh":"今天风很大。","en":"It's windy today.","it":"Oggi c'è vento.","ipa":"ɔ̣dʤi ʧɛ̣ vɛ̣nto."},{"n":34,"zh":"今天风不大。","en":"It isn't windy today.","it":"Non c'è vento oggi.","ipa":"non ʧɛ̣ vɛ̣nt‿ ɔ̣dʤi."},{"n":35,"zh":"我手冷。","en":"My hands are cold.","it":"Le mie mani sono fredde.","ipa":"le mịe mạni sọno frɛ̣dːe."},{"n":36,"zh":"巴西是个非常大的国家。","en":"Brazil is a very big country.","it":"Il Brasile è un paese molto grande.","ipa":"il brazịl‿ ɛ̣ un paɛ̣ze mọlto ɡrạnde."},{"n":37,"zh":"钻石不便宜。","en":"Diamonds are not cheap.","it":"I diamanti non costano poco.","ipa":"i djamạnti non kɔ̣stano pɔ̣ko."},{"n":38,"zh":"多伦多不在美国。","en":"Toronto isn't in the United States.","it":"Toronto non si trova negli Stati Uniti.","ipa":"torọnto non si trɔ̣va nɛ̣ʎːi stạti unịti."},{"n":39,"zh":"我累了。","en":"I'm tired.","it":"Io sono stanco (♀stanca).","ipa":"ịo sọno stạŋko (♀stạŋka)."},{"n":40,"zh":"我不累。","en":"I'm not tired.","it":"Io non sono stanco (♀stanca).","ipa":"ịo non sọno stạŋko (♀stạŋka)."},{"n":41,"zh":"我饿了。","en":"I'm hungry.","it":"Io ho fame.","ipa":"ịo ɔ fạme."},{"n":42,"zh":"我不饿。","en":"I'm not hungry.","it":"Io non ho fame.","ipa":"ịo non ɔ fạme."},{"n":43,"zh":"他游泳很好。","en":"He's a good swimmer.","it":"Lui nuota bene.","ipa":"lụj nwɔ̣ta bẹne."},{"n":44,"zh":"我对政治不感兴趣。","en":"I'm not interested in politics.","it":"La politica non mi interessa.","ipa":"la polịtika non m‿ interɛ̣sːa."},{"n":45,"zh":"你叫什么名字？","en":"What's your name?","it":"Come ti chiami?","ipa":"kọme ti kjạmi?"},{"n":46,"zh":"我叫阿曼达。","en":"My name's Amanda.","it":"Mi chiamo Amanda.","ipa":"mi kjạmo amạnda."},{"n":47,"zh":"你结婚了么？","en":"Are you married?","it":"Tu sei sposato (♀sposata)?","ipa":"tu sɛ̣j spozạto (♀spozạta)?"},{"n":48,"zh":"没有，我是单身。","en":"No, I'm single.","it":"No, sono celibe.","ipa":"nɔ, sọno ʧẹlibe."},{"n":49,"zh":"你多大了？","en":"How old are you?","it":"Quanti anni hai?","ipa":"kwạnti ạnːi ạj?"},{"n":50,"zh":"我25岁（25）。","en":"I'm twenty-five (25).","it":"Io ho venticinque (25) anni.","ipa":"ịo ɔ ventiʧịŋkwe (25) ạnːi."},{"n":51,"zh":"你是学生吗？","en":"Are you a student?","it":"Sei studente?","ipa":"sɛ̣j studɛ̣nte?"},{"n":52,"zh":"是的，我是学生。","en":"Yes, I am [a student].","it":"Sì, sono studente.","ipa":"sị, sọno studɛ̣nte."},{"n":53,"zh":"我迟到了吗？","en":"Am I late?","it":"Sono in ritardo?","ipa":"sọno in ritạrdo?"},{"n":54,"zh":"没有，你准时了。","en":"No, you're on time.","it":"No, sei puntuale.","ipa":"nɔ, sɛ̣j puntwạle."},{"n":55,"zh":"你妈妈在家吗？","en":"Is your mother at home?","it":"Tua mamma è a casa?","ipa":"tụa mạmːa ɛ̣ a kạza?"},{"n":56,"zh":"不，她出去了。","en":"No, she's out.","it":"No, è uscita.","ipa":"nɔ, ɛ̣ uʃịta."},{"n":57,"zh":"你父母在家吗？","en":"Are your parents at home?","it":"I tuoi genitori sono a casa?","ipa":"i twɔ̣j ʤenitọri sọno a kạza?"},{"n":58,"zh":"不，他们出去了。","en":"No, they're out.","it":"No, sono usciti.","ipa":"nɔ, sọno uʃịti."},{"n":59,"zh":"你房间冷吗？","en":"Is it cold in your room?","it":"Fa freddo nella tua stanza?","ipa":"fa frɛ̣dːo nɛ̣lːa tụa stạnʦa?"},{"n":60,"zh":"是的，有点冷。","en":"Yes, a little.","it":"Sì, un po'.","ipa":"sị, un pɔ."},{"n":61,"zh":"你的鞋很漂亮，是新的吗？","en":"Your shoes are nice. Are they new?","it":"Le tue scarpe sono belle. Sono nuove?","ipa":"le tụe skạrpe sọno bɛ̣lːe. sọno nwɔ̣ve?"},{"n":62,"zh":"是的，是新的。","en":"Yes, they are.","it":"Sì, sono nuove.","ipa":"sị, sọno nwɔ̣ve."},{"n":63,"zh":"你妈妈在哪里？她在家里吗？","en":"Where's your mother? Is she at home?","it":"Dov'è tua mamma? È a casa?","ipa":"dovɛ̣ tụa mạmːa? ɛ̣ a kạza?"},{"n":64,"zh":"你来自哪里？","en":"Where are you from?","it":"Da dove vieni?","ipa":"da dọve vjẹni?"},{"n":65,"zh":"我来自加拿大。","en":"I'm from Canada.","it":"Io vengo dal Canada.","ipa":"ịo vẹŋɡo dal kạnada."},{"n":66,"zh":"你的车是什么颜色的？","en":"What color is your car?","it":"Di che colore è la tua macchina?","ipa":"di ke kolọre ɛ̣ la tụa mạkːina?"},{"n":67,"zh":"是红色的。","en":"It's red.","it":"È rossa.","ipa":"ɛ̣ rọsːa."},{"n":68,"zh":"哈桑多大了？","en":"How old is Hassan?","it":"Quanti anni ha Hassan?","ipa":"kwạnti ạnːi a ạsːan?"},{"n":69,"zh":"他24岁（24）。","en":"He's twenty-four (24).","it":"Ha ventiquattro (24) anni.","ipa":"a ventikwạtːro (24) ạnːi."},{"n":70,"zh":"你父母怎么样？","en":"How are your parents?","it":"Come stanno i tuoi genitori?","ipa":"kọme stạnːo i twɔ̣j ʤenitọri?"},{"n":71,"zh":"他们很好。","en":"They're doing fine.","it":"Loro stanno bene.","ipa":"lọro stạnːo bẹne."},{"n":72,"zh":"这些明信片很漂亮，多少钱？","en":"These postcards are nice. How much are they?","it":"Queste cartoline sono carine. Quanto costano?","ipa":"kwɛ̣ste kartolịne sọno karịne. kwạnto kɔ̣stano?"},{"n":73,"zh":"一美元（USD），一英镑（GBP），一欧元（EUR）。","en":"They're a dollar (USD). They're a pound (GBP). They're a euro (EUR).","it":"Costano un dollaro. Costano una sterlina. Costano un euro.","ipa":"kɔ̣stano un dɔ̣lːaro. kɔ̣stano ụna sterlịna. kɔ̣stano un ẹwro."},{"n":74,"zh":"这家酒店不太好，为什么这么贵？","en":"This hotel isn't very good. Why is it so expensive?","it":"Quest'hotel non è molto bello. Perché è così caro?","ipa":"kwɛstotɛ̣l non ɛ̣ mọlto bɛ̣lːo. perkɛ̣ ɛ̣ kozị kạro?"},{"n":75,"zh":"你的电话号码是多少？","en":"What's your phone number?","it":"Qual è il tuo numero di telefono?","ipa":"kwạl ɛ̣ il tụo nụmero di telɛ̣fono?"},{"n":76,"zh":"那个男人是谁？","en":"Who's that man?","it":"Chi è quell'uomo?","ipa":"ki ɛ̣ kwɛlːwɔ̣mo?"},{"n":77,"zh":"他是大老板。","en":"He's the boss.","it":"È il capo.","ipa":"ɛ̣ il kạpo."},{"n":78,"zh":"你的朋友在哪里？","en":"Where's your friend?","it":"Dov'è la tua amica?","ipa":"dovɛ̣ la tụa amịka?"},{"n":79,"zh":"她在洗手间。","en":"She's in the bathroom.","it":"È in bagno.","ipa":"ɛ̣ in bạɲːo."},{"n":80,"zh":"你父亲怎么样？","en":"How's your father?","it":"Come sta tuo padre?","ipa":"kọme sta tụo pạdre?"},{"n":81,"zh":"他做得很好。","en":"He's doing great.","it":"Sta benissimo.","ipa":"sta benịsːimo."},{"n":82,"zh":"你累了吗？","en":"Are you tired?","it":"Sei stanco (♀stanca)?","ipa":"sɛ̣j stạŋko (♀stạŋka)?"},{"n":83,"zh":"是的，我累了。","en":"Yes, I am [tired].","it":"Sì, sono stanco (♀stanca).","ipa":"sị, sọno stạŋko (♀stạŋka)."},{"n":84,"zh":"你饿了吗？","en":"Are you hungry?","it":"Hai fame?","ipa":"ạj fạme?"},{"n":85,"zh":"不饿，但我渴了。","en":"No, but I'm thirsty.","it":"No, però ho sete.","ipa":"nɔ, perɔ̣ ɔ sẹte."},{"n":86,"zh":"你的朋友是中国人吗？","en":"Is your friend Chinese?","it":"Il tuo amico è cinese?","ipa":"il tụo amịko ɛ̣ ʧinẹze?"},{"n":87,"zh":"是的，他是中国人。","en":"Yes, he is [Chinese].","it":"Sì, è cinese.","ipa":"sị, ɛ̣ ʧinẹze."},{"n":88,"zh":"这些是你的钥匙吗？","en":"Are these your keys?","it":"Queste sono le tue chiavi?","ipa":"kwɛ̣ste sọno le tụe kjạvi?"},{"n":89,"zh":"是的，它们是我的。","en":"Yes, they are [mine].","it":"Sì, sono le mie.","ipa":"sị, sọno le mịe."},{"n":90,"zh":"那是我的座位。","en":"That's my seat.","it":"Questo è il mio posto.","ipa":"kwɛ̣sto ɛ̣ il mịo pɔ̣sto."},{"n":91,"zh":"不，不是你的。","en":"No, it isn't [yours].","it":"No, non è il tuo.","ipa":"nɔ, non ɛ̣ il tụo."},{"n":92,"zh":"相机在哪里？","en":"Where's the camera?","it":"Dov'è la macchina fotografica?","ipa":"dovɛ̣ la mạkːina fotoɡrạfika?"},{"n":93,"zh":"它在你的包里。","en":"It's in your bag.","it":"È nella tua borsa.","ipa":"ɛ̣ nɛ̣lːa tụa bọrsa."},{"n":94,"zh":"你的车是蓝色的吗？","en":"Is your car blue?","it":"La tua macchina è blu?","ipa":"la tụa mạkːina ɛ̣ blu?"},{"n":95,"zh":"不，它是黑色的。","en":"No, it's black.","it":"No, è nera.","ipa":"nɔ, ɛ̣ nẹra."},{"n":96,"zh":"莉萨是来自多伦多的吗？","en":"Is Lisa from Toronto?","it":"Lisa è di Toronto?","ipa":"lịza ɛ̣ di torọnto?"},{"n":97,"zh":"不，她是美国人。","en":"No, she's American.","it":"No, è americana.","ipa":"nɔ, ɛ̣ amerikạna."},{"n":98,"zh":"我迟到了吗？","en":"Am I late?","it":"Sono in ritardo?","ipa":"sọno in ritạrdo?"},{"n":99,"zh":"是的，你迟到了。","en":"Yes, you are [late].","it":"Sì, sei in ritardo.","ipa":"sị, sɛ̣j in ritạrdo."},{"n":100,"zh":"莉拉是哪里人？","en":"Where's Layla from?","it":"Di dov'è Layla?","ipa":"di dovɛ̣ (…)?"}]},{"lesson":2,"range":[101,200],"items":[{"n":101,"zh":"她来自伦敦。","en":"She's from London.","it":"È di Londra.","ipa":"ɛ̣ di lọndra."},{"n":102,"zh":"你的包是什么颜色的？","en":"What color is your bag?","it":"Di che colore è la tua borsa?","ipa":"di ke kolọre ɛ̣ la tụa bọrsa?"},{"n":103,"zh":"是黑色的。","en":"It's black.","it":"È nera.","ipa":"ɛ̣ nẹra."},{"n":104,"zh":"你饿吗？","en":"Are you hungry?","it":"Hai fame?","ipa":"ạj fạme?"},{"n":105,"zh":"不，我不饿。","en":"No, I'm not [hungry].","it":"No, non ho fame.","ipa":"nɔ, non ɔ fạme."},{"n":106,"zh":"约翰怎么样？","en":"How's John?","it":"Come sta John?","ipa":"kọme sta jɔ̣n?"},{"n":107,"zh":"他很好。","en":"He's fine.","it":"Sta bene.","ipa":"sta bẹne."},{"n":108,"zh":"那个女人是谁？","en":"Who's that woman?","it":"Chi è quella donna?","ipa":"ki ɛ̣ kwɛ̣lːa dɔ̣nːa?"},{"n":109,"zh":"她是我的妹妹。","en":"She's my sister.","it":"È mia sorella.","ipa":"ɛ̣ mịa sorɛ̣lːa."},{"n":110,"zh":"你妈妈在家吗？","en":"Is your mother at home?","it":"Tua mamma è a casa?","ipa":"tụa mạmːa ɛ̣ a kạza?"},{"n":111,"zh":"你父母好吗？","en":"How are your parents?","it":"Come stanno i tuoi genitori?","ipa":"kọme stạnːo i twɔ̣j ʤenitọri?"},{"n":112,"zh":"你的工作有趣吗？","en":"Is your job interesting?","it":"Il tuo lavoro è interessante?","ipa":"il tụo lavọro ɛ̣ interesːạnte?"},{"n":113,"zh":"今天商店开门了吗？","en":"Are the stores open today?","it":"I negozi sono aperti oggi?","ipa":"i neɡɔ̣ʦi sọno apɛ̣rti ɔ̣dʤi?"},{"n":114,"zh":"你来自哪里？","en":"Where are you from?","it":"Di dove sei?","ipa":"di dọve sɛ̣j?"},{"n":115,"zh":"你对运动感兴趣吗？","en":"Are you interested in sports?","it":"Ti interessano gli sport?","ipa":"t‿ interɛ̣sːano ʎːi spɔrt?"},{"n":116,"zh":"邮局离这里近吗？","en":"Is the post office near here?","it":"L'ufficio postale è qui vicino?","ipa":"lufːịʧo postạl‿ ɛ̣ kwị viʧịno?"},{"n":117,"zh":"你的孩子们在学校吗？","en":"Are your children at school?","it":"I tuoi figli sono a scuola?","ipa":"i twɔ̣j fịʎːi sọno a skwɔ̣la?"},{"n":118,"zh":"你为什么迟到？","en":"Why are you late?","it":"Perché sei in ritardo?","ipa":"perkɛ̣ sɛ̣j in ritạrdo?"},{"n":119,"zh":"你的孩子们怎么样？","en":"How are your children?","it":"Come stanno i tuoi figli?","ipa":"kọme stạnːo i twɔ̣j fịʎːi?"},{"n":120,"zh":"他们都很好。","en":"They're fine.","it":"Stanno bene.","ipa":"stạnːo bẹne."},{"n":121,"zh":"公交站在哪里？","en":"Where's the bus stop?","it":"Dov'è la fermata dell'autobus?","ipa":"dovɛ̣ la fermạta dɛlːạwtobus?"},{"n":122,"zh":"在红绿灯那里。","en":"At the stoplight.","it":"Al semaforo.","ipa":"al semạforo."},{"n":123,"zh":"你的孩子多大了？","en":"How old are your children?","it":"Quanti anni hanno i tuoi figli?","ipa":"kwạnti ạnːi ạnːo i twɔ̣j fịʎːi?"},{"n":124,"zh":"五岁、七岁和十岁。","en":"Five (5), seven (7), and ten (10).","it":"Cinque (5), sette (7) e dieci (10) anni.","ipa":"ʧịŋkwe (5), sɛ̣tːe (7) e djẹʧi (10) ạnːi."},{"n":125,"zh":"这些橙子多少钱？","en":"How much are these oranges?","it":"Quanto costano queste arance?","ipa":"kwạnto kɔ̣stano kwɛ̣ste arạɲʧe?"},{"n":126,"zh":"一磅一块五（1.50美元/磅）。它们是2.3欧元每公斤。","en":"A dollar fifty a pound ($1.50/lb). They're 2.3 Euros a kilo.","it":"Un dollaro e cinquanta alla libbra. Due euro e trenta centesimi al chilo.","ipa":"un dɔ̣lːaro e ʧiŋkwạnt‿ ạlːa lịbːra. dụe ẹwro e trɛ̣nta ʧentẹzimi al kịlo."},{"n":127,"zh":"你最喜欢的运动是什么？","en":"What's your favorite sport?","it":"Qual è il tuo sport preferito?","ipa":"kwạl ɛ̣ il tụo spɔrt preferịto?"},{"n":128,"zh":"我最喜欢的运动是滑雪。","en":"My favorite sport is skiing.","it":"Il mio sport preferito è lo sci.","ipa":"il mịo spɔrt preferịto ɛ̣ lo ʃi."},{"n":129,"zh":"这张照片里的人是谁？","en":"Who's the man in this photo?","it":"Chi è l'uomo nella foto?","ipa":"ki ɛ̣ lwɔ̣mo nɛ̣lːa fọto?"},{"n":130,"zh":"那是我父亲。","en":"That's my father.","it":"È mio padre.","ipa":"ɛ̣ mịo pạdre."},{"n":131,"zh":"你新鞋是什么颜色的？","en":"What color are your new shoes?","it":"Di che colore sono le tue scarpe nuove?","ipa":"di ke kolọre sọno le tụe skạrpe nwɔ̣ve?"},{"n":132,"zh":"是黑色的。","en":"They're black.","it":"Sono nere.","ipa":"sọno nẹre."},{"n":133,"zh":"你叫什么名字？","en":"What's your name?","it":"Come ti chiami?","ipa":"kọme ti kjạmi?"},{"n":134,"zh":"我叫布莱恩。","en":"I'm Brian.","it":"Mi chiamo Brian.","ipa":"mi kjạmo (…)."},{"n":135,"zh":"你是澳大利亚人吗？","en":"Are you Australian?","it":"Sei australiano (♀australiana)?","ipa":"sɛ̣j awstraljạno (♀awstraljạna)?"},{"n":136,"zh":"不是，我是加拿大人。","en":"No, I'm Canadian.","it":"No, sono canadese.","ipa":"nɔ, sọno kanadẹze."},{"n":137,"zh":"你多大了？","en":"How old are you?","it":"Quanti anni hai?","ipa":"kwạnti ạnːi ạj?"},{"n":138,"zh":"我33岁。","en":"I'm thirty-three.","it":"Ho trentatrè (33) anni.","ipa":"ɔ trentatrɛ̣ (33) ạnːi."},{"n":139,"zh":"你是老师吗？","en":"Are you a teacher?","it":"Sei insegnante? > Fai l'insegnante?","ipa":"sɛ̣j inseɲːạnte? > fạj linseɲːạnte?"},{"n":140,"zh":"不是，我是医生。","en":"No, I'm a doctor.","it":"No, sono medico. > No, faccio il medico.","ipa":"nɔ, sọno mẹdiko. > nɔ, fạtʧo il mẹdiko."},{"n":141,"zh":"","en":"Are you married?","it":"Sei sposato (♀sposata)?","ipa":"sɛ̣j spozạto (♀spozạta)?"},{"n":142,"zh":"","en":"Yes, I am [married].","it":"Sì, sono sposato (♀sposata).","ipa":"sị, sọno spozạto (♀spozạta)."},{"n":143,"zh":"","en":"Is your wife a doctor?","it":"Tua moglie fa il medico? > Tua moglie è medico?","ipa":"tụa mọʎːje fa il mẹdiko? > tụa mọʎːj‿ ɛ̣ mẹdiko?"},{"n":144,"zh":"","en":"No, she's a teacher.","it":"No, fa l'insegnante. > No, è insegnante.","ipa":"nɔ, fa linseɲːạnte. > nɔ, ɛ̣ inseɲːạnte."},{"n":145,"zh":"","en":"Where is she from?","it":"Di dov'è lei?","ipa":"di dovɛ̣ lɛ̣j?"},{"n":146,"zh":"","en":"She's from Mexico.","it":"È messicana.","ipa":"ɛ̣ mesːikạna."},{"n":147,"zh":"","en":"What's her name?","it":"Come si chiama?","ipa":"kọme si kjạma?"},{"n":148,"zh":"","en":"Her name is Barbara.","it":"Si chiama Barbara.","ipa":"si kjạma bạrbara."},{"n":149,"zh":"","en":"How old is she?","it":"Quanti anni ha?","ipa":"kwạnti ạnːi a?"},{"n":150,"zh":"","en":"She's twenty-six (26).","it":"Lei ha ventisei (26) anni.","ipa":"lɛ̣j a ventisɛ̣j (26) ạnːi."},{"n":151,"zh":"","en":"Are you married? — No, I'm not.","it":"Sei sposato (♀sposata)? No, non sono sposato (♀sposata).","ipa":"sɛ̣j spozạto (♀spozạta)? nɔ, non sọno spozạto (♀spozạta)."},{"n":152,"zh":"","en":"Are you thirsty? — Yes, I am.","it":"Tu hai sete? Sì, ho sete.","ipa":"tu ạj sẹte? sị, ɔ sẹte."},{"n":153,"zh":"","en":"Is it cold today? — No, it isn't.","it":"Fa freddo oggi? No, non fa freddo.","ipa":"fa frɛ̣dː‿ ɔ̣dʤi? nɔ, non fa frɛ̣dːo."},{"n":154,"zh":"","en":"Are your hands cold? — No, they aren't.","it":"Le tue mani sono fredde? No, non lo sono.","ipa":"le tụe mạni sọno frɛ̣dːe? nɔ, non lo sọno."},{"n":155,"zh":"","en":"Is it dark now? — Yes, it is.","it":"È buio adesso? Sì, è buio.","ipa":"ɛ̣ bụjo adɛ̣sːo? sị, ɛ̣ bụjo."},{"n":156,"zh":"","en":"Are you a teacher? — Yes, I am.","it":"Tu sei insegnante? Sì, sono insegnante.","ipa":"tu sɛ̣j inseɲːạnte? sị, sọno inseɲːạnte."},{"n":157,"zh":"","en":"I'm working. I'm not watching TV.","it":"Io sto lavorando, non sto guardando la televisione.","ipa":"ịo stɔ lavorạndo, non stɔ ɡwardạndo la televizjọne."},{"n":158,"zh":"","en":"Barbara is reading a newspaper.","it":"Barbara sta leggendo un giornale.","ipa":"bạrbara sta ledʤɛ̣ndo un ʤornạle."},{"n":159,"zh":"","en":"She isn't eating.","it":"Lei non sta mangiando.","ipa":"lɛ̣j non sta maɲʤạndo."},{"n":160,"zh":"","en":"The phone is ringing.","it":"Il telefono sta squillando.","ipa":"il telɛ̣fono sta skwilːạndo."},{"n":161,"zh":"","en":"We're having dinner.","it":"Noi stiamo cenando.","ipa":"nọj stjạmo ʧenạndo."},{"n":162,"zh":"","en":"You're not listening to me.","it":"Tu non mi stai ascoltando.","ipa":"tu non mi stạj askoltạndo."},{"n":163,"zh":"","en":"The children are doing their homework.","it":"I bambini stanno facendo i compiti.","ipa":"i bambịni stạnːo faʧɛ̣ndo i kọmpiti."},{"n":164,"zh":"","en":"Please be quiet. I'm working.","it":"Fai piano, per favore. Sto lavorando.","ipa":"fạj pjạno, pɛr favọre. stɔ lavorạndo."},{"n":165,"zh":"","en":"The weather's nice. It's not raining.","it":"Il tempo è bello. Non sta piovendo.","ipa":"il tẹmpo ɛ̣ bɛ̣lːo. non sta pjovɛ̣ndo."},{"n":166,"zh":"","en":"Where are the children? — They're playing in the park.","it":"Dove sono i bambini? — Stanno giocando nel parco.","ipa":"dọve sọno i bambịni? — stạnːo ʤokạndo nɛl pạrko."},{"n":167,"zh":"","en":"We're having dinner now. Can I call you later?","it":"Noi stiamo cenando in questo momento. Posso chiamarti più tardi?","ipa":"nọj stjạmo ʧenạndo in kwɛ̣sto momɛ̣nto. pɔ̣sːo kjamạrti piụ tạrdi?"},{"n":168,"zh":"","en":"I'm not watching TV.","it":"Io non sto guardando la televisione.","ipa":"ịo non stɔ ɡwardạndo la televizjọne."},{"n":169,"zh":"","en":"She's eating an apple.","it":"Lei mangia una mela.","ipa":"lɛ̣j mạɲʤa ụna mẹla."},{"n":170,"zh":"","en":"He's waiting for a bus.","it":"Lui aspetta un autobus.","ipa":"lụj aspɛ̣tːa un ạwtobus."},{"n":171,"zh":"","en":"They're playing football.","it":"Loro giocano a calcio.","ipa":"lọro ʤọkano a kạlʧo."},{"n":172,"zh":"","en":"He's lying on the floor.","it":"Lui è sdraiato sul pavimento.","ipa":"lụj ɛ̣ zdrajạto sul pavimɛ̣nto."},{"n":173,"zh":"","en":"We're eating breakfast.","it":"Noi stiamo facendo colazione.","ipa":"nọj stjạmo faʧɛ̣ndo kolaʦjọne."},{"n":174,"zh":"","en":"She's sitting on the table.","it":"Lei è seduta sul tavolo.","ipa":"lɛ̣j ɛ̣ sedụta sul tạvolo."},{"n":175,"zh":"","en":"He's in the kitchen. He's cooking.","it":"Lui è in cucina. Sta cucinando.","ipa":"lụj ɛ̣ in kuʧịna. sta kuʧinạndo."},{"n":176,"zh":"","en":"You stepped on my foot. — I'm sorry.","it":"Tu mi hai pestato il piede. — Scusami.","ipa":"tu mi ạj pestạto il pjẹde. — skụzami."},{"n":177,"zh":"","en":"Somebody is swimming in the river.","it":"Qualcuno sta nuotando nel fiume.","ipa":"kwalkụno sta nwotạndo nɛl fiụme."},{"n":178,"zh":"","en":"We're here on vacation. We're staying at a hotel on the beach.","it":"Siamo qui in vacanza. Alloggiamo all'hotel sulla spiaggia.","ipa":"sjạmo kwị in vakạnʦa. alːodʤạmo alːotɛ̣l sụlːa spjạdʤa."},{"n":179,"zh":"","en":"Where's Tara? — She's taking a shower.","it":"Dov'è Tara? — Sta facendo la doccia.","ipa":"dovɛ̣ tạra? — sta faʧɛ̣ndo la dɔ̣tʧa."},{"n":180,"zh":"","en":"They're building a new hotel downtown.","it":"Stanno costruendo un nuovo albergo in centro città.","ipa":"stạnːo kostrwɛ̣ndo un nwɔ̣vo albɛ̣rɡo in ʧɛ̣ntro ʧitːạ."},{"n":181,"zh":"","en":"I'm leaving now, goodbye.","it":"Sto andando via. Arrivederci.","ipa":"stɔ andạndo vịa. arːivedẹrʧi."},{"n":182,"zh":"","en":"She isn't having dinner.","it":"Lei non sta cenando.","ipa":"lɛ̣j non sta ʧenạndo."},{"n":183,"zh":"","en":"She's watching TV.","it":"Lei sta guardando la televisione.","ipa":"lɛ̣j sta ɡwardạndo la televizjọne."},{"n":184,"zh":"","en":"She's sitting on the floor.","it":"Lei è seduta per terra.","ipa":"lɛ̣j ɛ̣ sedụta pɛr tɛ̣rːa."},{"n":185,"zh":"","en":"She's reading a book.","it":"Lei sta leggendo un libro.","ipa":"lɛ̣j sta ledʤɛ̣ndo un lịbro."},{"n":186,"zh":"","en":"He's not playing the piano.","it":"Lui non sta suonando il pianoforte.","ipa":"lụj non sta swonạndo il pjanofɔ̣rte."},{"n":187,"zh":"","en":"He's laughing.","it":"Lui sta ridendo.","ipa":"lụj sta ridɛ̣ndo."},{"n":188,"zh":"","en":"He's wearing a hat.","it":"Lui indossa un cappello.","ipa":"lụj indɔ̣sːa un kapːɛ̣lːo."},{"n":189,"zh":"","en":"He's not writing a letter.","it":"Lui non sta scrivendo una lettera.","ipa":"lụj non sta skrivɛ̣ndo ụna lɛ̣tːera."},{"n":190,"zh":"","en":"I'm not washing my hair.","it":"Io non mi sto lavando i capelli.","ipa":"ịo non mi stɔ lavạndo i kapɛ̣lːi."},{"n":191,"zh":"","en":"It isn't snowing.","it":"Non sta nevicando.","ipa":"non sta nevikạndo."},{"n":192,"zh":"","en":"I'm sitting on a chair.","it":"Io sono seduto (♀seduta) su una sedia.","ipa":"ịo sọno sedụto (♀sedụta) s‿ ụna sẹdja."},{"n":193,"zh":"","en":"I'm not eating.","it":"Io non sto mangiando.","ipa":"ịo non stɔ maɲʤạndo."},{"n":194,"zh":"","en":"It's raining.","it":"Sta piovendo.","ipa":"sta pjovɛ̣ndo."},{"n":195,"zh":"","en":"I'm not studying english.","it":"Non sto studiando inglese.","ipa":"non stɔ studjạndo inɡlẹze."},{"n":196,"zh":"","en":"I'm listening to music.","it":"Sto ascoltando la musica.","ipa":"stɔ askoltạndo la mụzika."},{"n":197,"zh":"","en":"The sun isn't shining.","it":"Il sole non sta splendendo.","ipa":"il sọle non sta splendɛ̣ndo."},{"n":198,"zh":"","en":"I'm wearing my shoes.","it":"Sto indassando le mie scarpe.","ipa":"stɔ indosːạndo le mịe skạrpe."},{"n":199,"zh":"","en":"I'm not reading the newspaper.","it":"Non sto leggendo il giornale.","ipa":"non stɔ ledʤɛ̣ndo il ʤornạle."},{"n":200,"zh":"","en":"Are you feeling okay?","it":"Ti senti bene?","ipa":"ti sɛ̣nti bẹne?"}]},{"lesson":3,"range":[201,300],"items":[{"n":201,"zh":"","en":"Yes, I'm fine.","it":"Sì, sto bene.","ipa":"sị, stɔ bẹne."},{"n":202,"zh":"","en":"Is it raining?","it":"Sta piovendo?","ipa":"sta pjovɛ̣ndo?"},{"n":203,"zh":"","en":"Yes, take an umbrella.","it":"Sì, prendi un ombrello.","ipa":"sị, prɛ̣ndi un ombrɛ̣lːo."},{"n":204,"zh":"","en":"Why are you wearing a coat?","it":"Perché indossi un cappotto?","ipa":"perkɛ̣ indɔ̣sːi un kapːɔ̣tːo?"},{"n":205,"zh":"","en":"It's not cold.","it":"Non fa freddo.","ipa":"non fa frɛ̣dːo."},{"n":206,"zh":"","en":"What's he doing?","it":"Lui cosa sta facendo?","ipa":"lụj kɔ̣za sta faʧɛ̣ndo?"},{"n":207,"zh":"","en":"He's reading the newspaper.","it":"Sta leggendo il giornale.","ipa":"sta ledʤɛ̣ndo il ʤornạle."},{"n":208,"zh":"","en":"What are the children doing?","it":"Cosa stanno facendo i bambini?","ipa":"kɔ̣za stạnːo faʧɛ̣ndo i bambịni?"},{"n":209,"zh":"","en":"They're watching TV.","it":"Stanno guardando la tivù.","ipa":"stạnːo ɡwardạndo la tivụ."},{"n":210,"zh":"","en":"Where's she going?","it":"Lei dove sta andando?","ipa":"lɛ̣j dọve st‿ andạndo?"},{"n":211,"zh":"","en":"Who are you waiting for?","it":"Chi stai aspettando?","ipa":"ki stạj aspetːạndo?"},{"n":212,"zh":"","en":"Are you waiting for John?","it":"Stai aspettando John?","ipa":"stạj aspetːạndo jɔ̣n?"},{"n":213,"zh":"","en":"Are you leaving now?","it":"Stai andando via?","ipa":"stạj andạndo vịa?"},{"n":214,"zh":"","en":"Yes, I am [leaving now]","it":"Sì, sto andando via.","ipa":"sị, stɔ andạndo vịa."},{"n":215,"zh":"","en":"Is Chris working today?","it":"Christian lavora oggi?","ipa":"krịstjan lavọra ɔ̣dʤi?"},{"n":216,"zh":"","en":"No, he isn't [working].","it":"No, oggi non lavora.","ipa":"nɔ, ɔ̣dʤi non lavọra."},{"n":217,"zh":"","en":"Is the sun shining?","it":"C'è il sole?","ipa":"ʧɛ̣ il sọle?"},{"n":218,"zh":"","en":"Yes, it is [the sun is shining].","it":"Sì, c'è il sole.","ipa":"sị, ʧɛ̣ il sọle."},{"n":219,"zh":"","en":"Are your friends staying at a hotel?","it":"I tuoi amici alloggiano in un albergo?","ipa":"i twɔ̣j amịʧi alːọdʤano in un albɛ̣rɡo?"},{"n":220,"zh":"","en":"No, they're staying with me.","it":"No, stanno da me.","ipa":"nɔ, stạnːo da mɛ."},{"n":221,"zh":"","en":"Are you watching TV?","it":"Stai guardando la televisione?","ipa":"stạj ɡwardạndo la televizjọne?"},{"n":222,"zh":"","en":"No, you can turn it off.","it":"No, puoi spegnerla.","ipa":"nɔ, pwɔ̣j spẹɲːerla."},{"n":223,"zh":"","en":"Are you leaving now?","it":"Stai andando via adesso?","ipa":"stạj andạndo vịa adɛ̣sːo?"},{"n":224,"zh":"","en":"Yes, see you tomorrow.","it":"Sì, ci vediamo domani.","ipa":"sị, ʧi vedjạmo domạni."},{"n":225,"zh":"","en":"Is it raining?","it":"Piove?","ipa":"pjɔ̣ve?"},{"n":226,"zh":"","en":"No, not right now.","it":"No, non in questo momento.","ipa":"nɔ, non in kwɛ̣sto momɛ̣nto."},{"n":227,"zh":"","en":"Are you enjoying the movie?","it":"Ti sta piacendo il film?","ipa":"ti sta pjaʧɛ̣ndo il film?"},{"n":228,"zh":"","en":"Yes, it's very funny.","it":"Sì, è molto divertente.","ipa":"sị, ɛ̣ mọlto divertɛ̣nte."},{"n":229,"zh":"","en":"Does the clock work?","it":"L'orologio funziona?","ipa":"lorolɔ̣ʤo funʦjọna?"},{"n":230,"zh":"","en":"No, it's broken.","it":"No, è rotto.","ipa":"nɔ, ɛ̣ rọtːo."},{"n":231,"zh":"","en":"Are you waiting for a bus?","it":"Stai aspettando l'autobus?","ipa":"stạj aspetːạndo lạwtobus?"},{"n":232,"zh":"","en":"No, I'm waiting for a taxi.","it":"No, sto aspettando il taxi.","ipa":"nɔ, stɔ aspetːạndo il tạksi."},{"n":233,"zh":"","en":"What are you reading?","it":"Cosa stai leggendo?","ipa":"kɔ̣za stạj ledʤɛ̣ndo?"},{"n":234,"zh":"","en":"Where is she going?","it":"Lei dove sta andando?","ipa":"lɛ̣j dọve st‿ andạndo?"},{"n":235,"zh":"","en":"What are you eating?","it":"Cosa stai mangiando?","ipa":"kɔ̣za stạj maɲʤạndo?"},{"n":236,"zh":"","en":"Why are you crying?","it":"Perché stai piangendo?","ipa":"perkɛ̣ stạj pjaɲʤɛ̣ndo?"},{"n":237,"zh":"","en":"What are they looking at?","it":"Che cosa stanno guardando?","ipa":"ke kɔ̣za stạnːo ɡwardạndo?"},{"n":238,"zh":"","en":"Why is he laughing?","it":"Perché lui ride?","ipa":"perkɛ̣ lụj rịde?"},{"n":239,"zh":"","en":"Are you listening to me?","it":"Mi stai ascoltando?","ipa":"mi stạj askoltạndo?"},{"n":240,"zh":"","en":"Where are your friends going?","it":"Dove stanno andando i tuoi amici?","ipa":"dọve stạnːo andạndo i twɔ̣j amịʧi?"},{"n":241,"zh":"","en":"Are your parents watching TV?","it":"I tuoi genitori stanno guardando la televisione?","ipa":"i twɔ̣j ʤenitọri stạnːo ɡwardạndo la televizjọne?"},{"n":242,"zh":"","en":"What's Claire cooking?","it":"Che cosa sta cucinando Claire?","ipa":"ke kɔ̣za sta kuʧinạndo (…)?"},{"n":243,"zh":"","en":"Why are you looking at me?","it":"Perché mi stai guardando?","ipa":"perkɛ̣ mi stạj ɡwardạndo?"},{"n":244,"zh":"","en":"Is the bus coming?","it":"L'autobus sta arrivando?","ipa":"lạwtobus st‿ arːivạndo?"},{"n":245,"zh":"","en":"Are you watching TV?","it":"Stai guardando la tele?","ipa":"stạj ɡwardạndo la tẹle?"},{"n":246,"zh":"","en":"No, I'm not [watching TV].","it":"No, non la sto guardando.","ipa":"nɔ, non la stɔ ɡwardạndo."},{"n":247,"zh":"","en":"Are you wearing a watch?","it":"Porti un orologio?","ipa":"pọrti un orolɔ̣ʤo?"},{"n":248,"zh":"","en":"No, I'm not [wearing a watch].","it":"No, non lo porto.","ipa":"nɔ, non lo pọrto."},{"n":249,"zh":"","en":"Is he eating something?","it":"Lui sta mangiando qualcosa?","ipa":"lụj sta maɲʤạndo kwalkɔ̣za?"},{"n":250,"zh":"","en":"No, he isn't [eating].","it":"No, non sta mangiando niente.","ipa":"nɔ, non sta maɲʤạndo njɛ̣nte."},{"n":251,"zh":"","en":"Is it raining?","it":"Sta piovendo?","ipa":"sta pjovɛ̣ndo?"},{"n":252,"zh":"","en":"No, it isn't [raining].","it":"No, non sta piovendo.","ipa":"nɔ, non sta pjovɛ̣ndo."},{"n":253,"zh":"","en":"Are you sitting on the floor?","it":"Sei seduto (♀seduta) per terra?","ipa":"sɛ̣j sedụto (♀sedụta) pɛr tɛ̣rːa?"},{"n":254,"zh":"","en":"Yes, I am [sitting on the floor].","it":"Sì, sono seduto (♀seduta) per terra.","ipa":"sị, sọno sedụto (♀sedụta) pɛr tɛ̣rːa."},{"n":255,"zh":"","en":"Are you feeling all right?","it":"Ti senti bene?","ipa":"ti sɛ̣nti bẹne?"},{"n":256,"zh":"","en":"No, I'm not [feeling all right].","it":"No, non mi sento bene.","ipa":"nɔ, non mi sɛ̣nto bẹne."},{"n":257,"zh":"","en":"They're looking at their books.","it":"Loro stanno rileggendo i loro libri.","ipa":"lọro stạnːo riledʤɛ̣ndo i lọro lịbri."},{"n":258,"zh":"","en":"They read a lot.","it":"Loro leggono molto.","ipa":"lọro lẹɡːono mọlto."},{"n":259,"zh":"","en":"He's eating ice cream.","it":"Lui sta mangiando il gelato.","ipa":"lụj sta maɲʤạndo il ʤelạto."},{"n":260,"zh":"","en":"He likes ice cream.","it":"Gli piace il gelato.","ipa":"ʎːi pjạʧe il ʤelạto."},{"n":261,"zh":"","en":"I work in an office.","it":"Lavoro in ufficio.","ipa":"lavọro in ufːịʧo."},{"n":262,"zh":"","en":"My brother works in a bank.","it":"Mio fratello lavora in banca.","ipa":"mịo fratɛ̣lːo lavọra in bạŋka."},{"n":263,"zh":"","en":"She lives in New York.","it":"Lei vive a New York.","ipa":"lɛ̣j vịve a (…) (…)."},{"n":264,"zh":"","en":"Her parents live in Chicago.","it":"I suoi genitori vivono a Chicago.","ipa":"i swɔ̣j ʤenitọri vịvono a (…)."},{"n":265,"zh":"","en":"It rains a lot in the winter.","it":"Piove molto in inverno.","ipa":"pjɔ̣ve mọlto in invɛ̣rno."},{"n":266,"zh":"","en":"Mike has lunch at home every day.","it":"Tutti i giorni, Mike pranza a casa.","ipa":"tụtː‿ i ʤọrni, (…) prạnʦ‿ a kạza."},{"n":267,"zh":"","en":"I like big cities.","it":"Mi piacciono le grandi città.","ipa":"mi pjạtʧono le ɡrạndi ʧitːạ."},{"n":268,"zh":"","en":"Your English is good.","it":"Il tuo inglese è buono.","ipa":"il tụo inɡlẹz‿ ɛ̣ bwɔ̣no."},{"n":269,"zh":"","en":"You speak English very well.","it":"Parli inglese molto bene.","ipa":"pạrl‿ inɡlẹze mọlto bẹne."},{"n":270,"zh":"","en":"Minoru works very hard.","it":"Minoru lavora davvero sodo.","ipa":"minɔ̣ru lavọra davːẹro sɔ̣do."},{"n":271,"zh":"","en":"He starts at seven thirty (7:30).","it":"Lui inizia alle sette e trenta (7:30).","ipa":"lụj inịʦj‿ ạlːe sɛ̣tː‿ e trɛ̣nta (7:30)."},{"n":272,"zh":"","en":"And he finishes at eight [o'clock] (8:00) at night.","it":"E finisce alle otto (8:00) [in punto] la sera.","ipa":"e finịʃe ạlːe ɔ̣tːo (8:00) [in pụnto] la sẹra."},{"n":273,"zh":"","en":"The earth goes around the sun.","it":"La Terra gira attorno al Sole.","ipa":"la tɛ̣rːa ʤịra atːọrno al sọle."},{"n":274,"zh":"","en":"We do a lot of different things in our free time.","it":"Durante il nostro tempo libero, facciamo tante cose diverse.","ipa":"durạnte il nɔ̣stro tẹmpo lịbero, fatʧạmo tạnte kɔ̣ze divɛ̣rse."},{"n":275,"zh":"","en":"It costs a lot of money.","it":"Costa un sacco di soldi.","ipa":"kɔ̣sta un sạkːo di sɔ̣ldi."},{"n":276,"zh":"","en":"She always goes to work early.","it":"Lei va sempre presto al lavoro.","ipa":"lɛ̣j va sẹmpre prɛ̣sto al lavọro."},{"n":277,"zh":"","en":"She always gets to work early.","it":"Lei arriva sempre presto al lavoro.","ipa":"lɛ̣j arːịva sẹmpre prɛ̣sto al lavọro."},{"n":278,"zh":"","en":"We often sleep late on weekends.","it":"Spesso, nei fine settimana, noi andiamo a dormire tardi.","ipa":"spɛ̣sːo, nɛ̣j fịne setːimạna, nọj andjạmo a dormịre tạrdi."},{"n":279,"zh":"","en":"Megumi usually plays tennis on Sundays.","it":"Megumi di solito gioca a tennis la domenica.","ipa":"meɡụmi di sɔ̣lito ʤɔ̣k‿ a tɛ̣nːis la domẹnika."},{"n":280,"zh":"","en":"I sometimes walk to work, but not often.","it":"Qualche volta vado al lavoro a piedi, ma non spesso.","ipa":"kwạlke vɔ̣lta vạdo al lavọro a pjẹdi, ma non spɛ̣sːo."},{"n":281,"zh":"","en":"She reads.","it":"Lei legge.","ipa":"lɛ̣j lẹdʤe."},{"n":282,"zh":"","en":"He thinks.","it":"Lui pensa.","ipa":"lụj pẹnsa."},{"n":283,"zh":"","en":"It flies.","it":"Vola.","ipa":"vọla."},{"n":284,"zh":"","en":"He dances.","it":"Lui balla.","ipa":"lụj bạlːa."},{"n":285,"zh":"","en":"She has.","it":"Lei ha.","ipa":"lɛ̣j a."},{"n":286,"zh":"","en":"It finishes.","it":"Finisce.","ipa":"finịʃe."},{"n":287,"zh":"","en":"He plays the piano.","it":"Lui suona il pianoforte.","ipa":"lụj swɔ̣na il pjanofɔ̣rte."},{"n":288,"zh":"","en":"They live in a very big house.","it":"Loro vivono in una casa davvero grande.","ipa":"lọro vịvono in ụna kạza davːẹro ɡrạnde."},{"n":289,"zh":"","en":"She eats a lot of fruit.","it":"Lei mangia molta frutta.","ipa":"lɛ̣j mạɲʤa mọlta frụtːa."},{"n":290,"zh":"","en":"He plays tennis.","it":"Lui gioca a tennis.","ipa":"lụj ʤɔ̣k‿ a tɛ̣nːis."},{"n":291,"zh":"","en":"We go to the movies a lot.","it":"Noi andiamo spesso al cinema.","ipa":"nọj andjạmo spɛ̣sːo al ʧịnema."},{"n":292,"zh":"","en":"He sleeps seven (7) hours a night.","it":"Lui dorme sette (7) ore per notte.","ipa":"lụj dɔ̣rme sɛ̣tːe (7) ọre pɛr nɔ̣tːe."},{"n":293,"zh":"","en":"She speaks four (4) languages.","it":"Lei parla quattro (4) lingue.","ipa":"lɛ̣j pạrla kwạtːro (4) lịŋɡwe."},{"n":294,"zh":"","en":"Banks usually open at nine (9:00) in the morning.","it":"Le banche di solito aprono alle nove (9:00) di mattina.","ipa":"le bạŋke di sɔ̣lito ạprono ạlːe nɔ̣ve (9:00) di matːịna."},{"n":295,"zh":"","en":"The museum closes at five (5) in the afternoon.","it":"Il museo chiude alle cinque (5:00) di pomeriggio.","ipa":"il muzẹo kiụde ạlːe ʧịŋkwe (5:00) di pomerịdʤo."},{"n":296,"zh":"","en":"She's a teacher. She teaches math to children.","it":"Lei è insegnante. Insegna matematica ai bambini.","ipa":"lɛ̣j ɛ̣ inseɲːạnte. insẹɲːa matemạtik‿ ạj bambịni."},{"n":297,"zh":"","en":"My job is very interesting. I meet a lot of people.","it":"Il mio lavoro è davvero interessante. Incontro molte persone.","ipa":"il mịo lavọro ɛ̣ davːẹro interesːạnte. iŋkọntro mọlte persọne."},{"n":298,"zh":"","en":"His car is always dirty. He never cleans it.","it":"La sua macchina è sempre sporca. Non la pulisce mai.","ipa":"la sụa mạkːina ɛ̣ sẹmpre spọrka. non la pulịʃe mạj."},{"n":299,"zh":"","en":"Food is expensive. It costs a lot of money.","it":"Il cibo è caro. Costa molto.","ipa":"il ʧịbo ɛ̣ kạro. kɔ̣sta mọlto."},{"n":300,"zh":"","en":"Shoes are expensive. They cost a lot of money.","it":"Le scarpe sono care. Costano molti soldi.","ipa":"le skạrpe sọno kạre. kɔ̣stano mọlti sɔ̣ldi."}]},{"lesson":4,"range":[301,400],"items":[{"n":301,"zh":"","en":"Water boils at one hundred degrees (100º) Celsius.","it":"L'acqua bolle a cento (100) gradi centigradi.","ipa":"lạkwa bọlːe a ʧɛ̣nto () ɡrạdi ʧentịɡradi."},{"n":302,"zh":"","en":"We're good friends. I like her and she likes me.","it":"Noi siamo buoni amici. Lei mi piace e io piaccio a lei.","ipa":"nọj sjạmo bwɔ̣ni amịʧi. lɛ̣j mi pjạʧ‿ e ịo pjạtʧo a lɛ̣j."},{"n":303,"zh":"","en":"She always arrives early.","it":"Lei arriva sempre in anticipo.","ipa":"lɛ̣j arːịva sẹmpre in antịʧipo."},{"n":304,"zh":"","en":"I never go to the movies alone.","it":"Io non vado mai al cinema da solo.","ipa":"ịo non vạdo mạj al ʧịnema da sọlo."},{"n":305,"zh":"","en":"She always works hard.","it":"Lei lavora intensamente.","ipa":"lɛ̣j lavọra intensamɛ̣nte."},{"n":306,"zh":"","en":"Children usually like chocolate.","it":"Solitamente ai bambini piace la cioccolata.","ipa":"solitamɛ̣nte ạj bambịni pjạʧe la ʧokːolạta."},{"n":307,"zh":"","en":"She always enjoys parties.","it":"Le piace sempre far festa.","ipa":"le pjạʧe sẹmpre far fɛ̣sta."},{"n":308,"zh":"","en":"I often forget people's names.","it":"Spesso mi dimentico i nomi delle persone.","ipa":"spɛ̣sːo mi dimɛ̣ntiko i nọmi dɛ̣lːe persọne."},{"n":309,"zh":"","en":"He never watches TV.","it":"Lui non guarda mai la televisione.","ipa":"lụj non ɡwạrda mạj la televizjọne."},{"n":310,"zh":"","en":"We usually have dinner at six thirty (6:30).","it":"Di solito ceniamo alle sei (6:30) e mezza.","ipa":"di sɔ̣lito ʧenjạmo ạlːe sɛ̣j (6:30) e mɛ̣ʣa."},{"n":311,"zh":"","en":"She always wears nice clothes.","it":"Lei indossa sempre bei vestiti.","ipa":"lɛ̣j indɔ̣sːa sẹmpre bɛ̣j vestịti."},{"n":312,"zh":"","en":"I usually watch TV in the evening.","it":"Di solito, guardo la televisione la sera.","ipa":"di sɔ̣lito, ɡwạrdo la televizjọne la sẹra."},{"n":313,"zh":"","en":"I never read in bed.","it":"Non leggo mai a letto.","ipa":"non lẹɡːo mạj a lɛ̣tːo."},{"n":314,"zh":"","en":"I often get up before seven (7:00).","it":"Spesso mi alzo prima delle sette (7:00).","ipa":"spɛ̣sːo mi ạlʦo prịma dɛ̣lːe sɛ̣tːe (7:00)."},{"n":315,"zh":"","en":"I always go to work by bus.","it":"Io vado sempre al lavoro in autobus.","ipa":"ịo vạdo sẹmpre al lavọro in ạwtobus."},{"n":316,"zh":"","en":"I usually go to school by bus.","it":"Di solito vado a scuola con il bus.","ipa":"di sɔ̣lito vạdo a skwɔ̣la kon il bus."},{"n":317,"zh":"","en":"I always drink coffee in the morning.","it":"Io bevo sempre il caffè di mattina.","ipa":"ịo bẹvo sẹmpre il kafːɛ̣ di matːịna."},{"n":318,"zh":"","en":"She doesn't drink coffee.","it":"Lei non beve caffè.","ipa":"lɛ̣j non bẹve kafːɛ̣."},{"n":319,"zh":"","en":"He doesn't like his job.","it":"Non gli piace il suo lavoro.","ipa":"non ʎːi pjạʧe il sụo lavọro."},{"n":320,"zh":"","en":"I drink coffee, but I don't drink tea.","it":"Io bevo il caffè, ma non il tè.","ipa":"ịo bẹvo il kafːɛ̣, ma non il tɛ̣."},{"n":321,"zh":"","en":"She drinks tea, but she doesn't drink coffee.","it":"Lei beve il tè, ma non beve il caffè.","ipa":"lɛ̣j bẹve il tɛ̣, ma non bẹve il kafːɛ̣."},{"n":322,"zh":"","en":"You don't work very hard.","it":"Tu non lavori duramente.","ipa":"tu non lavọri duramɛ̣nte."},{"n":323,"zh":"","en":"We don't watch TV very often.","it":"Noi non guardiamo spesso la televisione.","ipa":"nọj non ɡwardjạmo spɛ̣sːo la televizjọne."},{"n":324,"zh":"","en":"The weather is usually nice.","it":"Generalmente, il tempo è bello.","ipa":"ʤeneralmɛ̣nte, il tẹmpo ɛ̣ bɛ̣lːo."},{"n":325,"zh":"","en":"It doesn't rain very often.","it":"Non piove spessissimo.","ipa":"non pjɔ̣ve spesːịsːimo."},{"n":326,"zh":"","en":"They don't know many people.","it":"Loro non conoscono molta gente.","ipa":"lọro non konọskono mọlta ʤɛ̣nte."},{"n":327,"zh":"","en":"They don't have many friends.","it":"Loro non hanno molti amici.","ipa":"lọro non ạnːo mọlti amịʧi."},{"n":328,"zh":"","en":"I don't like football.","it":"Non mi piace il calcio.","ipa":"non mi pjạʧe il kạlʧo."},{"n":329,"zh":"","en":"He doesn't like football.","it":"Non gli piace il calcio.","ipa":"non ʎːi pjạʧe il kạlʧo."},{"n":330,"zh":"","en":"I don't like him, and he doesn't like me.","it":"Lui non mi piace e io non piaccio a lui.","ipa":"lụj non mi pjạʧ‿ e ịo non pjạtʧo a lụj."},{"n":331,"zh":"","en":"My car doesn't use much gas.","it":"La mia macchina non consuma molta benzina.","ipa":"la mịa mạkːina non konsụma mọlta benzịna."},{"n":332,"zh":"","en":"Sometimes he's late, but not often.","it":"Qualche volta è in ritardo, ma non spesso.","ipa":"kwạlke vɔ̣lta ɛ̣ in ritạrdo, ma non spɛ̣sːo."},{"n":333,"zh":"","en":"I don't like to wash the car.","it":"Non mi piace lavare la macchina.","ipa":"non mi pjạʧe lavạre la mạkːina."},{"n":334,"zh":"","en":"I don't do it very often.","it":"Non lo faccio spesso.","ipa":"non lo fạtʧo spɛ̣sːo."},{"n":335,"zh":"","en":"She speaks Spanish, but she doesn't speak Italian.","it":"Lei parla lo spagnolo, ma non parla l'italiano.","ipa":"lɛ̣j pạrla lo spaɲːọlo, ma non pạrla litaljạno."},{"n":336,"zh":"","en":"He doesn't do his job very well.","it":"Lui non fa bene il suo lavoro.","ipa":"lụj non fa bẹne il sụo lavọro."},{"n":337,"zh":"","en":"She doesn't usually have breakfast.","it":"Di solito, lei non fa colazione.","ipa":"di sɔ̣lito, lɛ̣j non fa kolaʦjọne."},{"n":338,"zh":"","en":"I don't play the piano very well.","it":"Io non suono molto bene il pianoforte.","ipa":"ịo non swɔ̣no mọlto bẹne il pjanofɔ̣rte."},{"n":339,"zh":"","en":"She doesn't play the piano very well.","it":"Lei non suona molto bene il pianoforte.","ipa":"lɛ̣j non swɔ̣na mọlto bẹne il pjanofɔ̣rte."},{"n":340,"zh":"","en":"They don't know my phone number.","it":"Loro non conoscono il mio numero di telefono.","ipa":"lọro non konọskono il mịo nụmero di telɛ̣fono."},{"n":341,"zh":"","en":"We don't work very hard.","it":"Noi non lavoriamo sodo.","ipa":"nọj non lavorjạmo sɔ̣do."},{"n":342,"zh":"","en":"David doesn't have a car.","it":"Davide non possiede una macchina.","ipa":"dạvide non posːjẹde ụna mạkːina."},{"n":343,"zh":"","en":"You don't do the same thing every day.","it":"Tu non fai la stessa cosa ogni giorno.","ipa":"tu non fạj la stɛ̣sːa kɔ̣za ɔ̣ɲːi ʤọrno."},{"n":344,"zh":"","en":"They like classical music.","it":"A loro piace la musica classica.","ipa":"a lọro pjạʧe la mụzika klạsːika."},{"n":345,"zh":"","en":"She doesn't like jazz music.","it":"A lei non piace la musica jazz.","ipa":"a lɛ̣j non pjạʧe la mụzika ʤaz."},{"n":346,"zh":"","en":"I like rock and roll music.","it":"Mi piace il rock and roll.","ipa":"mi pjạʧe il (…) (…) (…)."},{"n":347,"zh":"","en":"They don't like boxing.","it":"A loro non piace il pugilato.","ipa":"a lọro non pjạʧe il puʤilạto."},{"n":348,"zh":"","en":"She doesn't like baseball.","it":"Non le piace il baseball.","ipa":"non le pjạʧe il (…)."},{"n":349,"zh":"","en":"I like tennis.","it":"A me piace il tennis.","ipa":"a mɛ pjạʧe il tɛ̣nːis."},{"n":350,"zh":"","en":"They like horror movies.","it":"A loro piacciono i film d'orrore.","ipa":"a lọro pjạtʧono i film dorːọre."},{"n":351,"zh":"","en":"She doesn't like action movies.","it":"Non le piacciono i film d'azione.","ipa":"non le pjạtʧono i film daʦjọne."},{"n":352,"zh":"","en":"I like romantic movies.","it":"Mi piacciono i film romantici.","ipa":"mi pjạtʧono i film romạntiʧi."},{"n":353,"zh":"","en":"I never watch TV.","it":"Non guardo mai la televisione.","ipa":"non ɡwạrdo mạj la televizjọne."},{"n":354,"zh":"","en":"I don't watch TV very often.","it":"Non guardo spesso la televisione.","ipa":"non ɡwạrdo spɛ̣sːo la televizjọne."},{"n":355,"zh":"","en":"I don't like to go to bars very often.","it":"Non mi piace andare per bar troppo spesso.","ipa":"non mi pjạʧe andạre pɛr bar trɔ̣pːo spɛ̣sːo."},{"n":356,"zh":"","en":"She likes to ride her bicycle every day.","it":"Le piace andare in bicicletta tutti i giorni.","ipa":"le pjạʧe andạre in biʧiklɛ̣tːa tụtː‿ i ʤọrni."},{"n":357,"zh":"","en":"They always like to eat in restaurants.","it":"A loro piace mangiare sempre al ristorante.","ipa":"a lọro pjạʧe maɲʤạre sẹmpre al ristorạnte."},{"n":358,"zh":"","en":"I never like to travel by train.","it":"Non mi piace viaggiare in treno.","ipa":"non mi pjạʧe vjadʤạre in trẹno."},{"n":359,"zh":"","en":"I get the news every day, but sometimes I don't read it.","it":"Ricevo il giornale ogni giorno, ma qualche volta non lo leggo.","ipa":"riʧẹvo il ʤornạle ɔ̣ɲːi ʤọrno, ma kwạlke vɔ̣lta non lo lẹɡːo."},{"n":360,"zh":"","en":"He has a car, but he doesn't use it very often.","it":"Lui possiede una macchina, ma non la usa molto spesso.","ipa":"lụj posːjẹde ụna mạkːina, ma non la ụza mọlto spɛ̣sːo."},{"n":361,"zh":"","en":"His friends like the movies, but they usually watch movies at home.","it":"Ai suoi amici piace andare al cinema, ma spesso guardano i film a casa.","ipa":"ạj swɔ̣j amịʧi pjạʧe andạre al ʧịnema, ma spɛ̣sːo ɡwạrdano i film a kạza."},{"n":362,"zh":"","en":"She's married, but she doesn't wear a ring.","it":"Lei è sposata, ma non porta la fede nuziale.","ipa":"lɛ̣j ɛ̣ spozạta, ma non pɔ̣rta la fẹde nuʦjạle."},{"n":363,"zh":"","en":"I don't know much about politics. I'm not interested in it.","it":"Io non ne so molto di politica. Non mi interessa.","ipa":"ịo non ne sɔ mọlto di polịtika. non m‿ interɛ̣sːa."},{"n":364,"zh":"","en":"This hotel isn't expensive. It doesn't cost much to stay there.","it":"Quest'hotel non è caro. Non costa molto alloggiare qui.","ipa":"kwɛstotɛ̣l non ɛ̣ kạro. non kɔ̣sta mọlto alːodʤạre kwị."},{"n":365,"zh":"","en":"He lives near us, but we don't see him very often.","it":"Lui vive vicino a noi, ma non lo vediamo molto spesso.","ipa":"lụj vịve viʧịno a nọj, ma non lo vedjạmo mọlto spɛ̣sːo."},{"n":366,"zh":"","en":"She speaks four (4) languages.","it":"Lei parla quattro (4) lingue.","ipa":"lɛ̣j pạrla kwạtːro (4) lịŋɡwe."},{"n":367,"zh":"","en":"I don't like my job. It's very boring.","it":"Non mi piace il mio lavoro. È molto noioso.","ipa":"non mi pjạʧe il mịo lavọro. ɛ̣ mọlto nojọzo."},{"n":368,"zh":"","en":"Where is he? — I'm sorry, I don't know.","it":"Lui dov'è? — Mi dispiace, non lo so.","ipa":"lụj dovɛ̣? — mi dispjạʧe, non lo sɔ."},{"n":369,"zh":"","en":"She's a very quiet person. She doesn't talk very much.","it":"Lei è una persona molto tranquilla. Non parla molto.","ipa":"lɛ̣j ɛ̣ ụna persọna mọlto traŋkwịlːa. non pạrla mọlto."},{"n":370,"zh":"","en":"He drinks a lot of coffee. It's his favorite drink.","it":"Lui beve molto caffè. È la sua bevanda preferita.","ipa":"lụj bẹve mọlto kafːɛ̣. ɛ̣ la sụa bevạnda preferịta."},{"n":371,"zh":"","en":"It's not true. I don't believe it.","it":"Non è vero. Non ci credo.","ipa":"non ɛ̣ vẹro. non ʧi krẹdo."},{"n":372,"zh":"","en":"That's a very beautiful picture. I like it a lot.","it":"Questa è una foto davvero bellissima. Mi piace molto.","ipa":"kwɛ̣sta ɛ̣ ụna fọto davːẹro belːịsːima. mi pjạʧe mọlto."},{"n":373,"zh":"","en":"He's a vegetarian. He doesn't eat meat.","it":"Lui è vegetariano. Non mangia la carne.","ipa":"lụj ɛ̣ veʤetarjạno. non mạɲʤa la kạrne."},{"n":374,"zh":"","en":"Do you work on Sunday?","it":"Lavori la domenica?","ipa":"lavọri la domẹnika?"},{"n":375,"zh":"","en":"Do your friends live near here?","it":"I tuoi amici abitano qui vicino?","ipa":"i twɔ̣j amịʧi ạbitano kwị viʧịno?"},{"n":376,"zh":"","en":"Does Emily play tennis?","it":"Emilia gioca a tennis?","ipa":"emịlja ʤɔ̣k‿ a tɛ̣nːis?"},{"n":377,"zh":"","en":"Where do your parents live?","it":"Dove abitano i tuoi genitori?","ipa":"dọve ạbitano i twɔ̣j ʤenitọri?"},{"n":378,"zh":"","en":"How often do you wash your hair?","it":"Quanto spesso ti lavi i capelli?","ipa":"kwạnto spɛ̣sːo ti lạv‿ i kapɛ̣lːi?"},{"n":379,"zh":"","en":"What does this word mean?","it":"Cosa significa questa parola?","ipa":"kɔ̣za siɲːịfika kwɛ̣sta parɔ̣la?"},{"n":380,"zh":"","en":"How much does it cost to fly to New York?","it":"Quanto costa un volo per New York?","ipa":"kwạnto kɔ̣sta un vọlo pɛr (…) (…)?"},{"n":381,"zh":"","en":"Do you always have breakfast?","it":"Tu fai sempre colazione?","ipa":"tu fạj sẹmpre kolaʦjọne?"},{"n":382,"zh":"","en":"Does Wenjie ever call you?","it":"Wenjie ti chiama mai?","ipa":"(…) ti kjạma mạj?"},{"n":383,"zh":"","en":"What do you usually do on weekends?","it":"Solitamente, cosa fai nei fine settimana?","ipa":"solitamɛ̣nte, kɔ̣za fạj nɛ̣j fịne setːimạna?"},{"n":384,"zh":"","en":"Do they like music?","it":"A loro piace la musica?","ipa":"a lọro pjạʧe la mụzika?"},{"n":385,"zh":"","en":"Does he like music?","it":"Gli piace la musica?","ipa":"ʎːi pjạʧe la mụzika?"},{"n":386,"zh":"","en":"Do your parents speak English?","it":"I tuoi genitori parlano inglese?","ipa":"i twɔ̣j ʤenitọri pạrlano inɡlẹze?"},{"n":387,"zh":"","en":"Does your father work hard?","it":"Tuo padre lavora intensamente?","ipa":"tụo pạdre lavọra intensamɛ̣nte?"},{"n":388,"zh":"","en":"Does your sister live in Canada?","it":"Tua sorella vive in Canada?","ipa":"tụa sorɛ̣lːa vịve in kạnada?"},{"n":389,"zh":"","en":"I like chocolate. How about you? Do you like chocolate?","it":"A me piace la cioccolata. E a te? Ti piace la cioccolata?","ipa":"a mɛ pjạʧe la ʧokːolạta. e a tɛ? ti pjạʧe la ʧokːolạta?"},{"n":390,"zh":"","en":"I play tennis. How about you? Do you play tennis?","it":"Io gioco a tennis. E tu? Tu, giochi a tennis?","ipa":"ịo ʤɔ̣ko a tɛ̣nːis. e tu? tu, ʤọki a tɛ̣nːis?"},{"n":391,"zh":"","en":"You live near here. How about Fred? Does he live near here?","it":"Tu vivi qui vicino. E Fred? Lui, vive qui vicino?","ipa":"tu vịvi kwị viʧịno. e frɛd? lụj, vịve kwị viʧịno?"},{"n":392,"zh":"","en":"Jisang plays tennis. How about his friends? Do they play tennis?","it":"Jisang gioca a tennis. E i suoi amici? Loro, giocano a tennis?","ipa":"(…) ʤɔ̣k‿ a tɛ̣nːis. e i swɔ̣j amịʧi? lọro, ʤọkano a tɛ̣nːis?"},{"n":393,"zh":"","en":"You speak English. How about your brother? Does he speak English?","it":"Tu parli inglese. E tuo fratello? Lui, parla inglese?","ipa":"tu pạrl‿ inɡlẹze. e tụo fratɛ̣lːo? lụj, pạrla inɡlẹze?"},{"n":394,"zh":"","en":"I do yoga every morning. How about you? Do you do yoga every morning?","it":"Faccio yoga tutte le mattine. E tu? Tu, fai yoga tutte le mattine?","ipa":"fạtʧo jɔ̣ɡa tụtːe le matːịne. e tu? tu, fạj jɔ̣ɡa tụtːe le matːịne?"},{"n":395,"zh":"","en":"Yaqin often travels on business. How about Gary? Does he often travel on business?","it":"Yaqin viaggia spesso per lavoro. E Gary? Lui, viaggia spesso per lavoro?","ipa":"(…) vjạdʤa spɛ̣sːo pɛr lavọro. e (…)? lụj, vjạdʤa spɛ̣sːo pɛr lavọro?"},{"n":396,"zh":"","en":"I want to be famous. How about you? Do you want to be famous?","it":"Voglio diventare famoso. E tu? Tu, vuoi diventare famoso?","ipa":"vɔ̣ʎːjo diventạre famọzo. e tu? tu, vwɔ̣j diventạre famọzo?"},{"n":397,"zh":"","en":"You work hard. How about Heuiyeon? Does she work hard?","it":"Tu lavori sodo. E Heuiyeon? Lei, lavora sodo?","ipa":"tu lavọri sɔ̣do. e ewjjeọn? lɛ̣j, lavọra sɔ̣do?"},{"n":398,"zh":"","en":"Where do your parents live?","it":"Dove abitano i tuoi genitori?","ipa":"dọve ạbitano i twɔ̣j ʤenitọri?"},{"n":399,"zh":"","en":"Do you always get up early?","it":"Ti alzi sempre presto?","ipa":"ti ạlʦi sẹmpre prɛ̣sto?"},{"n":400,"zh":"","en":"How often do you watch TV?","it":"Quanto spesso guardi la televisione?","ipa":"kwạnto spɛ̣sːo ɡwạrdi la televizjọne?"}]},{"lesson":5,"range":[401,500],"items":[{"n":401,"zh":"","en":"What do you want for dinner?","it":"Cosa vuoi per cena?","ipa":"kɔ̣za vwɔ̣j pɛr ʧẹna?"},{"n":402,"zh":"","en":"Do you like football?","it":"Ti piace il calcio?","ipa":"ti pjạʧe il kạlʧo?"},{"n":403,"zh":"","en":"Does your brother like football?","it":"A tuo fratello piace il calcio?","ipa":"a tụo fratɛ̣lːo pjạʧe il kạlʧo?"},{"n":404,"zh":"","en":"What do you do in your free time?","it":"Cosa fai nel tempo libero?","ipa":"kɔ̣za fạj nɛl tẹmpo lịbero?"},{"n":405,"zh":"","en":"Where does your sister work?","it":"Dove lavora tua sorella?","ipa":"dọve lavọra tụa sorɛ̣lːa?"},{"n":406,"zh":"","en":"Do you ever go to the movies?","it":"Tu vai mai al cinema?","ipa":"tu vạj mạj al ʧịnema?"},{"n":407,"zh":"","en":"What does this word mean?","it":"Cosa significa questa parola?","ipa":"kɔ̣za siɲːịfika kwɛ̣sta parɔ̣la?"},{"n":408,"zh":"","en":"How often does it snow here?","it":"Quanto spesso nevica qui?","ipa":"kwạnto spɛ̣sːo nẹvika kwị?"},{"n":409,"zh":"","en":"What time do you usually go to bed?","it":"A che ora vai a letto, di solito?","ipa":"a ke ọra vạj a lɛ̣tːo, di sɔ̣lito?"},{"n":410,"zh":"","en":"How much does it cost to call Mexico?","it":"Quanto costa chiamare in Messico?","ipa":"kwạnto kɔ̣sta kjamạre in mɛ̣sːiko?"},{"n":411,"zh":"","en":"What do you usually have for breakfast?","it":"Cosa mangi di solito a colazione?","ipa":"kɔ̣za mạɲʤi di sɔ̣lito a kolaʦjọne?"},{"n":412,"zh":"","en":"Do you watch TV a lot? — No, I don't.","it":"Guardi molto la tivù? — No, non molto.","ipa":"ɡwạrdi mọlto la tivụ? — nɔ, non mọlto."},{"n":413,"zh":"","en":"Do you live in a big city? — No, I don't.","it":"Vivi in una grande città? — No, non vivo in una grande città.","ipa":"vịv‿ in ụna ɡrạnde ʧitːạ? — nɔ, non vịvo in ụna ɡrạnde ʧitːạ."},{"n":414,"zh":"","en":"Do you ever ride a bicycle? — Not usually.","it":"Non vai mai in bici? — No, di solito no.","ipa":"non vạj mạj in bịʧi? — nɔ, di sɔ̣lito nɔ."},{"n":415,"zh":"","en":"Does it rain a lot where you live? — Not much.","it":"Piove molto dove vivi? — No, non molto.","ipa":"pjɔ̣ve mọlto dọve vịvi? — nɔ, non mọlto."},{"n":416,"zh":"","en":"Do you play the piano? — No, I don't.","it":"Suoni il pianoforte? — No, non suono il pianoforte.","ipa":"swɔ̣n‿ il pjanofɔ̣rte? — nɔ, non swɔ̣no il pjanofɔ̣rte."},{"n":417,"zh":"","en":"Zhirong's watching television.","it":"Zhirong sta guardando la televisione.","ipa":"(…) sta ɡwardạndo la televizjọne."},{"n":418,"zh":"","en":"He's not playing the guitar.","it":"Lui non sta suonando la chitarra.","ipa":"lụj non sta swonạndo la kitạrːa."},{"n":419,"zh":"","en":"But Zhirong has a guitar.","it":"Ma Zhirong possiede una chitarra.","ipa":"ma (…) posːjẹde ụna kitạrːa."},{"n":420,"zh":"","en":"He plays guitar a lot, and he plays very well.","it":"Lui suona molto la chitarra e la suona molto bene.","ipa":"lụj swɔ̣na mọlto la kitạrːa e la swɔ̣na mọlto bẹne."},{"n":421,"zh":"","en":"Zhirong plays the guitar.","it":"Zhirong suona la chitarra.","ipa":"(…) swɔ̣na la kitạrːa."},{"n":422,"zh":"","en":"But he's not playing the guitar now.","it":"Ma non sta suonando la chitarra in questo momento.","ipa":"ma non sta swonạndo la kitạrːa in kwɛ̣sto momɛ̣nto."},{"n":423,"zh":"","en":"Is Zhirong playing the guitar? — No, he isn't.","it":"Zhirong sta suonando la chitarra? — No, lui non la sta suonando.","ipa":"(…) sta swonạndo la kitạrːa? — nɔ, lụj non la sta swonạndo."},{"n":424,"zh":"","en":"Does he play the guitar? — Yes, he does.","it":"Lui suona la chitarra? — Sì, suona la chitarra.","ipa":"lụj swɔ̣na la kitạrːa? — sị, swɔ̣na la kitạrːa."},{"n":425,"zh":"","en":"Please be quiet. I'm working.","it":"Fai piano, per favore. Sto lavorando.","ipa":"fạj pjạno, pɛr favọre. stɔ lavorạndo."},{"n":426,"zh":"","en":"Yiting's taking a shower at the moment.","it":"Yiting sta facendo la doccia in questo momento.","ipa":"(…) sta faʧɛ̣ndo la dɔ̣tʧa in kwɛ̣sto momɛ̣nto."},{"n":427,"zh":"","en":"Take an umbrella with you. It's raining.","it":"Prendi l'ombrello. Sta piovendo.","ipa":"prɛ̣ndi lombrɛ̣lːo. sta pjovɛ̣ndo."},{"n":428,"zh":"","en":"You can turn off the TV. I'm not watching it.","it":"Puoi spegnere la televisione. Non la sto guardando.","ipa":"pwɔ̣j spẹɲːere la televizjọne. non la stɔ ɡwardạndo."},{"n":429,"zh":"","en":"Why are you under the table? What are you doing?","it":"Perché sei sotto il tavolo? Cosa stai facendo?","ipa":"perkɛ̣ sɛ̣j sọtːo il tạvolo? kɔ̣za stạj faʧɛ̣ndo?"},{"n":430,"zh":"","en":"I work every day from nine (9:00) to five-thirty (5:30).","it":"Lavoro ogni giorno dalle nove (9:00) alle cinque e trenta (5:30).","ipa":"lavọro ɔ̣ɲːi ʤọrno dạlːe nɔ̣ve (9:00) ạlːe ʧịŋkw‿ e trɛ̣nta (5:30)."},{"n":431,"zh":"","en":"Howard takes a shower every morning.","it":"Howard fa la doccia tutte le mattine.","ipa":"(…) fa la dɔ̣tʧa tụtːe le matːịne."},{"n":432,"zh":"","en":"It rains a lot in the winter.","it":"D'inverno piove molto.","ipa":"dinvɛ̣rno pjɔ̣ve mọlto."},{"n":433,"zh":"","en":"I don't watch TV very often.","it":"Io non guardo molto spesso la tivù.","ipa":"ịo non ɡwạrdo mọlto spɛ̣sːo la tivụ."},{"n":434,"zh":"","en":"What do you usually do on weekends?","it":"Cosa fai di solito nei fine settimana?","ipa":"kɔ̣za fạj di sɔ̣lito nɛ̣j fịne setːimạna?"},{"n":435,"zh":"","en":"Do you like her?","it":"Lei ti piace?","ipa":"lɛ̣j ti pjạʧe?"},{"n":436,"zh":"","en":"Do you love her?","it":"Tu la ami?","ipa":"tu l‿ ạmi?"},{"n":437,"zh":"","en":"Do you want to know the answer?","it":"Vuoi sapere la risposta?","ipa":"vwɔ̣j sapẹre la rispɔ̣sta?"},{"n":438,"zh":"","en":"Do you understand me?","it":"Tu mi capisci?","ipa":"tu mi kapịʃi?"},{"n":439,"zh":"","en":"Do you remember that day?","it":"Ti ricordi di quel giorno?","ipa":"ti rikɔ̣rdi di kwɛ̣l ʤọrno?"},{"n":440,"zh":"","en":"It depends on you.","it":"Dipende da te.","ipa":"dipɛ̣nde da tɛ."},{"n":441,"zh":"","en":"What do you prefer?","it":"Cosa preferisci?","ipa":"kɔ̣za preferịʃi?"},{"n":442,"zh":"","en":"Do you hate me?","it":"Tu mi odi?","ipa":"tu mi ɔ̣di?"},{"n":443,"zh":"","en":"What do you need?","it":"Di cosa hai bisogno?","ipa":"di kɔ̣z‿ ạj bizọɲːo?"},{"n":444,"zh":"","en":"What do you mean?","it":"Cosa intendi?","ipa":"kɔ̣za intɛ̣ndi?"},{"n":445,"zh":"","en":"Do you believe me?","it":"Tu mi credi?","ipa":"tu mi krẹdi?"},{"n":446,"zh":"","en":"I don't believe you.","it":"Io non ti credo.","ipa":"ịo non ti krẹdo."},{"n":447,"zh":"","en":"Do you forget the answer?","it":"Non ti ricordi la risposta?","ipa":"non ti rikɔ̣rdi la rispɔ̣sta?"},{"n":448,"zh":"","en":"Does he take photographs?","it":"Lui scatta fotografie?","ipa":"lụj skạtːa fotoɡrạfje?"},{"n":449,"zh":"","en":"Is he taking a photograph?","it":"Lui sta scattando una foto?","ipa":"lụj sta skatːạndo ụna fọto?"},{"n":450,"zh":"","en":"What's he doing now?","it":"Lui, cosa sta facendo in questo momento?","ipa":"lụj, kɔ̣za sta faʧɛ̣ndo in kwɛ̣sto momɛ̣nto?"},{"n":451,"zh":"","en":"Is she driving a bus?","it":"Lei sta guidando un autobus?","ipa":"lɛ̣j sta ɡwidạndo un ạwtobus?"},{"n":452,"zh":"","en":"Does she drive a bus?","it":"Lei guida un autobus?","ipa":"lɛ̣j ɡwịda un ạwtobus?"},{"n":453,"zh":"","en":"What's she doing now?","it":"Lei, cosa sta facendo in questo momento?","ipa":"lɛ̣j, kɔ̣za sta faʧɛ̣ndo in kwɛ̣sto momɛ̣nto?"},{"n":454,"zh":"","en":"Does he wash windows?","it":"Lui lava le finestre?","ipa":"lụj lạva le finɛ̣stre?"},{"n":455,"zh":"","en":"Is he washing a window?","it":"Lui sta lavando la finestra?","ipa":"lụj sta lavạndo la finɛ̣stra?"},{"n":456,"zh":"","en":"What's he doing now?","it":"Che cosa sta facendo adesso?","ipa":"ke kɔ̣za sta faʧɛ̣ndo adɛ̣sːo?"},{"n":457,"zh":"","en":"Are they teaching?","it":"Loro stanno insegnando?","ipa":"lọro stạnːo inseɲːạndo?"},{"n":458,"zh":"","en":"Do they teach?","it":"Loro insegnano?","ipa":"lọro insẹɲːano?"},{"n":459,"zh":"","en":"What do they do?","it":"Loro che cosa fanno?","ipa":"lọro ke kɔ̣za fạnːo?"},{"n":460,"zh":"","en":"Excuse me, do you speak English?","it":"Mi scusi, lei parla inglese?","ipa":"mi skụzi, lɛ̣j pạrla inɡlẹze?"},{"n":461,"zh":"","en":"Where's Kelly? — I don't know.","it":"Dov'è Kelly? — Non lo so.","ipa":"dovɛ̣ (…)? — non lo sɔ."},{"n":462,"zh":"","en":"What's so funny? Why are you laughing?","it":"Cosa c'è di così divertente? Perché stai ridendo?","ipa":"kɔ̣za ʧɛ̣ di kozị divertɛ̣nte? perkɛ̣ stạj ridɛ̣ndo?"},{"n":463,"zh":"","en":"What does your sister do? — She's a dentist.","it":"Che cosa fa nella vita tua sorella? — Lei è dentista.","ipa":"ke kɔ̣za fa nɛ̣lːa vịta tụa sorɛ̣lːa? — lɛ̣j ɛ̣ dentịsta."},{"n":464,"zh":"","en":"It's raining. I don't want to go out in the rain.","it":"Sta piovendo. Io non voglio andare fuori sotto la pioggia.","ipa":"sta pjovɛ̣ndo. ịo non vɔ̣ʎːjo andạre fwɔ̣ri sọtːo la pjɔ̣dʤa."},{"n":465,"zh":"","en":"Where do you come from?","it":"Di dove sei?","ipa":"di dọve sɛ̣j?"},{"n":466,"zh":"","en":"How much does it cost to send a package to Canada?","it":"Quanto costa mandare un pacco in Canada?","ipa":"kwạnto kɔ̣sta mandạre un pạkːo in kạnada?"},{"n":467,"zh":"","en":"He's a good tennis player, but he doesn't play very often.","it":"Gioca bene a tennis, ma non ci gioca spesso.","ipa":"ʤɔ̣ka bẹne a tɛ̣nːis, ma non ʧi ʤɔ̣ka spɛ̣sːo."},{"n":468,"zh":"","en":"Where's Jirou? — He's taking a shower.","it":"Dov'è Jirou? — Si sta docciando.","ipa":"dovɛ̣ (…)? si sta dotʧạndo."},{"n":469,"zh":"","en":"I don't watch TV very often.","it":"Non guardo spesso la televisione.","ipa":"non ɡwạrdo spɛ̣sːo la televizjọne."},{"n":470,"zh":"","en":"Somebody's singing.","it":"Qualcuno sta cantando.","ipa":"kwalkụno sta kantạndo."},{"n":471,"zh":"","en":"Junko's tired. She wants to go home now.","it":"Junko è stanca. Vuole andare a casa.","ipa":"(…) ɛ̣ stạŋka. vwɔ̣le andạre a kạza."},{"n":472,"zh":"","en":"How often do you read the news?","it":"Quanto spesso leggi il giornale?","ipa":"kwạnto spɛ̣sːo lɛ̣dʤ‿ il ʤornạle?"},{"n":473,"zh":"","en":"Excuse me, but you're sitting in my seat. — I'm sorry.","it":"Mi scusi, ma si è seduto al mio posto. — Chiedo scusa.","ipa":"mi skụzi, ma si ɛ̣ sedụto al mịo pɔ̣sto. — kjɛ̣do skụza."},{"n":474,"zh":"","en":"I'm sorry, I don't understand. Can you speak more slowly?","it":"Mi dispiace, non capisco. Potrebbe parlare più lentamente?","ipa":"mi dispjạʧe, non kapịsko. potrɛ̣bːe parlạre piụ lentamɛ̣nte?"},{"n":475,"zh":"","en":"It's late. I'm going home now. Are you coming with me?","it":"È tardi. Adesso vado a casa. Tu vieni con me?","ipa":"ɛ̣ tạrdi. adɛ̣sːo vạdo a kạza. tu vjẹni kon mɛ?"},{"n":476,"zh":"","en":"What time does your father finish work every day?","it":"A che ora tuo papà finisce di lavorare ogni giorno?","ipa":"a ke ọra tụo papạ finịʃe di lavorạre ɔ̣ɲːi ʤọrno?"},{"n":477,"zh":"","en":"You can turn the music off. I'm not listening to it.","it":"Puoi spegnere la musica. Io non la sto ascoltando.","ipa":"pwɔ̣j spẹɲːere la mụzika. ịo non la stɔ askoltạndo."},{"n":478,"zh":"","en":"He's in the kitchen cooking something.","it":"Lui è in cucina, preparandosi qualcosa.","ipa":"lụj ɛ̣ in kuʧịna, preparạndozi kwalkɔ̣za."},{"n":479,"zh":"","en":"Jack doesn't usually drive to work. He usually walks.","it":"Giacomo solitamente non va al lavoro in macchina. Di solito ci va a piedi.","ipa":"ʤạkomo solitamɛ̣nte non v‿ al lavọro in mạkːina. di sɔ̣lito ʧi v‿ a pjẹdi."},{"n":480,"zh":"","en":"Lucy doesn't like coffee. She prefers tea.","it":"A Lucia non piace il caffè. Preferisce il tè.","ipa":"a luʧịa non pjạʧe il kafːɛ̣. preferịʃe il tɛ̣."},{"n":481,"zh":"","en":"I have blue eyes. > I've got blue eyes.","it":"Ho gli occhi azzurri.","ipa":"ɔ ʎːi ɔ̣kːi aʦːụrːi."},{"n":482,"zh":"","en":"Ganesh has two (2) sisters. > Ganesh's got two (2) sisters.","it":"Ganesh ha due (2) sorelle.","ipa":"(…) a dụe (2) sorɛ̣lːe."},{"n":483,"zh":"","en":"Our car has four (4) doors. > Our car's got four (4) doors.","it":"La nostra macchina ha quattro (4) porte.","ipa":"la nɔ̣stra mạkːin‿ a kwạtːro (4) pɔ̣rte."},{"n":484,"zh":"","en":"She isn't feeling well. She has a headache. > She's got a headache.","it":"Lei non si sente bene. Ha mal di testa.","ipa":"lɛ̣j non si sɛ̣nte bẹne. a mal di tɛ̣sta."},{"n":485,"zh":"","en":"They like animals. They have a horse, three (3) dogs, and six (6) cats. They've got a lot of animals.","it":"A loro piacciono gli animali. Hanno un cavallo, tre (3) cani e sei (6) gatti. Hanno un sacco di animali.","ipa":"a lọro pjạtʧono ʎːi animạli. ạnːo un kavạlːo, trɛ (3) kạni e sɛ̣j (6) ɡạtːi. ạnːo un sạkːo di animạli."},{"n":486,"zh":"","en":"I have a bike, but I don't have a car. > I've got a bike, but I haven't got a car.","it":"Possiedo una bicicletta, ma non ho un'automobile.","ipa":"posːjẹdo ụna biʧiklɛ̣tːa, ma non ɔ unawtomɔ̣bile."},{"n":487,"zh":"","en":"They don't have any children. > They haven't got any children.","it":"Loro non hanno figli.","ipa":"lọro non ạnːo fịʎːi."},{"n":488,"zh":"","en":"It's a nice house, but it doesn't have a garage. > It hasn't got a garage.","it":"È una bella casa, ma non ha un garage.","ipa":"ɛ̣ ụna bɛ̣lːa kạza, ma non a un ɡarạʒ."},{"n":489,"zh":"","en":"Lila doesn't have a job. > Lila hasn't got a job.","it":"Lila non ha un lavoro.","ipa":"lịla non a un lavọro."},{"n":490,"zh":"","en":"Does your phone have a camera?","it":"Il tuo cellulare ha una videocamera?","ipa":"il tụo ʧelːulạre a ụna videokạmera?"},{"n":491,"zh":"","en":"Does Nicole have a car? > Has Nicole got a car?","it":"Nicole ha una macchina?","ipa":"(…) a ụna mạkːina?"},{"n":492,"zh":"","en":"What kind of car does she have? > What kind of car has she got?","it":"Che [tipo di] macchina hai?","ipa":"ke [tịpo di] mạkːin‿ ạj?"},{"n":493,"zh":"","en":"What do you have in your bag? > What have you got in your bag?","it":"Che cos'hai nella tua borsa?","ipa":"ke kozạj nɛ̣lːa tụa bọrsa?"},{"n":494,"zh":"","en":"Do you have a camera? — No, I don't.","it":"Hai una macchina fotografica? — No, non ce l'ho.","ipa":"ạj ụna mạkːina fotoɡrạfika? — nɔ, non ʧe lɔ."},{"n":495,"zh":"","en":"Have you got a camera? — No, I don't.","it":"Possiedi una macchina fotografica? — No, non ne ho.","ipa":"posːjẹdi ụna mạkːina fotoɡrạfika? — nɔ, non ne ɔ."},{"n":496,"zh":"","en":"Does she have a car? — No, she doesn't.","it":"Lei ha un'auto? — No, non ce l'ha.","ipa":"lɛ̣j a unạwto? — nɔ, non ʧe la."},{"n":497,"zh":"","en":"Ask if he has a computer. — Yes, he's got a computer.","it":"Chiedi se lui possiede un computer. — Sì, possiede un computer.","ipa":"kjɛ̣di se lụj posːjẹde un kompjụter. — sị, posːjẹde un kompjụter."},{"n":498,"zh":"","en":"Ask if he has a dog. — No, he hasn't got a dog.","it":"Chiedi se lui ha un cane. — No, non ha un cane.","ipa":"kjɛ̣di se lụj a un kạne. — nɔ, non a un kạne."},{"n":499,"zh":"","en":"Ask if he has a smart phone. — No, he hasn't got a smart phone.","it":"Chiedi se lui ha uno smartphone. — No, non possiede uno smartphone.","ipa":"kjɛ̣di se lụj a ụno (…). — nɔ, non posːjẹde ụno (…)."},{"n":500,"zh":"","en":"Ask if he has a watch. — Yes, he's got a watch.","it":"Chiedi se lui possiede un orologio. — Sì, ha un orologio.","ipa":"kjɛ̣di se lụj posːjẹde un orolɔ̣ʤo. — sị, a un orolɔ̣ʤo."}]},{"lesson":6,"range":[501,600],"items":[{"n":501,"zh":"","en":"Ask if he has any brothers or sisters. — Yes, he's got a brother and two (2) sisters.","it":"Chiedi se lui ha dei fratelli o delle sorelle. — Sì, ha un fratello e due (2) sorelle.","ipa":"kjɛ̣di se lụj a dẹj fratɛ̣lːi o dɛ̣lːe sorɛ̣lːe. — sị, a un fratɛ̣lːo e dụe (2) sorɛ̣lːe."},{"n":502,"zh":"","en":"I don't have a computer.","it":"Io non ho un computer.","ipa":"ịo non ɔ un kompjụter."},{"n":503,"zh":"","en":"You don't have a dog.","it":"Tu non hai un cane.","ipa":"tu non ạj un kạne."},{"n":504,"zh":"","en":"She doesn't have a bike.","it":"Lei non possiede una bici.","ipa":"lɛ̣j non posːjẹde ụna bịʧi."},{"n":505,"zh":"","en":"He has several brothers and sisters.","it":"Lui ha diversi fratelli e sorelle.","ipa":"lụj a divɛ̣rsi fratɛ̣lːi e sorɛ̣lːe."},{"n":506,"zh":"","en":"They have two (2) children.","it":"Loro hanno due (2) bambini.","ipa":"lọro ạnːo dụe (2) bambịni."},{"n":507,"zh":"","en":"She doesn't have a key.","it":"Lei non ha una chiave.","ipa":"lɛ̣j non a ụna kjạve."},{"n":508,"zh":"","en":"He has a new job.","it":"Lui ha un nuovo lavoro.","ipa":"lụj a un nwɔ̣vo lavọro."},{"n":509,"zh":"","en":"They don't have much money.","it":"Loro non hanno molti soldi.","ipa":"lọro non ạnːo mọlti sɔ̣ldi."},{"n":510,"zh":"","en":"Do you have an umbrella?","it":"Tu hai un ombrello?","ipa":"tu ạj un ombrɛ̣lːo?"},{"n":511,"zh":"","en":"We have a lot of work to do.","it":"Noi abbiamo molto lavoro da fare.","ipa":"nọj abːjạmo mọlto lavọro da fạre."},{"n":512,"zh":"","en":"I don't have your phone number.","it":"Io non ho il tuo numero di telefono.","ipa":"ịo non ɔ il tụo nụmero di telɛ̣fono."},{"n":513,"zh":"","en":"Does your father have a car?","it":"Tuo papà possiede una macchina?","ipa":"tụo papạ posːjẹde ụna mạkːina?"},{"n":514,"zh":"","en":"How much money do you have with you?","it":"Quanto denaro hai con te?","ipa":"kwạnto denạro ạj kon tɛ?"},{"n":515,"zh":"","en":"She doesn't have a car. She goes everywhere by bicycle.","it":"Lei non ha una macchina. Va ovunque in bicicletta.","ipa":"lɛ̣j non a ụna mạkːina. va ovụŋkwe in biʧiklɛ̣tːa."},{"n":516,"zh":"","en":"They like animals. They have three (3) dogs and two (2) cats.","it":"A loro piacciono gli animali. Hanno tre (3) cani e due (2) gatti.","ipa":"a lọro pjạtʧono ʎːi animạli. ạnːo trɛ (3) kạni e dụe (2) ɡạtːi."},{"n":517,"zh":"","en":"Fahim isn't happy. He's got a lot of problems.","it":"Fahim non è felice. Ha molti problemi.","ipa":"(…) non ɛ̣ felịʧe. a mọlti problẹmi."},{"n":518,"zh":"","en":"They don't read much. They don't have many books.","it":"Loro non leggono molto. Non possiedono molti libri.","ipa":"lọro non lẹɡːono mọlto. non posːjẹdono mọlti lịbri."},{"n":519,"zh":"","en":"What's wrong? — I've got something in my eye.","it":"Cosa c'è che non va? — Ho qualcosa nell'occhio.","ipa":"kɔ̣za ʧɛ̣ ke non va? — ɔ kwalkɔ̣za nɛlːɔ̣kːjo."},{"n":520,"zh":"","en":"Where's my phone? — I don't know. I don't have it.","it":"Dov'è il mio telefono? — Non lo so, non ce l'ho.","ipa":"dovɛ̣ il mịo telɛ̣fono? — non lo sɔ, non ʧe lɔ."},{"n":521,"zh":"","en":"She wants to go to the concert, but she doesn't have a ticket.","it":"Lei vuole andare al concerto, ma non ha il biglietto.","ipa":"lɛ̣j vwɔ̣le andạre al koɲʧɛ̣rto, ma non a il biʎːjɛ̣tːo."},{"n":522,"zh":"","en":"I'm not feeling well. I have a headache.","it":"Non mi sento bene. Ho mal di testa.","ipa":"non mi sɛ̣nto bẹne. ɔ mal di tɛ̣sta."},{"n":523,"zh":"","en":"It's a nice house but it doesn't have a big yard.","it":"È una bella casa, ma non ha un grande giardino.","ipa":"ɛ̣ ụna bɛ̣lːa kạza, ma non a un ɡrạnde ʤardịno."},{"n":524,"zh":"","en":"Most cars have four (4) wheels.","it":"La maggior parte delle automobili ha quattro (4) ruote.","ipa":"la madʤọr pạrte dɛ̣lːe awtomɔ̣bili a kwạtːro (4) rwɔ̣te."},{"n":525,"zh":"","en":"Everybody likes him. He's got a lot of friends.","it":"Lui piace a tutti. Ha molti amici.","ipa":"lụj pjạʧe a tụtːi. a mọlti amịʧi."},{"n":526,"zh":"","en":"I can't open the door. I don't have the key.","it":"Non posso aprire la porta. Non ho le chiavi.","ipa":"non pɔ̣sːo aprịre la pɔ̣rta. non ɔ le kjạvi."},{"n":527,"zh":"","en":"An insect has six (6) legs.","it":"Un insetto ha sei (6) gambe.","ipa":"un insɛ̣tːo a sɛ̣j (6) ɡạmbe."},{"n":528,"zh":"","en":"Hurry, we don't have much time.","it":"Presto, non abbiamo molto tempo.","ipa":"prɛ̣sto, non abːjạmo mọlto tẹmpo."},{"n":529,"zh":"","en":"Now he's at work.","it":"Lui è al lavoro in questo momento.","ipa":"lụj ɛ̣ al lavọro in kwɛ̣sto momɛ̣nto."},{"n":530,"zh":"","en":"Last night he wasn't at work.","it":"Ieri sera lui non era al lavoro.","ipa":"jẹri sẹra lụj non ẹra al lavọro."},{"n":531,"zh":"","en":"He was in bed.","it":"Lui era a letto.","ipa":"lụj ẹra a lɛ̣tːo."},{"n":532,"zh":"","en":"He was asleep.","it":"Lui stava dormendo.","ipa":"lụj stạva dormɛ̣ndo."},{"n":533,"zh":"","en":"He was in bed, asleep.","it":"Lui era nel letto, addormentato.","ipa":"lụj ẹra nɛl lɛ̣tːo, adːormentạto."},{"n":534,"zh":"","en":"I was tired last night.","it":"Ieri notte, ero stanco.","ipa":"jẹri nɔ̣tːe, ẹro stạŋko."},{"n":535,"zh":"","en":"Where was Fatima yesterday?","it":"Dov'era ieri Fatima?","ipa":"dovɛ̣ra jẹri fạtima?"},{"n":536,"zh":"","en":"The weather was nice last week.","it":"La settimana scorsa il tempo era bello.","ipa":"la setːimạna skọrsa il tẹmpo ẹra bɛ̣lːo."},{"n":537,"zh":"","en":"You were late yesterday.","it":"Ieri, eri in ritardo.","ipa":"jẹri, ẹri in ritạrdo."},{"n":538,"zh":"","en":"They weren't here last Sunday.","it":"Non erano qui domenica scorsa.","ipa":"non ẹrano kwị domẹnika skọrsa."},{"n":539,"zh":"","en":"Last year Rebecca was twenty-two (22), so she is twenty-three (23) now.","it":"L'anno scorso Rebecca aveva ventidue (22) anni, adesso ne ha ventitrè (23).","ipa":"lạnːo skọrso rebẹkː‿ avẹva ventidụe (22) ạnːi, adɛ̣sːo ne a ventitrɛ̣ (23)."},{"n":540,"zh":"","en":"When I was a child, I was afraid of dogs.","it":"Quando ero [un] bambino avevo paura dei cani.","ipa":"kwạndo ẹro [un] bambịno avẹvo paụra dẹj kạni."},{"n":541,"zh":"","en":"We were hungry after the trip, but we weren't tired.","it":"Dopo il viaggio avevamo fame, ma non eravamo stanchi.","ipa":"dɔ̣po il vjạdʤo avevạmo fạme, ma non eravạmo stạŋki."},{"n":542,"zh":"","en":"The hotel was comfortable, but it wasn't expensive.","it":"L'hotel era comodo, ma non [era] caro.","ipa":"lotɛ̣l ẹra kɔ̣modo, ma non [ẹra] kạro."},{"n":543,"zh":"","en":"Was the weather nice when you were on vacation?","it":"Il tempo era bello quando eri in vacanza?","ipa":"il tẹmpo ẹra bɛ̣lːo kwạndo ẹri in vakạnʦa?"},{"n":544,"zh":"","en":"Your shoes are nice. Were they expensive?","it":"Carine le tue scarpe. Ti sono costate parecchio?","ipa":"karịne le tụe skạrpe. ti sọno kostạte parɛ̣kːjo?"},{"n":545,"zh":"","en":"Why were you late this morning?","it":"Perché eri in ritardo stamattina?","ipa":"perkɛ̣ ẹri in ritạrdo stamatːịna?"},{"n":546,"zh":"","en":"Were you late? — No, I wasn't.","it":"Eri in ritardo? — No, non ero in ritardo.","ipa":"ẹri in ritạrdo? — nɔ, non ẹro in ritạrdo."},{"n":547,"zh":"","en":"Was Paul at work yesterday? — Yes, he was.","it":"Paolo era al lavoro ieri? — Si, era al lavoro.","ipa":"paọlo ẹra al lavọro jẹri? — si, ẹra al lavọro."},{"n":548,"zh":"","en":"Were they at the party? — No, they weren't.","it":"Loro erano alla festa? — No, non c'erano.","ipa":"lọro ẹrano ạlːa fɛ̣sta? — nɔ, non ʧẹrano."},{"n":549,"zh":"","en":"Today the weather's nice, but yesterday it was very cold.","it":"Oggi il tempo è bello, ma ieri faceva davvero freddo.","ipa":"ɔ̣dʤ‿ il tẹmpo ɛ̣ bɛ̣lːo, ma jẹri faʧẹva davːẹro frɛ̣dːo."},{"n":550,"zh":"","en":"I'm hungry. Can I have something to eat?","it":"Ho fame. Posso avere qualcosa da mangiare?","ipa":"ɔ fạme. pɔ̣sːo avẹre kwalkɔ̣za da maɲʤạre?"},{"n":551,"zh":"","en":"I feel fine this morning, but I was very tired last night.","it":"Stamattina mi sento bene, ma ieri sera ero davvero stanco.","ipa":"stamatːịna mi sɛ̣nto bẹne, ma jẹri sẹra ẹro davːẹro stạŋko."},{"n":552,"zh":"","en":"Where were you at eleven a.m. (11:00) last Friday morning?","it":"Dov'eri venerdì scorso alle undici (11:00) di mattina?","ipa":"dovẹri venerdị skọrso ạlːe ụndiʧi (11:00) di matːịna?"},{"n":553,"zh":"","en":"Don't buy those shoes. They're very expensive.","it":"Non comprare quelle scarpe. Sono davvero care.","ipa":"non komprạre kwɛ̣lːe skạrpe. sọno davːẹro kạre."},{"n":554,"zh":"","en":"I like your new jacket. Was it expensive?","it":"Mi piace la tua nuova giacca. Ti è costata molto?","ipa":"mi pjạʧe la tụa nwɔ̣va ʤạkːa. ti ɛ̣ kostạta mọlto?"},{"n":555,"zh":"","en":"This time last year I was in Paris.","it":"L'anno scorso a quest'ora ero a Parigi.","ipa":"lạnːo skọrso a kwɛstọra ẹro a parịʤi."},{"n":556,"zh":"","en":"Where are the children? — I don't know, they were here a few minutes ago.","it":"Dove sono i bambini? — Non lo so, erano qui fino a qualche minuto fa.","ipa":"dọve sọno i bambịni? — non lo sɔ, ẹrano kwị fịno a kwạlke minụto fa."},{"n":557,"zh":"","en":"We weren't happy with the hotel. Our room was very small, and it wasn't clean.","it":"Non siamo stati contenti dell'albergo, la nostra camera era piccola e non era pulita.","ipa":"non sjạmo stạti kontɛ̣nti dɛlːalbɛ̣rɡo, la nɔ̣stra kạmera ẹra pịkːola e non ẹra pulịta."},{"n":558,"zh":"","en":"Antonio wasn't at work last week because he was sick. He's better now.","it":"Antonio non era al lavoro settimana scorsa perché era malato. Ora sta meglio.","ipa":"antɔ̣njo non ẹra al lavọro setːimạna skọrsa perkɛ̣ ẹra malạto. ọra sta mẹʎːjo."},{"n":559,"zh":"","en":"Yesterday was a holiday, so the banks were closed. They're open today.","it":"Ieri era [un giorno] festivo, quindi le banche erano chiuse. Oggi sono aperte.","ipa":"jẹri ẹra [un ʤọrno] festịvo, kwịndi le bạŋk‿ ẹrano kiụze. ɔ̣dʤi sọno apɛ̣rte."},{"n":560,"zh":"","en":"Were Anabel and Richard at the party? — Anabel was there, but Richard wasn't.","it":"Anabel e Richard erano alla festa? — Anabel c'era, Richard no.","ipa":"(…) e (…) ẹrano ạlːa fɛ̣sta? (…) ʧẹra, (…) nɔ."},{"n":561,"zh":"","en":"Where are my keys? — I don't know. They were on the table, but they're not there now.","it":"Dove sono le mie chiavi? — Non lo so, erano sul tavolo, ma ora non sono qui.","ipa":"dọve sọno le mịe kjạvi? — non lo sɔ, ẹrano sul tạvolo, ma ọra non sọno kwị."},{"n":562,"zh":"","en":"You weren't at home last night. Where were you?","it":"Non eri a casa ieri notte. Dov'eri?","ipa":"non ẹri a kạza jẹri nɔ̣tːe. dovẹri?"},{"n":563,"zh":"","en":"Why were you late this morning? — The traffic was bad.","it":"Perché eri in ritardo stamattina? — C'era molto traffico.","ipa":"perkɛ̣ ẹri in ritạrdo stamatːịna? — ʧẹra mọlto trạfːiko."},{"n":564,"zh":"","en":"Was your exam difficult? — No, it was easy.","it":"Era difficile il tuo esame? — No, era facile.","ipa":"ẹra difːịʧile il tụo ezạme? — nɔ, ẹra fạʧile."},{"n":565,"zh":"","en":"Where were they last week? — They were on vacation.","it":"Dov'erano settimana scorsa? — Erano in vacanza.","ipa":"dovẹrano setːimạna skọrsa? — ẹrano in vakạnʦa."},{"n":566,"zh":"","en":"How much was your new camera? — It was three hundred dollars ($300). > It was two hundred euros (€200).","it":"Quanto è costata la tua nuova macchina fotografica? — Mi è costata duecento (200) euro.","ipa":"kwạnto ɛ̣ kostạta la tụa nwɔ̣va mạkːina fotoɡrạfika? mi ɛ̣ kostạta dweʧɛ̣nto () ẹwro."},{"n":567,"zh":"","en":"Why were you angry yesterday? — Because you were late.","it":"Perché eri arrabbiato ieri? — Perché tu eri in ritardo.","ipa":"perkɛ̣ ẹri arːabːjạto jẹri? — perkɛ̣ tu ẹri in ritạrdo."},{"n":568,"zh":"","en":"Was the weather nice last week? — Yes, it was beautiful.","it":"Il tempo era bello settimana scorsa? — Sì, era bellissimo.","ipa":"il tẹmpo ẹra bɛ̣lːo setːimạna skọrsa? — sị, ẹra belːịsːimo."},{"n":569,"zh":"","en":"I brush my teeth every morning. This morning I brushed my teeth.","it":"Mi lavo i denti tutte le mattine. Stamattina mi sono lavato i denti.","ipa":"mi lạvo i dɛ̣nti tụtːe le matːịne. stamatːịna mi sọno lavạto i dɛ̣nti."},{"n":570,"zh":"","en":"Terry worked in a bank from nineteen ninety-five (1995) to two thousand one (2001).","it":"Terry ha lavorato in banca dal millenovecentonovantacinque (1995) al duemilauno (2001).","ipa":"(…) a lavorạto in bạŋka dal milːenoveʧentonovantaʧịŋkwe () al dwemilaụno ()."},{"n":571,"zh":"","en":"Yesterday it rained all morning. It stopped at lunchtime.","it":"Ieri è piovuto tutta la mattina. Ha smesso all'ora di pranzo.","ipa":"jẹri ɛ̣ pjovụto tụtːa la matːịna. a smɛ̣sːo alːọra di prạnʦo."},{"n":572,"zh":"","en":"We enjoyed the party last night.","it":"Ci siamo divertiti ieri sera alla festa.","ipa":"ʧi sjạmo divertịti jẹri sẹra ạlːa fɛ̣sta."},{"n":573,"zh":"","en":"We danced a lot and talked to a lot of people.","it":"Abbiamo ballato molto e parlato con tante persone.","ipa":"abːjạmo balːạto mọlto e parlạto kon tạnte persọne."},{"n":574,"zh":"","en":"The party ended at midnight.","it":"La festa è finita a mezzanotte.","ipa":"la fɛ̣sta ɛ̣ finịt‿ a meʣanɔ̣tːe."},{"n":575,"zh":"","en":"I usually get up early, but this morning I got up at nine thirty (9:30).","it":"Di solito mi alzo presto, ma stamattina mi sono alzato alle nove e mezza (9:30).","ipa":"di sɔ̣lito mi ạlʦo prɛ̣sto, ma stamatːịna mi sọno alʦạto ạlːe nɔ̣v‿ e mɛ̣ʣa (9:30)."},{"n":576,"zh":"","en":"We did a lot of work yesterday.","it":"Abbiamo lavorato molto ieri.","ipa":"abːjạmo lavorạto mọlto jẹri."},{"n":577,"zh":"","en":"Sonia went to the movies three (3) times last week.","it":"Sonia è andata tre (3) volte al cinema, la settimana scorsa.","ipa":"sɔ̣nja ɛ̣ andạta trɛ (3) vɔ̣lte al ʧịnema, la setːimạna skọrsa."},{"n":578,"zh":"","en":"Enzo came into the room, took off his coat, and sat down.","it":"Enzo è entrato nella stanza, si è tolto il cappotto e si è seduto.","ipa":"ẹnʦo ɛ̣ entrạto nɛ̣lːa stạnʦa, si ɛ̣ tọlto il kapːɔ̣tːo e si ɛ̣ sedụto."},{"n":579,"zh":"","en":"It was hot in the room, so I opened the window.","it":"Faceva caldo nella stanza, perciò ho aperto la finestra.","ipa":"faʧẹva kạldo nɛ̣lːa stạnʦa, perʧɔ̣ ɔ apɛ̣rto la finɛ̣stra."},{"n":580,"zh":"","en":"The movie was very long. It started at seven-fifteen (7:15) and finished at ten pm (10:00).","it":"Il film è stato davvero lungo. È iniziato alle sette e un quarto ed è finito alle dieci (10:00) di sera.","ipa":"il film ɛ̣ stạto davːẹro lụŋɡo. ɛ̣ iniʦjạto ạlːe sɛ̣tː‿ e un kwạrto ed ɛ̣ finịto ạlːe djẹʧi (10:00) di sẹra."},{"n":581,"zh":"","en":"When I was a child, I wanted to be a doctor.","it":"Quando ero bambino volevo diventare dottore.","ipa":"kwạndo ẹro bambịno volẹvo diventạre dotːọre."},{"n":582,"zh":"","en":"The accident happened last Sunday afternoon.","it":"L'incidente è avvenuto la scorsa domenica pomeriggio.","ipa":"liɲʧidɛ̣nt‿ ɛ̣ avːenụto la skọrsa domẹnika pomerịdʤo."},{"n":583,"zh":"","en":"It's a nice day today, but yesterday it rained all day.","it":"Oggi è una bella giornata, ma ieri è piovuto tutto il giorno.","ipa":"ɔ̣dʤi ɛ̣ ụna bɛ̣lːa ʤornạta, ma jẹri ɛ̣ pjovụto tụtːo il ʤọrno."},{"n":584,"zh":"","en":"We enjoyed our vacation last year. We stayed at a very nice place.","it":"Ci è piaciuta la nostra vacanza l'anno passato. Siamo stati in un posto davvero bello.","ipa":"ʧi ɛ̣ pjaʧụta la nɔ̣stra vakạnʦa lạnːo pasːạto. sjạmo stạt‿ in un pɔ̣sto davːẹro bɛ̣lːo."},{"n":585,"zh":"","en":"Cecilia's grandfather died when he was ninety (90) years old.","it":"Il nonno di Cecilia è morto all'età di novant'anni.","ipa":"il nɔ̣nːo di ʧeʧịlja ɛ̣ mɔ̣rto alːetạ di novantạnːi."},{"n":586,"zh":"","en":"I already paid the bill.","it":"Ho già pagato il conto.","ipa":"ɔ ʤạ paɡạto il kọnto."},{"n":587,"zh":"","en":"I visited her last week.","it":"Sono andato a trovarla la settimana scorsa.","ipa":"sọno andạto a trovạrla la setːimạna skọrsa."},{"n":588,"zh":"","en":"I bought my tickets online.","it":"Ho comprato i miei biglietti online (su internet).","ipa":"ɔ komprạto i mjɛ̣j biʎːjɛ̣tːi (…) (su ịnternet)."},{"n":589,"zh":"","en":"I copied the schedule.","it":"Ho copiato il programma (l'orario).","ipa":"ɔ kopjạto il proɡrạmːa (lorạrjo)."},{"n":590,"zh":"","en":"I put my bag on the table. (PAST TENSE)","it":"Ho messo la mia borsa sul tavolo.","ipa":"ɔ mɛ̣sːo la mịa bọrsa sul tạvolo."},{"n":591,"zh":"","en":"I spoke with him yesterday on the phone.","it":"Ieri, ho parlato con lui al telefono.","ipa":"jẹri, ɔ parlạto kon lụj al telɛ̣fono."},{"n":592,"zh":"","en":"Last Tuesday, Vanessa flew from Los Angeles to Mexico City.","it":"Giovedì scorso, Vanessa ha volato da Los Angeles a Città del Messico.","ipa":"ʤovedị skọrso, vanɛ̣sː‿ a volạto da los ạɲʤeles a ʧitːạ dɛl mɛ̣sːiko."},{"n":593,"zh":"","en":"She got up at six (6) in the morning and had a cup of coffee.","it":"Si è svegliata alle sei (6:00) di mattina e ha preso una tazza di caffè.","ipa":"si ɛ̣ sveʎːjạt‿ ạlːe sɛ̣j (6:00) di matːịna e a prẹzo ụna tạʦːa di kafːɛ̣."},{"n":594,"zh":"","en":"At seven-fifteen she left home and drove to the airport.","it":"Alle sette e un quarto è uscita di casa e ha guidato fino all'aeroporto.","ipa":"ạlːe sɛ̣tː‿ e un kwạrto ɛ̣ uʃịta di kạza e a ɡwidạto fịno alːaeropɔ̣rto."},{"n":595,"zh":"","en":"When she got there, she parked the car, walked to the terminal, and checked in.","it":"Quando è arrivata ha parcheggiato, camminato fino al terminal e ha fatto il check-in.","ipa":"kwạndo ɛ̣ arːivạt‿ a parkedʤạto, kamːinạto fịno al tɛ̣rminal e a fạtːo il (…)."},{"n":596,"zh":"","en":"Then she had breakfast at an airport cafe and waited for her flight.","it":"Poi ha fatto colazione in un bar dell'aeroporto e ha aspettato il suo volo.","ipa":"pọj a fạtːo kolaʦjọne in un bar dɛlːaeropọrto e a aspetːạto il sụo vọlo."},{"n":597,"zh":"","en":"The plane departed on time and arrived in Mexico City four (4) hours later.","it":"L'aereo è partito puntuale ed è arrivato a Città del Messico quattro (4) ore dopo.","ipa":"laẹreo ɛ̣ partịto puntwạl‿ ed ɛ̣ arːivạto a ʧitːạ dɛl mɛ̣sːiko kwạtːro (4) ọre dɔ̣po."},{"n":598,"zh":"","en":"Finally, she took a taxi from the airport to her hotel downtown.","it":"Infine, ha preso un taxi dall'aeroporto [fino] al suo hotel in centro [città].","ipa":"infịne, a prẹzo un tạksi dalːaeropọrto [fịno] al sụo otɛ̣l in ʧɛ̣ntro [ʧitːạ]."},{"n":599,"zh":"","en":"Steve always goes to work by car. > Yesterday he went to work by car.","it":"Stefano va sempre al lavoro in macchina. Ieri è andato al lavoro in macchina.","ipa":"stẹfano va sẹmpre al lavọro in mạkːina. jẹri ɛ̣ andạto al lavọro in mạkːina."},{"n":600,"zh":"","en":"Hannah often loses her keys. > She lost her keys last week.","it":"Anna spesso perde le [sue] chiavi. Ha perso le [sue] chiavi la settimana scorsa.","ipa":"ạnːa spɛ̣sːo pɛ̣rde le [sụe] kjạvi. a pɛ̣rso le [sụe] kjạvi la setːimạna skọrsa."}]},{"lesson":7,"range":[601,700],"items":[{"n":601,"zh":"","en":"Zoe meets her friends every night. > She met them last night.","it":"Zoe si vede con i suoi amici ogni sera. Li ha incontrati ieri sera.","ipa":"ʦọe si vẹde kon i swɔ̣j amịʧi ɔ̣ɲːi sẹra. li a iŋkontrạti jẹri sẹra."},{"n":602,"zh":"","en":"I usually buy two (2) newspapers every day. > Yesterday I bought two (2) newspapers.","it":"Solitamente compro due (2) giornali al giorno. Ieri ho comprato due giornali.","ipa":"solitamɛ̣nte kọmpro dụe (2) ʤornạli al ʤọrno. jẹri ɔ komprạto dụe ʤornạli."},{"n":603,"zh":"","en":"We often go to the movies on weekends. > Last Sunday we went to the movies.","it":"Andiamo spesso al cinema nel fine settimana. Domenica scorsa siamo andati al cinema.","ipa":"andjạmo spɛ̣sːo al ʧịnema nɛl fịne setːimạna. domẹnika skọrsa sjạmo andạti al ʧịnema."},{"n":604,"zh":"","en":"I eat an orange every day. > Yesterday I ate an orange.","it":"Mangio un'arancia al giorno. Ieri ho mangiato un'arancia.","ipa":"mạɲʤo unarạɲʧ‿ al ʤọrno. jẹri ɔ maɲʤạto unarạɲʧa."},{"n":605,"zh":"","en":"Tom always takes a shower in the morning. > This morning he took a shower.","it":"Tom fa sempre la doccia di mattina. Stamattina ha fatto la doccia.","ipa":"(…) fa sẹmpre la dɔ̣tʧa di matːịna. stamatːịn‿ a fạtːo la dɔ̣tʧa."},{"n":606,"zh":"","en":"Our friends often come to see us. > They came to see us last Friday.","it":"I nostri amici vengono spesso a trovarci. Sono venuti a trovarci venerdì scorso.","ipa":"i nọstri amịʧi vẹŋɡono spɛ̣sːo a trovạrʧi. sọno venụti a trovạrʧi venerdị skọrso."},{"n":607,"zh":"","en":"I don't watch TV very often.","it":"Non guardo la televisione molto spesso.","ipa":"non ɡwạrdo la televizjọne mọlto spɛ̣sːo."},{"n":608,"zh":"","en":"I didn't watch TV yesterday.","it":"Ieri, non ho guardato la televisione.","ipa":"jẹri, non ɔ ɡwardạto la televizjọne."},{"n":609,"zh":"","en":"Does she go out often?","it":"Lei esce spesso?","ipa":"lɛ̣j ẹʃe spɛ̣sːo?"},{"n":610,"zh":"","en":"Did she go out last night?","it":"Lei è uscita ieri sera?","ipa":"lɛ̣j ɛ̣ uʃịta jẹri sẹra?"},{"n":611,"zh":"","en":"I played tennis yesterday, but I didn't win.","it":"Ieri ho giocato a tennis, ma non ho vinto.","ipa":"jẹri ɔ ʤokạto a tɛ̣nːis, ma non ɔ vịnto."},{"n":612,"zh":"","en":"Did you do your homework? — No, I didn't have time.","it":"Hai fatto i compiti? — No, non ho avuto tempo.","ipa":"ạj fạtːo i kọmpiti? — nɔ, non ɔ avụto tẹmpo."},{"n":613,"zh":"","en":"We went to the movies, but we didn't enjoy the film.","it":"Siamo andati al cinema, ma il film non ci è piaciuto.","ipa":"sjạmo andạti al ʧịnema, ma il film non ʧi ɛ̣ pjaʧụto."},{"n":614,"zh":"","en":"Did you see Fabian yesterday? — No, I didn't.","it":"Hai visto Fabiano ieri? — No, non l'ho visto.","ipa":"ạj vịsto fabjạno jẹri? — nɔ, non lɔ vịsto."},{"n":615,"zh":"","en":"Did it rain on Sunday? — Yes, it did.","it":"È piovuto domenica? — Sì, è piovuto.","ipa":"ɛ̣ pjovụto domẹnika? — sị, ɛ̣ pjovụto."},{"n":616,"zh":"","en":"Did Eveline come to the party? — No, she didn't.","it":"Eveline è venuta alla festa? — No, non è venuta.","ipa":"ɛ̣velin‿ ɛ̣ venụt‿ ạlːa fɛ̣sta? — nɔ, non ɛ̣ venụta."},{"n":617,"zh":"","en":"Did your parents have a good trip? — Yes, they did.","it":"I tuoi genitori hanno fatto buon viaggio? — Sì, hanno fatto buon viaggio.","ipa":"i twɔ̣j ʤenitọri ạnːo fạtːo bwɔ̣n vjạdʤo? sị, ạnːo fạtːo bwɔ̣n vjạdʤo."},{"n":618,"zh":"","en":"I saw Evita, but I didn't see Fausto.","it":"Ho visto Evita, ma non ho visto Fausto.","ipa":"ɔ vịsto ẹvita, ma non ɔ vịsto fạwsto."},{"n":619,"zh":"","en":"They worked on Monday, but they didn't on Tuesday.","it":"Hanno lavorato lunedì, però non hanno lavorato martedì.","ipa":"ạnːo lavorạto lunedị, perɔ̣ non ạnːo lavorạto martedị."},{"n":620,"zh":"","en":"We went to the post office, but we didn't go to the bank.","it":"Siamo andati in posta, ma non siamo andati in banca.","ipa":"sjạmo andạt‿ in pɔ̣sta, ma non sjạmo andạt‿ in bạŋka."},{"n":621,"zh":"","en":"She had a pen, but she didn't have any paper.","it":"Aveva una penna, però non aveva della carta.","ipa":"avẹva ụna pɛ̣nːa, perɔ̣ non avẹva dɛ̣lːa kạrta."},{"n":622,"zh":"","en":"Gerhard did some work in the yard, but he didn't do any work in the house.","it":"Gerardo ha fatto dei lavori nel giardino, ma non ha fatto nessun lavoro in casa.","ipa":"ʤerạrdo a fạtːo dẹj lavọri nɛl ʤardịno, ma non a fạtːo nesːụn lavọro in kạza."},{"n":623,"zh":"","en":"I watched TV last night. How about you? Did you watch TV last night?","it":"Ieri sera, ho guardato la televisione. E tu? Hai guardato la tivù ieri sera?","ipa":"jẹri sẹra, ɔ ɡwardạto la televizjọne. e tu? ạj ɡwardạto la tivụ jẹri sẹra?"},{"n":624,"zh":"","en":"I enjoyed the party. How about you? Did you enjoy the party?","it":"Mi sono divertito alla festa. E tu? Ti sei divertito alla festa?","ipa":"mi sọno divertịto ạlːa fɛ̣sta. e tu? ti sɛ̣j divertịto ạlːa fɛ̣sta?"},{"n":625,"zh":"","en":"I had a nice vacation. How about you? Did you have a nice vacation?","it":"Ho passato una bella vacanza. E tu? Hai passato una bella vacanza?","ipa":"ɔ pasːạto ụna bɛ̣lːa vakạnʦa. e tu? ạj pasːạto ụna bɛ̣lːa vakạnʦa?"},{"n":626,"zh":"","en":"I finished work early. How about you? Did you finish work early?","it":"Ho finito di lavorare presto. E tu? Hai finito di lavorare presto?","ipa":"ɔ finịto di lavorạre prɛ̣sto. e tu? ạj finịto di lavorạre prɛ̣sto?"},{"n":627,"zh":"","en":"I slept well last night. How about you? Did you sleep well last night?","it":"Ho dormito bene ieri notte. E tu? Hai dormito bene ieri notte?","ipa":"ɔ dormịto bẹne jẹri nɔ̣tːe. e tu? ạj dormịto bẹne jẹri nɔ̣tːe?"},{"n":628,"zh":"","en":"I watched TV.","it":"Ho guardato la televisione.","ipa":"ɔ ɡwardạto la televizjọne."},{"n":629,"zh":"","en":"I got up before seven am (7:00).","it":"Mi sono svegliato prima delle sette (7:00) di mattina.","ipa":"mi sọno sveʎːjạto prịma dɛ̣lːe sɛ̣tːe (7:00) di matːịna."},{"n":630,"zh":"","en":"I took a shower.","it":"Ho fatto la doccia.","ipa":"ɔ fạtːo la dɔ̣tʧa."},{"n":631,"zh":"","en":"I bought a magazine.","it":"Ho comprato una rivista.","ipa":"ɔ komprạto ụna rivịsta."},{"n":632,"zh":"","en":"I went to bed before ten-thirty.","it":"Sono andato a letto prima delle dieci e mezza (10:30).","ipa":"sọno andạto a lɛ̣tːo prịma dɛ̣lːe djẹʧi e mɛ̣ʣa (10:30)."},{"n":633,"zh":"","en":"We went to Hong Kong last month.","it":"Il mese scorso, siamo andati a Hong Kong.","ipa":"il mẹze skọrso, sjạmo andạti a (…) (…)."},{"n":634,"zh":"","en":"Where did you stay?","it":"Dove avete alloggiato?","ipa":"dọve avẹte alːodʤạto?"},{"n":635,"zh":"","en":"We stayed with some friends.","it":"Abbiamo alloggiato a casa di alcuni amici.","ipa":"abːjạmo alːodʤạto a kạza di alkụni amịʧi."},{"n":636,"zh":"","en":"I was late for the meeting.","it":"Ero in ritardo per la riunione.","ipa":"ẹro in ritạrdo pɛr la riunjọne"},{"n":637,"zh":"","en":"What time did you get there?","it":"A che ora sei arrivato?","ipa":"a ke ọra sɛ̣j arːivạto?"},{"n":638,"zh":"","en":"I got there at nine-thirty.","it":"Sono arrivato alle nove e trenta (9:30).","ipa":"sọno arːivạto ạlːe nɔ̣v‿ e trɛ̣nta (9:30)."},{"n":639,"zh":"","en":"I played tennis this afternoon.","it":"Questo pomeriggio, ho giocato a tennis.","ipa":"kwɛ̣sto pomerịdʤo, ɔ ʤokạto a tɛ̣nːis."},{"n":640,"zh":"","en":"Did you win?","it":"Hai vinto?","ipa":"ạj vịnto?"},{"n":641,"zh":"","en":"No, I lost.","it":"No, ho perso.","ipa":"nɔ, ɔ pɛ̣rso."},{"n":642,"zh":"","en":"I had a nice vacation.","it":"Ho trascorso una bella vacanza.","ipa":"ɔ traskọrso ụna bɛ̣lːa vakạnʦa."},{"n":643,"zh":"","en":"Where did you go?","it":"Dove sei stato (andato)?","ipa":"dọve sɛ̣j stạto (andạto)?"},{"n":644,"zh":"","en":"I went to the mountains.","it":"Sono andato (stato) in montagna.","ipa":"sọno andạto (stạto) in montạɲːa."},{"n":645,"zh":"","en":"We came home by taxi.","it":"Siamo tornati a casa in taxi.","ipa":"sjạmo tornạti a kạza in tạksi."},{"n":646,"zh":"","en":"How much did it cost?","it":"Quanto è costato?","ipa":"kwạnto ɛ̣ kostạto?"},{"n":647,"zh":"","en":"It cost forty dollars ($40). > It cost thirty euros (€30)","it":"È costato trenta (30) euro.","ipa":"ɛ̣ kostạto trɛ̣nta (30) ẹwro."},{"n":648,"zh":"","en":"I'm tired this morning.","it":"Sono stanco questa mattina.","ipa":"sọno stạŋko kwɛ̣sta matːịna."},{"n":649,"zh":"","en":"Did you sleep well last night?","it":"Hai dormito bene ieri notte?","ipa":"ạj dormịto bẹne jẹri nɔ̣tːe?"},{"n":650,"zh":"","en":"No, I didn't sleep very well.","it":"No, non ho dormito molto bene.","ipa":"nɔ, non ɔ dormịto mọlto bẹne."},{"n":651,"zh":"","en":"We went to the beach yesterday.","it":"Ieri, siamo andati in spiaggia.","ipa":"jẹri, sjạmo andạt‿ in spjạdʤa."},{"n":652,"zh":"","en":"Was the weather nice?","it":"Il tempo era bello?","ipa":"il tẹmpo ẹra bɛ̣lːo?"},{"n":653,"zh":"","en":"Yes, the weather was great.","it":"Sì, il tempo era fantastico.","ipa":"sị, il tẹmpo ẹra fantạstiko."},{"n":654,"zh":"","en":"The window is broken.","it":"La finestra è rotta.","ipa":"la finɛ̣stra ɛ̣ rọtːa."},{"n":655,"zh":"","en":"How did it break?","it":"Come si è rotta?","ipa":"kọme si ɛ̣ rọtːa?"},{"n":656,"zh":"","en":"I don't know how it broke.","it":"Non lo so, come si sia rotta.","ipa":"non lo sɔ, kọme si sịa rọtːa."},{"n":657,"zh":"","en":"We went to the movies, but the film wasn't very good. We didn't enjoy it.","it":"Siamo andati al cinema, ma il film non era molto bello. Non ci è piaciuto.","ipa":"sjạmo andạti al ʧịnema, ma il film non ẹra mọlto bɛ̣lːo. non ʧi ɛ̣ pjaʧụto."},{"n":658,"zh":"","en":"Giovanni bought some new clothes yesterday: two (2) shirts and a pair of pants.","it":"Giovanni ha comprato dei nuovi vestiti ieri: due (2) magliette e un paio di pantaloni.","ipa":"ʤovạnːi a komprạto dẹj nwɔ̣vi vestịti jẹri: dụe (2) maʎːjẹtː‿ e un pạjo di pantalọni."},{"n":659,"zh":"","en":"Did it rain yesterday? — No, it was a nice day.","it":"È piovuto ieri? — No, era una bella giornata.","ipa":"ɛ̣ pjovụto jẹri? — nɔ, ẹra ụna bɛ̣lːa ʤornạta."},{"n":660,"zh":"","en":"We were tired, so we didn't stay long at the party.","it":"Eravamo stanchi, perciò non siamo rimasti a lungo alla festa.","ipa":"eravạmo stạŋki, perʧɔ̣ non sjạmo rimạsti a lụŋɡo ạlːa fɛ̣sta."},{"n":661,"zh":"","en":"It was very warm in the room, so I opened a window.","it":"Faceva molto caldo nella stanza, quindi ho aperto la finestra.","ipa":"faʧẹva mọlto kạldo nɛ̣lːa stạnʦa, kwịndi ɔ apɛ̣rto la finɛ̣stra."},{"n":662,"zh":"","en":"Did you call Ingrid this morning? — No, I didn't have time.","it":"Hai chiamato Ingrid stamattina? — No, non ne ho avuto il tempo.","ipa":"ạj kjamạto (…) stamatːịna? — nɔ, non ne ɔ avụto il tẹmpo."},{"n":663,"zh":"","en":"I cut my hand this morning. — How did you do that?","it":"Mi sono tagliato la mano questa mattina. — Come hai fatto?","ipa":"mi sọno taʎːjạto la mạno kwɛ̣sta matːịna. — kọme ạj fạtːo?"},{"n":664,"zh":"","en":"Why weren't you at the meeting yesterday? — I didn't know about a meeting.","it":"Perché ieri non c'eri alla riunione? — Io non sapevo ci fosse una riunione.","ipa":"perkɛ̣ jẹri non ʧẹri ạlːa riunjọne? — ịo non sapẹvo ʧi fɔ̣sːe ụna riunjọne."},{"n":665,"zh":"","en":"It's six o'clock (6:00) now. Luka's at home watching TV.","it":"Adesso, sono le sei (6:00) in punto. Luca è a casa e sta guardando la televisione.","ipa":"adɛ̣sːo, sọno le sɛ̣j (6:00) in pụnto. lụka ɛ̣ a kạza e sta ɡwardạndo la televizjọne."},{"n":666,"zh":"","en":"At four o'clock (4:00) he wasn't at home. He was at the gym.","it":"Alle quattro (4:00) precise lui non era a casa. Era in palestra.","ipa":"ạlːe kwạtːro (4:00) preʧịze lụj non ẹra a kạza. ẹra in palɛ̣stra."},{"n":667,"zh":"","en":"He was swimming in the pool, not watching TV.","it":"Stava nuotando in piscina, non stava guardando la tivù.","ipa":"stạva nwotạndo in piʃịna, non stạva ɡwardạndo la tivụ."},{"n":668,"zh":"","en":"What were you doing at eleven-thirty yesterday? Were you working?","it":"Cosa stavi facendo ieri alle undici e mezza (11:30)? Stavi lavorando?","ipa":"kɔ̣za stạvi faʧɛ̣ndo jẹri ạlːe ụndiʧi e mɛ̣ʣa (11:30)? stạvi lavorạndo?"},{"n":669,"zh":"","en":"What did he say? — I don't know, I wasn't listening.","it":"Che cosa ha detto lui? — Non lo so, non stavo ascoltando.","ipa":"ke kɔ̣z‿ a dɛ̣tːo lụj? — non lo sɔ, non stạvo askoltạndo."},{"n":670,"zh":"","en":"It was raining, so we didn't go out.","it":"Pioveva, così non siamo usciti.","ipa":"pjovẹva, kozị non sjạmo uʃịti."},{"n":671,"zh":"","en":"In two-thousand-one we were living in Japan.","it":"Nel duemilauno (2001) vivevamo in Giappone.","ipa":"nɛl dwemilaụno () vivevạmo in ʤapːọne."},{"n":672,"zh":"","en":"Today she's wearing a skirt, but yesterday she was wearing pants.","it":"Oggi lei indossa una gonna, ma ieri indossava dei pantaloni.","ipa":"ɔ̣dʤi lɛ̣j indɔ̣sːa ụna ɡɔ̣nːa, ma jẹri indosːạva dẹj pantalọni."},{"n":673,"zh":"","en":"I woke up early yesterday. It was a beautiful morning.","it":"Ieri, mi sono svegliato presto. Era una mattina splendida.","ipa":"jẹri, mi sọno sveʎːjạto prɛ̣sto. ẹra ụna matːịna splɛ̣ndida."},{"n":674,"zh":"","en":"The sun was shining, and the birds were singing.","it":"Il sole splendeva e gli uccelli cantavano.","ipa":"il sọle splendẹva e ʎːi utʧɛ̣lːi kantạvano."},{"n":675,"zh":"","en":"I was working at ten-thirty last night.","it":"Ieri notte, alle dieci e mezza, stavo lavorando.","ipa":"jẹri nɔ̣tːe, ạlːe djẹʧi e mɛ̣ʣa, stạvo lavorạndo."},{"n":676,"zh":"","en":"It wasn't raining when we went out.","it":"Non stava piovendo quando siamo usciti.","ipa":"non stạva pjovɛ̣ndo kwạndo sjạmo uʃịti."},{"n":677,"zh":"","en":"What were you doing at three [o'clock] (3:00)?","it":"Voi, cosa stavate facendo alle tre (3:00) esatte?","ipa":"vọj, kɔ̣za stạvi faʧɛ̣ndo ạlːe trɛ (3:00) ezạtːe?"},{"n":678,"zh":"","en":"Dmitry and Irina were at the supermarket buying food.","it":"Dimitry e Irina erano al supermercato a comprare del cibo.","ipa":"dimitrj e irịna ẹrano al supermerkạto a komprạre dɛl ʧịbo."},{"n":679,"zh":"","en":"Santo was in his car driving.","it":"Santo stava guidando la sua macchina.","ipa":"sạnto stạva ɡwidạndo la sụa mạkːina."},{"n":680,"zh":"","en":"Dennis was at the station waiting for a train.","it":"Dennis era alla stazione ad aspettare il treno.","ipa":"dɛ̣nːis ẹra ạlːa staʦjọne ad aspetːạre il trẹno."},{"n":681,"zh":"","en":"The old couple were in the park taking a walk.","it":"La coppia di anziani era al parco a fare una passeggiata.","ipa":"la kɔ̣pːja di anʦjạni ẹra al pạrko a fạre ụna pasːedʤạta."},{"n":682,"zh":"","en":"At eight forty-five (8:45) she was washing her car.","it":"Alle otto e quarantacinque (8:45), lei stava lavando la sua autovettura.","ipa":"ạlːe ɔ̣tːo e kwarantaʧịŋkwe (8:45), lɛ̣j stạva lavạndo la sụa awtovetːụra."},{"n":683,"zh":"","en":"At ten forty-five (10:45) she was playing tennis.","it":"Alle dieci e tre quarti (10:45), lei stava giocando a tennis.","ipa":"ạlːe djẹʧi e trɛ kwạrti (10:45), lɛ̣j stạva ʤokạndo a tɛ̣nːis."},{"n":684,"zh":"","en":"At eight o'clock (8:00) she was reading the news.","it":"Alle otto (8:00) in punto, lei stava leggendo il giornale.","ipa":"ạlːe ɔ̣tːo (8:00) in pụnto, lɛ̣j stạva ledʤɛ̣ndo il ʤornạle."},{"n":685,"zh":"","en":"At twelve-ten she was cooking lunch.","it":"A mezzogiorno e dieci (12:10), lei stava cucinando il pranzo.","ipa":"a meʣoʤọrno e djẹʧi (12:10), lɛ̣j stạva kuʧinạndo il prạnʦo."},{"n":686,"zh":"","en":"At seven-fifteen (7:15) she was having breakfast.","it":"Alle sette e un quarto (7:15), lei stava facendo colazione.","ipa":"ạlːe sɛ̣tː‿ e un kwạrto (7:15), lɛ̣j stạva faʧɛ̣ndo kolaʦjọne."},{"n":687,"zh":"","en":"At nine thirty (9:30) she was cleaning the kitchen.","it":"Alle nove e mezza (9:30), lei stava pulendo la cucina.","ipa":"ạlːe nɔ̣v‿ e mɛ̣ʣa (9:30), lɛ̣j stạva pulɛ̣ndo la kuʧịna."},{"n":688,"zh":"","en":"Where were you living in nineteen ninety-nine (1999)?","it":"Dove vivevi nel millenovecentonovantanove (1999)?","ipa":"dọve vivẹvi nɛl milːenoveʧentonovantanɔ̣ve ()?"},{"n":689,"zh":"","en":"What were you doing at two [o'clock] (2:00)?","it":"Cosa stavi facendo alle due (2:00) [in punto]?","ipa":"kɔ̣za stạvi faʧɛ̣ndo ạlːe dụe (2:00) [in pụnto]?"},{"n":690,"zh":"","en":"Was it raining when you got up?","it":"Stava piovendo quando ti sei alzato?","ipa":"stạva pjovɛ̣ndo kwạndo ti sɛ̣j alʦạto?"},{"n":691,"zh":"","en":"Why was she driving so fast?","it":"Perché lei stava guidando così veloce?","ipa":"perkɛ̣ lɛ̣j stạva ɡwidạndo kozị velọʧe?"},{"n":692,"zh":"","en":"Why was he wearing a suit yesterday?","it":"Perché ieri, lui indossava un completo?","ipa":"perkɛ̣ jẹri, lụj indosːạva un komplẹto?"},{"n":693,"zh":"","en":"He wasn't wearing a jacket.","it":"Lui non indossava una giacca.","ipa":"lụj non indosːạva ụna ʤạkːa."},{"n":694,"zh":"","en":"He was carrying a bag.","it":"Lui non portava una borsa.","ipa":"lụj non portạva ụna bọrsa."},{"n":695,"zh":"","en":"He wasn't going to the dentist.","it":"Lui non stava andando dal dentista.","ipa":"lụj non stạv‿ andạndo dal dentịsta."},{"n":696,"zh":"","en":"He was eating ice cream.","it":"Lui stava mangiando un gelato.","ipa":"lụj stạva maɲʤạndo un ʤelạto."},{"n":697,"zh":"","en":"He wasn't carrying an umbrella.","it":"Lui non aveva con sè un ombrello.","ipa":"lụj non avẹva kon sɛ̣ un ombrɛ̣lːo."},{"n":698,"zh":"","en":"He wasn't going home.","it":"Lui non stava andando a casa.","ipa":"lụj non stạv‿ andạndo a kạza."},{"n":699,"zh":"","en":"He was wearing a hat.","it":"Lui indossava un cappello.","ipa":"lụj indosːạva un kapːɛ̣lːo."},{"n":700,"zh":"","en":"He wasn't riding a bicycle.","it":"Lui non stava andando in bicicletta.","ipa":"lụj non stạv‿ andạndo in biʧiklɛ̣tːa."}]},{"lesson":8,"range":[701,800],"items":[{"n":701,"zh":"","en":"What was Jose doing when the phone rang?","it":"Cosa stava facendo Jose quando il telefono ha squillato?","ipa":"kɔ̣za stạva faʧɛ̣ndo (…) kwạndo il telɛ̣fono a skwilːạto?"},{"n":702,"zh":"","en":"He was reading a book.","it":"Stava leggendo un libro.","ipa":"stạva ledʤɛ̣ndo un lịbro."},{"n":703,"zh":"","en":"What did he do when the phone rang?","it":"Cosa ha fatto quando il telefono ha squillato?","ipa":"kɔ̣z‿ a fạtːo kwạndo il telɛ̣fono a skwilːạto?"},{"n":704,"zh":"","en":"He stopped reading and answered the phone.","it":"Ha smesso di leggere e ha risposto al telefono.","ipa":"a smɛ̣sːo di lɛ̣dʤere e a rispɔ̣sto al telɛ̣fono."},{"n":705,"zh":"","en":"What did you do yesterday morning?","it":"Cosa hai fatto ieri mattina?","ipa":"kɔ̣z‿ ạj fạtːo jẹri matːịna?"},{"n":706,"zh":"","en":"What were you doing at ten thirty (10:30)?","it":"Cosa stavi facendo alle dieci e mezza?","ipa":"kɔ̣za stạvi faʧɛ̣ndo ạlːe djẹʧi e mɛ̣ʣa?"},{"n":707,"zh":"","en":"We played tennis from ten (10:00) to eleven thirty (11:30).","it":"Noi abbiamo giocato a tennis dalle dieci (10:00) alle undici e trenta (11:30).","ipa":"nọj abːjạmo ʤokạto a tɛ̣nːis dạlːe djẹʧi (10:00) ạlːe ụndiʧi e trɛ̣nta (11:30)."},{"n":708,"zh":"","en":"We were playing tennis.","it":"Stavamo giocando a tennis.","ipa":"stavạmo ʤokạndo a tɛ̣nːis."},{"n":709,"zh":"","en":"Did you watch the basketball game on TV last night?","it":"Ieri sera, hai guardato la partita di pallacanestro in televisione?","ipa":"jẹri sẹra, ạj ɡwardạto la partịta di palːakanɛ̣stro in televizjọne?"},{"n":710,"zh":"","en":"Were you watching TV when I called you?","it":"Stavi guardando la tele, quando ti ho chiamato?","ipa":"stạvi ɡwardạndo la tẹle, kwạndo ti ɔ kjamạto?"},{"n":711,"zh":"","en":"It didn't rain while we were on vacation.","it":"Non è piovuto mentre eravamo in vacanza.","ipa":"non ɛ̣ pjovụto mɛ̣ntre eravạmo in vakạnʦa."},{"n":712,"zh":"","en":"It wasn't raining when I got up.","it":"Non stava piovendo quando mi sono alzato.","ipa":"non stạva pjovɛ̣ndo kwạndo mi sọno alʦạto."},{"n":713,"zh":"","en":"I started work at nine (9:00) and finished at four thirty (4:30). So at two thirty (2:30), I was in the middle of working.","it":"Ho iniziato a lavorare alle nove (9:00) e ho smesso alle quattro e mezza (9:30). Perciò, alle due e trenta (2:30), ero nel bel mezzo del mio lavoro.","ipa":"ɔ iniʦjạto a lavorạre ạlːe nɔ̣ve (9:00) e ɔ smɛ̣sːo ạlːe kwạtːro e mɛ̣ʣa (4:30). perʧɔ̣, ạlːe dụe e trɛ̣nta (2:30), ẹro nɛl bɛl mɛ̣ʣo dɛl mịo lavọro."},{"n":714,"zh":"","en":"It was raining when we went out.","it":"Pioveva quando siamo usciti.","ipa":"pjovẹva kwạndo sjạmo uʃịti."},{"n":715,"zh":"","en":"I saw them this morning. They were waiting at the bus stop.","it":"Li ho visti stamattina. Stavano aspettando il bus alla fermata.","ipa":"li ɔ vịsti stamatːịna. stạvano aspetːạndo il bus ạlːa fermạta."},{"n":716,"zh":"","en":"She fell asleep while reading.","it":"Si è addormentata mentre leggeva.","ipa":"si ɛ̣ adːormentạta mɛ̣ntre ledʤẹva."},{"n":717,"zh":"","en":"Khalid broke his arm last week.","it":"Khalid si è rotto il braccio la settimana scorsa.","ipa":"kạlid si ɛ̣ rọtːo il brạtʧo la setːimạna skọrsa."},{"n":718,"zh":"","en":"It happened when he was painting his room.","it":"È successo quando stava dipingendo la sua stanza.","ipa":"ɛ̣ sutʧɛ̣sːo kwạndo stạva dipiɲʤɛ̣ndo la sụa stạnʦa."},{"n":719,"zh":"","en":"He fell off the ladder.","it":"È caduto dalla scala.","ipa":"ɛ̣ kadụto dạlːa skạla."},{"n":720,"zh":"","en":"The train arrived at the station, and she got off.","it":"Il treno è arrivato alla stazione e lei è scesa.","ipa":"il trẹno ɛ̣ arːivạto ạlːa staʦjọn‿ e lɛ̣j ɛ̣ ʃẹza."},{"n":721,"zh":"","en":"Two friends of hers were waiting to meet her.","it":"Due suoi amici stavano aspettando d'incontrarla.","ipa":"dụe swɔ̣j amịʧi stạvano aspetːạndo diŋkontrạrla."},{"n":722,"zh":"","en":"Yesterday she was walking down the street when she met Albert.","it":"Ieri lei stava camminando per strada, quando ha incontrato Alberto.","ipa":"jẹri lɛ̣j stạva kamːinạndo pɛr strạda, kwạndo a iŋkontrạto albɛ̣rto."},{"n":723,"zh":"","en":"He was going to the station to catch a train, and he was carrying a bag.","it":"Lui stava andando alla stazione per prendere il treno e portava con sé una borsa.","ipa":"lụj stạv‿ andạndo ạlːa staʦjọne pɛr prɛ̣ndere il trẹno e portạva kon sɛ̣ ụna bọrsa."},{"n":724,"zh":"","en":"They stopped to talk for a few minutes.","it":"Si sono fermati a parlare per qualche minuto.","ipa":"si sọno fermạti a parlạre pɛr kwạlke minụto."},{"n":725,"zh":"","en":"Was Lara busy when you went to see her?","it":"Lara era occupata quando sei andata a trovarla?","ipa":"lạra ẹra okːupạta kwạndo sɛ̣j andạt‿ a trovạrla?"},{"n":726,"zh":"","en":"Yes, she was studying.","it":"Sì, stava studiando.","ipa":"sị, stạva studjạndo."},{"n":727,"zh":"","en":"What time did the mail arrive this morning?","it":"A che ora è arrivata la posta stamattina?","ipa":"a ke ọra ɛ̣ arːivạta la pɔ̣sta stamatːịna?"},{"n":728,"zh":"","en":"It came while he was having breakfast.","it":"È arrivata mentre lui stava facendo colazione.","ipa":"ɛ̣ arːivạta mɛ̣ntre lụj stạva faʧɛ̣ndo kolaʦjọne."},{"n":729,"zh":"","en":"Was Marta at work today?","it":"Oggi Marta era al lavoro?","ipa":"ɔ̣dʤi mạrta ẹra al lavọro?"},{"n":730,"zh":"","en":"No, she didn't go to work. She was sick.","it":"No, non è andata al lavoro. Era malata.","ipa":"nɔ, non ɛ̣ andạt‿ al lavọro. ẹra malạta."},{"n":731,"zh":"","en":"How fast were you driving when the police stopped you?","it":"A che velocità stavi andando quando la polizia ti ha fermato?","ipa":"a ke veloʧitạ stạvi andạndo kwạndo la poliʦịa ti a fermạto?"},{"n":732,"zh":"","en":"I'm not sure, but I wasn't driving very fast.","it":"Non lo so di preciso, ma non stavo andando molto veloce.","ipa":"non lo sɔ di preʧịzo, ma non stạvo andạndo mọlto velọʧe."},{"n":733,"zh":"","en":"Did your team win the baseball game yesterday?","it":"Ieri la tua squadra ha vinto la partita di baseball?","ipa":"jẹri la tụa skwạdra a vịnto la partịta di (…)?"},{"n":734,"zh":"","en":"No, the weather was very bad, so we didn't play.","it":"No, il tempo era pessimo, per cui non abbiamo giocato.","ipa":"nɔ, il tẹmpo ẹra pẹsːimo, pɛr kwị non abːjạmo ʤokạto."},{"n":735,"zh":"","en":"We were playing baseball when I hit the ball and broke a window.","it":"Stavamo giocando a baseball quando ho colpito la palla e ho rotto una finestra.","ipa":"stavạmo ʤokạndo a (…) kwạnd‿ ɔ kolpịto la pạlːa e ɔ rọtːo ụna finɛ̣stra."},{"n":736,"zh":"","en":"Did you see Clara last night?","it":"Hai visto Clara ieri sera?","ipa":"ạj vịsto klạra jẹri sẹra?"},{"n":737,"zh":"","en":"Yes, she was wearing a very nice jacket.","it":"Sì, indossava una giacca molto carina.","ipa":"sị, indosːạva ụna ʤạkːa mọlto karịna."},{"n":738,"zh":"","en":"What were you doing at two [o'clock] (2:00) this morning?","it":"Cosa stavi facendo alle due (2:00) precise questa mattina?","ipa":"kɔ̣za stạvi faʧɛ̣ndo ạlːe dụe (2:00) [preʧịze] kwɛ̣sta matːịna?"},{"n":739,"zh":"","en":"I was asleep.","it":"Stavo dormendo.","ipa":"stạvo dormɛ̣ndo."},{"n":740,"zh":"","en":"I lost my key last night.","it":"Ho perso le [mie] chiavi ieri sera.","ipa":"ɔ pɛ̣rso le [mịe] kjạvi jẹri sẹra."},{"n":741,"zh":"","en":"How did you get into your apartment?","it":"Come sei entrato nel tuo appartamento?","ipa":"kọme sɛ̣j entrạto nɛl tụo apːartamɛ̣nto?"},{"n":742,"zh":"","en":"I climbed in through a window.","it":"Sono entrato arrampicandomi fin sù la finestra.","ipa":"sọno entrạto arːampikạndomi fin sụ la finɛ̣stra."},{"n":743,"zh":"","en":"Bernard used to work in a factory.","it":"Bernardo lavorava in una fabbrica.","ipa":"bernạrdo lavorạva in ụna fạbːrika."},{"n":744,"zh":"","en":"Now he works in a supermarket.","it":"Adesso, lui lavora in un supermercato.","ipa":"adɛ̣sːo, lụj lavọra in un supermerkạto."},{"n":745,"zh":"","en":"When I was a child, I used to like chocolate.","it":"Quando ero bambino, mi piaceva la cioccolata.","ipa":"kwạndo ẹro bambịno, mi pjaʧẹva la ʧokːolạta."},{"n":746,"zh":"","en":"I used to read a lot of books, but I don't read much these days.","it":"Leggevo molti libri, ma non leggo più un granchè ultimamente.","ipa":"ledʤẹvo mọlti lịbri, ma non lẹɡːo piụ un ɡraŋkẹ ultimamɛ̣nte."},{"n":747,"zh":"","en":"Emilia has short hair now, but it used to be very long.","it":"Emilia porta i capelli corti ora, ma una volta erano molto lunghi.","ipa":"emịlja pɔ̣rta i kapɛ̣lːi kọrti ọra, ma ụna vɔ̣lta ẹrano mọlto lụŋɡi."},{"n":748,"zh":"","en":"They used to live on the same street as us.","it":"Vivevano nella nostra stessa via.","ipa":"vivẹvano nɛ̣lːa nɔ̣stra stɛ̣sːa vịa."},{"n":749,"zh":"","en":"We used to see them a lot, but we don't see them very often these days.","it":"Eravamo soliti vederli molto, ma ultimamente non li vediamo molto spesso.","ipa":"eravạmo sɔ̣liti vedẹrli mọlto, ma ultimamɛ̣nte non li vedjạmo mọlto spɛ̣sːo."},{"n":750,"zh":"","en":"Nadya used to have a piano, but she sold it a few years ago.","it":"Nadia aveva un pianoforte, ma l'ha venduto qualche anno fa.","ipa":"nạdj‿ avẹva un pjanofɔ̣rte, ma la vendụto kwạlke ạnːo fa."},{"n":751,"zh":"","en":"When I was a child, I didn't use to like mushrooms.","it":"Quando ero bambino, non mi piacevano i funghi.","ipa":"kwạndo ẹro bambịno, non mi pjaʧẹvano i fụŋɡi."},{"n":752,"zh":"","en":"Where did you use to live before you came here?","it":"Dove vivevi prima di venire qui?","ipa":"dọve vivẹvi prịma di venịre kwị?"},{"n":753,"zh":"","en":"He used to play baseball.","it":"Lui giocava a baseball.","ipa":"lụj ʤokạv‿ a (…)."},{"n":754,"zh":"","en":"He used to be a taxi driver.","it":"Faceva il tassista.","ipa":"faʧẹva il tasːịsta."},{"n":755,"zh":"","en":"They used to live in the country.","it":"Vivevano in campagna.","ipa":"vivẹvano in kampạɲːa."},{"n":756,"zh":"","en":"I used to wear glasses.","it":"Una volta portavo gli occhiali.","ipa":"ụna vɔ̣lta portạvo ʎːi okːjạli."},{"n":757,"zh":"","en":"This building used to be a hotel.","it":"Questo palazzo, una volta, era un hotel.","ipa":"kwɛ̣sto palạʦːo, ụna vɔ̣lta, ẹra un otɛ̣l."},{"n":758,"zh":"","en":"Do you play sports? — No, I used to swim every day though.","it":"Pratichi degli sport? — No, tuttavia ero solito nuotare tutti i giorni.","ipa":"prạtiki dẹʎːi spɔrt? — nɔ, tutːavịa ẹro sɔ̣lito nwotạre tụtː‿ i ʤọrni."},{"n":759,"zh":"","en":"Do you go out much? — No, I used to go out three (3) nights a week though.","it":"Esci molto? — No, però una volta uscivo tre (3) sere a settimana.","ipa":"ẹʃi mọlto? — nɔ, perɔ̣ ụna vɔ̣lta uʃịvo trɛ (3) sẹre a setːimạna."},{"n":760,"zh":"","en":"Do you play any instruments? — No, I used to play guitar though.","it":"Suoni qualche strumento musicale? — No, suonavo la chitarra, però.","ipa":"swɔ̣ni kwạlke strumɛ̣nto muzikạle? — nɔ, swonạvo la kitạrːa, perɔ̣."},{"n":761,"zh":"","en":"Do you like to read? — I don't have the time, but I used to read a lot.","it":"Ti piace leggere? — Non ne ho il tempo, ma leggevo molto in passato.","ipa":"ti pjạʧe lɛ̣dʤere? — non ne ɔ il tẹmpo, ma ledʤẹvo mọlto in pasːạto."},{"n":762,"zh":"","en":"Do you travel much? — I'd like to. I used to travel several times a year though.","it":"Viaggi molto? — Mi piacerebbe. In passato, tuttavia, viaggiavo più volte all'anno.","ipa":"vjạdʤi mọlto? — mi pjaʧerɛ̣bːe. in pasːạto, tutːavịa, vjadʤạvo piụ vɔ̣lte alːạnːo."},{"n":763,"zh":"","en":"I used to play tennis, but I stopped playing a few years ago.","it":"Giocavo a tennis, ma ho smesso qualche anno fa.","ipa":"ʤokạvo a tɛ̣nːis, ma ɔ smɛ̣sːo kwạlke ạnːo fa."},{"n":764,"zh":"","en":"Do you play any sports? — Yes, I play basketball.","it":"Pratichi qualche sport? — Sì, gioco a pallacanestro.","ipa":"prạtiki kwạlke spɔrt? — sị, ʤɔ̣ko a palːakanɛ̣stro."},{"n":765,"zh":"","en":"Do you have a car? — No, I used to have one (1), but I sold it.","it":"Possiedi una vettura? — No, ne possedevo una in passato, ma l'ho venduta.","ipa":"posːjẹdi ụna vetːụra? — nɔ, ne posːedẹvo ụna in pasːạto, ma lɔ vendụta."},{"n":766,"zh":"","en":"Igor used to be a waiter. Now he's the manager of a hotel.","it":"Igor faceva il cameriere. Adesso è direttore d'albergo.","ipa":"ịɡor faʧẹva il kamerjẹre. adɛ̣sːo ɛ̣ diretːọre dalbɛ̣rɡo."},{"n":767,"zh":"","en":"Do you go to work by car? — Sometimes, but most days I go by subway.","it":"Vai al lavoro in macchina? — Qualche volta, se no vado quasi sempre in metropolitana.","ipa":"vạj al lavọro in mạkːina? — kwạlke vɔ̣lta, se nɔ vạdo kwạzi sẹmpre in metropolitạna."},{"n":768,"zh":"","en":"When I was a child, I never used to eat meat, but I eat it now.","it":"Quando ero piccolo non mangiavo mai la carne, invece adesso la mangio.","ipa":"kwạndo ẹro pịkːolo non maɲʤạvo mạj la kạrne, invẹʧe adɛ̣sːo la mạɲʤo."},{"n":769,"zh":"","en":"Angela loves to watch TV. She watches it every night.","it":"Angela adora guardare la tivù. La guarda ogni sera.","ipa":"ạɲʤel‿ adɔ̣ra ɡwardạre la tivụ. la ɡwạrda ɔ̣ɲːi sẹra."},{"n":770,"zh":"","en":"We used to live near the airport, but we moved downtown a few years ago.","it":"Abitavamo vicino all'aeroporto, ma qualche anno fa ci siamo trasferiti in centro.","ipa":"abitạvamo viʧịno alːaeropɔ̣rto, ma kwạlke ạnːo fa ʧi sjạmo trasferịt‿ in ʧɛ̣ntro."},{"n":771,"zh":"","en":"Normally I start work at seven am (7:00), so I get up very early.","it":"Di solito inizio a lavorare alle sette (7:00) di mattina, dunque mi alzo molto presto.","ipa":"di sɔ̣lito inịʦjo a lavorạre ạlːe sɛ̣tːe (7:00) di matːịna, dụŋkwe mi ạlʦo mọlto prɛ̣sto."},{"n":772,"zh":"","en":"What games did you use to play when you were a child?","it":"A che giochi giocavi quando eri bambino?","ipa":"a ke ʤọki ʤokạvi kwạndo ẹri bambịno?"},{"n":773,"zh":"","en":"Have you been to France? — No, I haven't.","it":"Sei stato in Francia? — No, non ci sono stato.","ipa":"sɛ̣j stạto in frạɲʧa? — nɔ, non ʧi sọno stạto."},{"n":774,"zh":"","en":"We've been to Canada, but we haven't been to Alaska.","it":"Siamo stati in Canada, ma non siamo stati in Alaska.","ipa":"sjạmo stạt‿ in kạnada, ma non sjạmo stạt‿ in alạska."},{"n":775,"zh":"","en":"Shakira's an interesting person. She's had many different jobs and has lived in many places.","it":"Shakira è una persona interessante. Ha fatto molti lavori diversi e ha vissuto in parecchi luoghi.","ipa":"sakịra ɛ̣ ụna persọna interesːạnte. a fạtːo mọlti lavọri divɛ̣rsi e a visːụto in parɛ̣kːi lwɔ̣ɡi."},{"n":776,"zh":"","en":"I've seen that man before, but I can't remember where.","it":"Ho già visto quell'uomo prima d'ora, ma non ricordo dove.","ipa":"ɔ ʤạ vịsto kwɛlːwɔ̣mo prịma dọra, ma non rikɔ̣rdo dọve."},{"n":777,"zh":"","en":"How many times has Brazil won the World Cup?","it":"Quante volte il Brasile ha vinto la Coppa del Mondo?","ipa":"kwạnte vɔ̣lte il brazịle a vịnto la kɔ̣pːa dɛl mọndo?"},{"n":778,"zh":"","en":"Have you read this book? — Yes, I've read it twice.","it":"Hai letto questo libro? — Sì, l'ho letto due volte.","ipa":"ạj lɛ̣tːo kwɛ̣sto lịbro? — sị, lɔ lɛ̣tːo dụe vɔ̣lte."},{"n":779,"zh":"","en":"Has she ever been to Australia? — Yes, once.","it":"Lei, è mai stata in Australia? — Sì, una volta.","ipa":"lɛ̣j, ɛ̣ mạj stạta in awstrạlja? — sị, ụna vɔ̣lta."},{"n":780,"zh":"","en":"Have you ever played golf? — Yes, I play a lot.","it":"Hai mai giocato a golf? — Sì, ci gioco molto.","ipa":"ạj mạj ʤokạto a ɡolf? — sị, ʧi ʤɔ̣ko mọlto."},{"n":781,"zh":"","en":"My sister's never traveled by plane.","it":"Mia sorella non ha mai viaggiato in aereo.","ipa":"mịa sorɛ̣lːa non a mạj vjadʤạto in aẹreo."},{"n":782,"zh":"","en":"I've never ridden a horse.","it":"Non ho mai cavalcato un cavallo.","ipa":"non ɔ mạj kavalkạto un kavạlːo."},{"n":783,"zh":"","en":"Who is that man? — I don't know, I've never seen him before.","it":"Chi è quell'uomo? — Non lo so, non l'ho mai visto prima.","ipa":"ki ɛ̣ kwɛlːwɔ̣mo? — non lo sɔ, non lɔ mạj vịsto prịma."},{"n":784,"zh":"","en":"Have you ever been to Montreal? — No, never.","it":"Sei mai stato a Montreal? — No, mai.","ipa":"sɛ̣j mạj stạto a mɔ̣ntreal? — nɔ, mạj."},{"n":785,"zh":"","en":"Have you ever played golf? — No, never.","it":"Hai mai giocato a golf? — No, mai.","ipa":"ạj mạj ʤokạto a ɡolf? — nɔ, mạj."},{"n":786,"zh":"","en":"Have you ever been to South Korea? — Yes, once.","it":"Sei mai stato in Corea del Sud? — Sì, una volta.","ipa":"sɛ̣j mạj stạto in korẹa dɛl sud? — sị, ụna vɔ̣lta."},{"n":787,"zh":"","en":"Have you ever lost your passport? — No, never.","it":"Hai mai perso il [tuo] passaporto? — No, mai.","ipa":"ạj mạj pɛ̣rso il [tụo] pasːapɔ̣rto? — nɔ, mạj."},{"n":788,"zh":"","en":"Have you ever flown in a helicopter? — No, never.","it":"Hai mai volato in elicottero? — No, mai.","ipa":"ạj mạj volạto in elikɔ̣tːero? — nɔ, mạj."},{"n":789,"zh":"","en":"Have you ever won a race? — Yes, a few times.","it":"Hai mai vinto una gara? — Sì, un paio di volte.","ipa":"ạj mạj vịnto ụna ɡạra? — sị, un pạjo di vɔ̣lte."},{"n":790,"zh":"","en":"Have you ever been to Peru? — Yes, twice.","it":"Sei mai stato in Perù? — Sì, due volte.","ipa":"sɛ̣j mạj stạto in perụ? — sị, dụe vɔ̣lte."},{"n":791,"zh":"","en":"Have you ever driven a bus? — No, never.","it":"Hai mai guidato un autobus? — No, mai.","ipa":"ạj mạj ɡwidạto un ạwtobus? — nɔ, mạj."},{"n":792,"zh":"","en":"Have you ever broken your leg? — Yes, once.","it":"Ti sei mai rotto una gamba? — Sì, una volta.","ipa":"ti sɛ̣j mạj rọtːo ụna ɡạmba? — sị, ụna vɔ̣lta."},{"n":793,"zh":"","en":"She's been to Spain twice.","it":"È stata in Spagna due volte.","ipa":"ɛ̣ stạta in spạɲːa dụe vɔ̣lte."},{"n":794,"zh":"","en":"She's been to Japan once.","it":"È stata in Giappone una volta.","ipa":"ɛ̣ stạta in ʤapːọne ụna vɔ̣lta."},{"n":795,"zh":"","en":"She's won a race several times.","it":"Ha vinto una gara diverse volte.","ipa":"a vịnto ụna ɡạra divɛ̣rse vɔ̣lte."},{"n":796,"zh":"","en":"She's never flown in a helicopter.","it":"Non ha mai volato in elicottero.","ipa":"non a mạj volạto in elikɔ̣tːero."},{"n":797,"zh":"","en":"I've been to New York once.","it":"Sono stato a New York una volta.","ipa":"sọno stạto a (…) (…) ụna vɔ̣lta."},{"n":798,"zh":"","en":"I've never played tennis.","it":"Non ho mai giocato a tennis.","ipa":"non ɔ mạj ʤokạto a tɛ̣nːis."},{"n":799,"zh":"","en":"I've never driven a truck.","it":"Non ho mai guidato un camion.","ipa":"non ɔ mạj ɡwidạto un kạmjon."},{"n":800,"zh":"","en":"I've been late for school several times.","it":"Sono arrivato in ritardo a scuola parecchie volte.","ipa":"sọno arːivạto in ritạrdo a skwɔ̣la parɛ̣kːje vɔ̣lte."}]},{"lesson":9,"range":[801,900],"items":[{"n":801,"zh":"","en":"She's had many different jobs.","it":"Lei ha svolto molti lavori diversi.","ipa":"lɛ̣j a svɔ̣lto mọlti lavọri divɛ̣rsi."},{"n":802,"zh":"","en":"She's written ten (10) books.","it":"Lei ha scritto dieci (10) libri.","ipa":"lɛ̣j a skrịtːo djẹʧi (10) lịbri."},{"n":803,"zh":"","en":"She's written a lot of interesting things.","it":"Lei ha scritto molte cose interessanti.","ipa":"lɛ̣j a skrịtːo mọlte kɔ̣ze interesːạnti."},{"n":804,"zh":"","en":"She's traveled all over the world.","it":"Lei ha viaggiato in tutto il mondo.","ipa":"lɛ̣j a vjadʤạto in tụtːo il mọndo."},{"n":805,"zh":"","en":"She's been married three (3) times.","it":"Si è sposata tre (3) volte.","ipa":"si ɛ̣ spozạta trɛ (3) vɔ̣lte."},{"n":806,"zh":"","en":"She's met a lot of interesting people.","it":"Lei ha incontrato molta gente interessante.","ipa":"lɛ̣j a iŋkontrạto mọlta ʤɛ̣nte interesːạnte."},{"n":807,"zh":"","en":"I've seen that woman before, but I can't remember her name.","it":"Ho già visto prima quella donna, ma non ricordo il suo nome.","ipa":"ɔ ʤạ vịsto prịma kwɛ̣lːa dɔ̣nːa, ma non rikɔ̣rdo il sụo nọme."},{"n":808,"zh":"","en":"Have you ever played basketball? — Just once.","it":"Hai mai giocato a pallacanestro? — Solo una volta.","ipa":"ạj mạj ʤokạto a palːakanɛ̣stro? — sọlo ụna vɔ̣lta."},{"n":809,"zh":"","en":"Have you ever written a poem? — Yes, in high school.","it":"Hai mai scritto una poesia? — Sì, al liceo.","ipa":"ạj mạj skrịtːo ụna poẹzja? — sị, al liʧẹo."},{"n":810,"zh":"","en":"Does she know Claude? — No, she's never met him.","it":"Lei conosce Claudio? — No, non lo ha mai incontrato.","ipa":"lɛ̣j konọʃe klạwdjo? — nɔ, non lo a mạj iŋkontrạto."},{"n":811,"zh":"","en":"They have lots of books, and have read all of them.","it":"Loro hanno molti libri e li hanno letti tutti quanti.","ipa":"lọro ạnːo mọlti lịbri e li ạnːo lɛ̣tːi tụtːi kwạnti."},{"n":812,"zh":"","en":"I've never been to New Zealand, but my brother's been there twice.","it":"Non sono mai stato in Nuova Zelanda, però mio fratello ci è stato due volte.","ipa":"non sọno mạj stạto in nwɔ̣va ʦelạnda, perɔ̣ mịo fratɛ̣lːo ʧi ɛ̣ stạto dụe vɔ̣lte."},{"n":813,"zh":"","en":"Gunter's favorite movie is Star Wars. He's seen it twenty (20) times, but I've never seen it.","it":"Star Wars è il film preferito di Gunter. Lo ha visto venti (20) volte, ma io non l'ho mai visto.","ipa":"star wars ɛ̣ il film preferịto di (…). lo a vịsto vɛ̣nti (20) vɔ̣lte, ma ịo non lɔ mạj vịsto."},{"n":814,"zh":"","en":"I've traveled by plane, bus, and train. Someday, I want to take a trip by boat.","it":"Ho viaggiato in aereo, in bus e in treno. Un giorno voglio fare un viaggio in nave.","ipa":"ɔ vjadʤạto in aẹreo, in bus e in trẹno. un ʤọrno vɔ̣ʎːjo fạre un vjạdʤo in nạve."},{"n":815,"zh":"","en":"Caroline's on vacation in Brazil. She's there now.","it":"Carolina è in vacanza in Brasile. È lì in questo momento.","ipa":"karolịna ɛ̣ in vakạnʦa in brazịle. ɛ̣ lị in kwɛ̣sto momɛ̣nto."},{"n":816,"zh":"","en":"She arrived in Brazil on Monday. Today's Thursday.","it":"È arrivata in Brasile lunedì. Oggi è martedì.","ipa":"ɛ̣ arːivạta in brazịle lunedị. ɔ̣dʤi ɛ̣ martedị."},{"n":817,"zh":"","en":"How long has she been in Brazil?","it":"Da quanto tempo è in Brasile?","ipa":"da kwạnto tẹmpo ɛ̣ in brazịle?"},{"n":818,"zh":"","en":"She's been in Brazil since Monday.","it":"È in Brasile da lunedì.","ipa":"ɛ̣ in brazịle da lunedị."},{"n":819,"zh":"","en":"She's been in Brazil for three (3) days.","it":"È in Brasile da tre (3) giorni.","ipa":"ɛ̣ in brazịle da trɛ (3) ʤọrni."},{"n":820,"zh":"","en":"Emil and Larisa are married. They've been married for five (5) years.","it":"Emil e Larisa sono sposati. Sono sposati da cinque (5) anni.","ipa":"emịl e larịza sọno spozạti. sọno spozạti da ʧịŋkwe (5) ạnːi."},{"n":821,"zh":"","en":"Are you married? How long have you been married?","it":"Siete sposati? Da quanto tempo siete sposati?","ipa":"sjẹte spozạti? da kwạnto tẹmpo sjẹte spozạti?"},{"n":822,"zh":"","en":"Do you know her? How long have you known her?","it":"La conosci? Da quanto tempo la conosci?","ipa":"la konọʃi? da kwạnto tẹmpo la konọʃi?"},{"n":823,"zh":"","en":"I know Charlotte. I've known her for a long time.","it":"Conosco Carlotta. La conosco da molto tempo.","ipa":"konọsko karlɔ̣tːa. la konọsko da mọlto tẹmpo."},{"n":824,"zh":"","en":"Karla lives in Tokyo. How long has she lived in Tokyo?","it":"Carla vive a Tokio. Da quanto tempo vive a Tokio?","ipa":"kạrla vịve a tɔ̣kjo. da kwạnto tẹmpo vịve a tɔ̣kjo?"},{"n":825,"zh":"","en":"She's lived there all her life.","it":"Ha vissuto lì tutta la [sua] vita.","ipa":"a visːụto lị tụtːa la [sụa] vịta."},{"n":826,"zh":"","en":"I have a car. How long have you had your car?","it":"Ho un'automobile. Da quanto tempo hai la tua auto?","ipa":"ɔ unawtomɔ̣bile. da kwạnto tẹmpo ạj la tụa ạwto?"},{"n":827,"zh":"","en":"I've had it since April.","it":"Ce l'ho da aprile.","ipa":"ʧe lɔ d‿ aprịle."},{"n":828,"zh":"","en":"I'm studying German. — How long have you been studying German?","it":"Studio [il] tedesco. Da quanto tempo studi [il] tedesco?","ipa":"stụdjo [il] tedɛ̣sko. da kwạnto tẹmpo stụdi [il] tedɛ̣sko?"},{"n":829,"zh":"","en":"I've been studying German for two (2) years.","it":"Studio il tedesco da due (2) anni.","ipa":"stụdjo il tedɛ̣sko da dụe (2) ạnːi."},{"n":830,"zh":"","en":"Gerard's watching TV. How long has he been watching TV?","it":"Gerardo sta guardando la televisione. Da quanto tempo guarda la tele?","ipa":"ʤerạrdo sta ɡwardạndo la televizjọne. da kwạnto tẹmpo ɡwạrda la tẹle?"},{"n":831,"zh":"","en":"He's been watching TV since five [o'clock] (5:00).","it":"Guarda la tivù dalle cinque (5:00) [in punto].","ipa":"ɡwạrda la tivụ dạlːe ʧịŋkwe (5:00) [in pụnto]."},{"n":832,"zh":"","en":"It's raining. It's been raining all day.","it":"Sta piovendo. E' tutto il giorno che piove.","ipa":"sta pjovɛ̣ndo. ɛ̣ tụtːo il ʤọrno ke pjɔ̣ve."},{"n":833,"zh":"","en":"Svetlana and Maksim are married. They've been married since nineteen ninety-nine (1999).","it":"Svetlana e Maksim sono sposati. Sono sposati dal millenovecentonovantanove (1999).","ipa":"svetlạna e maksịm sọno spozạti. sọno spozạti dal milːenoveʧentonovantanɔ̣ve ()."},{"n":834,"zh":"","en":"Severo's sick. He's been sick for the last few days.","it":"Severo è malato. È ammalato da qualche giorno.","ipa":"sevẹro ɛ̣ malạto. ɛ̣ amːalạto da kwạlke ʤọrno."},{"n":835,"zh":"","en":"We live on Main Street. We've lived there for a long time.","it":"Viviamo nella via principale. Ci viviamo da molto tempo.","ipa":"vivjạmo nɛ̣lːa vịa priɲʧipạle. ʧi vivjạmo da mọlto tẹmpo."},{"n":836,"zh":"","en":"Florentine works in a bank. She's worked in a bank for five (5) years.","it":"Florentine lavora in banca. Lavora in banca da cinque (5) anni.","ipa":"florentịne lavọra in bạŋka. lavọra in bạŋka da ʧịŋkwe (5) ạnːi."},{"n":837,"zh":"","en":"Hubert has a headache. He's had a headache since he got up this morning.","it":"Hubert ha mal di testa. Ha mal di testa da quando si è alzato questa mattina.","ipa":"(…) a mal di tɛ̣sta. a mal di tɛ̣sta da kwạndo si ɛ̣ alʦạto kwɛ̣sta matːịna."},{"n":838,"zh":"","en":"I'm studying English. I've studied English for six (6) months.","it":"Studio inglese. Studio l'inglese da sei (6) mesi.","ipa":"stụdjo inɡlẹze. stụdjo linɡlẹze da sɛ̣j (6) mẹzi."},{"n":839,"zh":"","en":"How long have they been in Brazil?","it":"Da quanto tempo sono in Brasile?","ipa":"da kwạnto tẹmpo sọno in brazịle?"},{"n":840,"zh":"","en":"How long have you known Olivia?","it":"Da quanto tempo conosci Olivia?","ipa":"da kwạnto tẹmpo konọʃi olịvja?"},{"n":841,"zh":"","en":"How long has she studied Italian?","it":"Da quanto tempo lei studia l'italiano?","ipa":"da kwạnto tẹmpo lɛ̣j stụdja litaljạno?"},{"n":842,"zh":"","en":"How long has he lived in Seattle?","it":"Da quanto tempo lui vive a Seattle?","ipa":"da kwạnto tẹmpo lụj vịve a (…)?"},{"n":843,"zh":"","en":"How long have you been a teacher?","it":"Da quanto tempo sei insegnante?","ipa":"da kwạnto tẹmpo sɛ̣j inseɲːạnte?"},{"n":844,"zh":"","en":"How long has it been raining?","it":"Da quanto tempo piove?","ipa":"da kwạnto tẹmpo pjɔ̣ve?"},{"n":845,"zh":"","en":"They've been married for ten (10) years.","it":"Sono sposati da dieci (10) anni.","ipa":"sọno spozạti da djẹʧi (10) ạnːi."},{"n":846,"zh":"","en":"Leonardo's lived in Canada since April.","it":"Leonardo vive in Canada da aprile.","ipa":"leonạrdo vịve in kạnada d‿ aprịle."},{"n":847,"zh":"","en":"Giselle and I are friends. I know her very well.","it":"Giselle e io siamo amici. La conosco molto bene.","ipa":"ʤizɛ̣lː‿ e ịo sjạmo amịʧi. la konọsko mọlto bẹne."},{"n":848,"zh":"","en":"Luisa and I are friends. I've known her for a long time.","it":"Luisa e io siamo amici. La conosco da molto tempo.","ipa":"lwịza e ịo sjạmo amịʧi. la konọsko da mọlto tẹmpo."},{"n":849,"zh":"","en":"Sorry I'm late. How long have you been waiting?","it":"Scusa, sono in ritardo. Da quanto stai aspettando?","ipa":"skụza, sọno in ritạrdo. da kwạnto stạj aspetːạndo?"},{"n":850,"zh":"","en":"Jean works in a hotel now. He likes his job a lot.","it":"Jean adesso lavora in un albergo. Gli piace molto il suo lavoro.","ipa":"(…) adɛ̣sːo lavọra in un albɛ̣rɡo. ʎːi pjạʧe mọlto il sụo lavọro"},{"n":851,"zh":"","en":"Isabelle's reading the newspaper. She's been reading it for two (2) hours.","it":"Isabella legge il giornale. Lo sta leggendo da due (2) ore.","ipa":"izabɛ̣lːa lẹdʤe il ʤornạle. lo sta ledʤɛ̣ndo da dụe (2) ọre."},{"n":852,"zh":"","en":"How long have you lived in this house?","it":"Da quanto tempo vivi in questa casa?","ipa":"da kwạnto tẹmpo vịv‿ in kwɛ̣sta kạza?"},{"n":853,"zh":"","en":"Is that a new coat? — No, I've had this coat for a long time.","it":"È nuovo quel cappotto? — No, possiedo questo cappotto da molto tempo.","ipa":"ɛ̣ nwɔ̣vo kwɛ̣l kapːɔ̣tːo? — nɔ, posːjẹdo kwɛ̣sto kapːɔ̣tːo da mọlto tẹmpo."},{"n":854,"zh":"","en":"Maalik's in Seattle right now. He's been there for the last three (3) days.","it":"Proprio in questo momento, Maalik si trova a Seattle. È lì da tre (3) giorni.","ipa":"prɔ̣prjo in kwɛ̣sto momɛ̣nto, maạlik si trɔ̣v‿ a (…). ɛ̣ lị da trɛ (3) ʤọrni."},{"n":855,"zh":"","en":"Yasmin's in Brazil. She's been there for three (3) days.","it":"Yasmin è in Brasile. Lei è lì da tre (3) giorni.","ipa":"(…) ɛ̣ in brazịle. lɛ̣j ɛ̣ lị da trɛ (3) ʤọrni."},{"n":856,"zh":"","en":"Today's Wednesday. She's been there since Monday.","it":"Oggi è mercoledì. È lì da lunedì.","ipa":"ɔ̣dʤi ɛ̣ merkoledị. ɛ̣ lị da lunedị."},{"n":857,"zh":"","en":"Lucien has been in Canada for six (6) months.","it":"Luciano è in Canada da sei (6) mesi.","ipa":"luʧạno ɛ̣ in kạnada da sɛ̣j (6) mẹzi."},{"n":858,"zh":"","en":"Lucien has been in Canada since January.","it":"Luciano è in Canada da gennaio.","ipa":"luʧạno ɛ̣ in kạnada da ʤenːạjo."},{"n":859,"zh":"","en":"We've been waiting for two (2) hours.","it":"Aspettiamo da due ore. > Stiamo aspettando da due (2) ore.","ipa":"aspetːjạmo da dụe ọre. > stjạmo aspetːạndo da dụe (2) ọre."},{"n":860,"zh":"","en":"We've been waiting since nine [o'clock] (9:00).","it":"Stiamo aspettando dalle nove. > Aspettiamo dalle nove (9:00).","ipa":"stjạmo aspetːạndo dạlːe nɔ̣ve. > aspetːjạmo dạlːe nɔ̣ve (9:00)."},{"n":861,"zh":"","en":"I've lived in Chicago for a long time.","it":"Vivo a Chicago da molto tempo.","ipa":"vịvo a (…) da mọlto tẹmpo."},{"n":862,"zh":"","en":"I've lived in Chicago since I was ten (10) years old.","it":"Vivo a Chicago da quando avevo dieci (10) anni.","ipa":"vịvo a (…) da kwạndo avẹvo djẹʧi (10) ạnːi."},{"n":863,"zh":"","en":"Jasmine started her new job three (3) weeks ago.","it":"Jasmine ha iniziato il suo nuovo lavoro tre (3) settimane fa.","ipa":"(…) a iniʦjạto il sụo nwɔ̣vo lavọro trɛ (3) setːimạne fa."},{"n":864,"zh":"","en":"When did Noboru leave? — He left ten (10) minutes ago.","it":"Quando è andato via Noboru? — È andato via dieci (10) minuti fa.","ipa":"kwạndo ɛ̣ andạto vịa nobɔ̣ru? — ɛ̣ andạto vịa djẹʧi (10) minụti fa."},{"n":865,"zh":"","en":"I had dinner an hour ago.","it":"Ho cenato un'ora fa.","ipa":"ɔ ʧenạto unọra fa."},{"n":866,"zh":"","en":"Life was very different a hundred (100) years ago.","it":"La vita era molto diversa cent'anni fa.","ipa":"la vịta ẹra mọlto divɛ̣rsa ʧentạnːi fa."},{"n":867,"zh":"","en":"When did Michiko arrive in Brazil?","it":"Quando è arrivata Michiko in Brasile?","ipa":"kwạndo ɛ̣ arːivạta (…) in brazịle?"},{"n":868,"zh":"","en":"She arrived in Brazil three (3) days ago.","it":"Lei è arrivata in Brasile tre (3) giorni fa.","ipa":"lɛ̣j ɛ̣ arːivạta in brazịle trɛ (3) ʤọrni fa."},{"n":869,"zh":"","en":"How long has she been in Brazil?","it":"Da quanto tempo è in Brasile?","ipa":"da kwạnto tẹmpo ɛ̣ in brazịle?"},{"n":870,"zh":"","en":"She's been in Brazil for three (3) days.","it":"È in Brasile da tre (3) giorni.","ipa":"ɛ̣ in brazịle da trɛ (3) ʤọrni."},{"n":871,"zh":"","en":"My aunt has lived in Australia for fifteen (15) years.","it":"Mia zia vive in Australia da quindici (15) anni.","ipa":"mịa ʦịa vịve in awstrạlja da kwịndiʧi (15) ạnːi."},{"n":872,"zh":"","en":"Lilianne's in her office. She's been there since seven [o'clock] (7:00).","it":"Liliana è nel suo ufficio. È lì dalle sette (7:00).","ipa":"liljạna ɛ̣ nɛl sụo ufːịʧo. ɛ̣ lị dạlːe sɛ̣tːe (7:00)."},{"n":873,"zh":"","en":"Mexico has been an independent country since eighteen twenty-one (1821).","it":"Il Messico è uno stato indipendente dal milleottocentoventuno (1821).","ipa":"il mɛ̣sːiko ɛ̣ ụno stạto indipendɛ̣nte dal milːeotːoʧentoventụno ()."},{"n":874,"zh":"","en":"The bus is late. We've been waiting for twenty (20) minutes.","it":"L'autobus è in ritardo. Aspettiamo da venti (20) minuti.","ipa":"lạwtobus ɛ̣ in ritạrdo. aspetːjạmo da vɛ̣nti (20) minụti."},{"n":875,"zh":"","en":"Nobody lives in those houses. They've been empty for many years.","it":"Nessuno abita in quelle case. Sono vuote da parecchi anni.","ipa":"nesːụno ạbita in kwɛ̣lːe kạze. sọno vwɔ̣te da parɛ̣kːi ạnːi."},{"n":876,"zh":"","en":"Michel's been sick for a long time. He's been in the hospital since October of last year.","it":"Michele è malato da molto tempo. È in ospedale da ottobre dell'anno scorso.","ipa":"mikẹl‿ ɛ̣ malạto da mọlto tẹmpo. ɛ̣ in ospedạle da otːọbre dɛlːạnːo skọrso."},{"n":877,"zh":"","en":"When was the last time you ate? — Three hours ago.","it":"Quando hai mangiato l'ultima volta? — Tre ore fa.","ipa":"kwạndo ạj maɲʤạto lụltima vɔ̣lta? — trɛ ọre fa."},{"n":878,"zh":"","en":"When was the last time you were sick? — Five months ago.","it":"Quando sei stato malato l'ultima volta? — Cinque mesi fa.","ipa":"kwạndo sɛ̣j stạto malạto lụltima vɔ̣lta? — ʧịŋkwe mẹzi fa."},{"n":879,"zh":"","en":"When was the last time you went to the movies? — Just last week.","it":"Quando sei andato l'ultima volta al cinema? — Proprio la settimana scorsa.","ipa":"kwạndo sɛ̣j andạto lụltima vɔ̣lt‿ al ʧịnema? — prɔ̣prjo la setːimạna skọrsa."},{"n":880,"zh":"","en":"When was the last time you were in a car? — Just this morning.","it":"Quando sei salito in macchina l'ultima volta? — Giusto stamattina.","ipa":"kwạndo sɛ̣j salịto in mạkːina lụltima vɔ̣lta? — ʤụsto stamatːịna."},{"n":881,"zh":"","en":"When was the last time you went on vacation? — A year ago.","it":"Quando sei andato l'ultima volta in vacanza? — Un anno fa.","ipa":"kwạndo sɛ̣j andạto lụltima vɔ̣lta in vakạnʦa? — un ạnːo fa."},{"n":882,"zh":"","en":"Mungeol and Weonhye have been married for twenty (20) years.","it":"Mungeol e Weonhye sono sposati da vent'anni.","ipa":"(…) e (…) sọno spozạti da ventạnːi."},{"n":883,"zh":"","en":"Mungeol and Weonhye got married twenty (20) years ago.","it":"Mungeol e Weonhye si sono sposati vent'anni fa.","ipa":"(…) e (…) si sọno spozạti ventạnːi fa."},{"n":884,"zh":"","en":"Nicholas arrived an hour ago.","it":"Nicola è arrivato un'ora fa.","ipa":"nikɔ̣la ɛ̣ arːivạto unọra fa."},{"n":885,"zh":"","en":"I bought these shoes a few days ago.","it":"Ho comprato queste scarpe qualche giorno fa.","ipa":"ɔ komprạto kwɛ̣ste skạrpe kwạlke ʤọrno fa."},{"n":886,"zh":"","en":"Miriam's been studying English for six (6) months.","it":"Miriam studia inglese da sei (6) mesi.","ipa":"mirjạm stụdja inɡlẹze da sɛ̣j (6) mẹzi."},{"n":887,"zh":"","en":"Have you known Heuijeong for a long time?","it":"Conosci Heuijeong da molto tempo?","ipa":"konọʃi (…) da mọlto tẹmpo?"},{"n":888,"zh":"","en":"Natalie's been in Brazil for three (3) days.","it":"Natalia è in Brasile da tre (3) giorni.","ipa":"natạlja ɛ̣ in brazịle da trɛ (3) ʤọrni."},{"n":889,"zh":"","en":"Geonhong's been here since Tuesday.","it":"Geonhong è qui da martedì.","ipa":"(…) ɛ̣ kwị da martedị."},{"n":890,"zh":"","en":"It's been raining for an hour.","it":"Piove da un'ora.","ipa":"pjɔ̣ve da unọra."},{"n":891,"zh":"","en":"I've known Mengjuan since two thousand two (2002).","it":"Conosco Mengjuan dal duemiladue (2002).","ipa":"konọsko (…) dal dwemiladụe ()."},{"n":892,"zh":"","en":"Remy and Pauline have been married for six (6) months.","it":"Remy e Pauline sono sposati da sei (6) mesi.","ipa":"(…) e pawlịne sọno spozạti da sɛ̣j (6) mẹzi."},{"n":893,"zh":"","en":"Hitomi has studied medicine at the university for three (3) years.","it":"Hitomi studia medicina all'università da tre (3) anni.","ipa":"itɔ̣mi stụdja mediʧịn‿ alːuniversitạ da trɛ (3) ạnːi."},{"n":894,"zh":"","en":"Ichirou's played the piano since he was seven (7) years old.","it":"Ichirou suona il pianoforte da quando aveva sette (7) anni.","ipa":"(…) swɔ̣na il pjanofɔ̣rte da kwạndo avẹva sɛ̣tːe (7) ạnːi."},{"n":895,"zh":"","en":"His car's dirty. He's washing his car. He's washed his car. It's clean now.","it":"La sua macchina è sporca. Lui sta lavando la sua autovettura. Ha lavato la sua macchina. Adesso è pulita.","ipa":"la sụa mạkːina ɛ̣ spọrka. lụj sta lavạndo la sụa awtovetːụra. a lavạto la sụa mạkːina. adɛ̣sːo ɛ̣ pulịta."},{"n":896,"zh":"","en":"They're at home. They're going out. They've gone out. They're not at home now.","it":"Loro sono a casa. Stanno uscendo. Sono usciti. In questo momento non sono a casa.","ipa":"lọro sọno a kạza. stạnːo uʃɛ̣ndo. sọno uʃịti. in kwɛ̣sto momɛ̣nto non sọno a kạza."},{"n":897,"zh":"","en":"I've lost my passport. I can't find my passport now.","it":"Ho perso il [mio] passaporto. In questo momento non riesco a trovare il [mio] passaporto.","ipa":"ɔ pɛ̣rso il [mịo] pasːapɔ̣rto. in kwɛ̣sto momɛ̣nto non rjẹsko a trovạre il [mịo] pasːapɔ̣rto."},{"n":898,"zh":"","en":"Where's Renee? — She's gone to bed. She's in bed now.","it":"Dov'è Renée? — È andata a letto. Adesso, è a letto.","ipa":"dovɛ̣ renée? — ɛ̣ andạt‿ a lɛ̣tːo. adɛ̣sːo, ɛ̣ a lɛ̣tːo."},{"n":899,"zh":"","en":"We've bought a new car. We have a new car now.","it":"Abbiamo comprato un'auto nuova. Adesso, abbiamo una macchina nuova.","ipa":"abːjạmo komprạto unạwto nwɔ̣va. adɛ̣sːo, abːjạmo ụna mạkːina nwɔ̣va."},{"n":900,"zh":"","en":"It's Rashmi's birthday tomorrow, and I haven't bought her a present. > I don't have a present for her yet.","it":"Domani è il compleanno di Rashmi e non le ho comprato il regalo. Non ho ancora un regalo per lei.","ipa":"domạni ɛ̣ il kompleạnːo di rạzmi e non le ɔ komprạto il reɡạlo. non ɔ aŋkọra un reɡạlo pɛr lɛ̣j."}]},{"lesson":10,"range":[901,1000],"items":[{"n":901,"zh":"","en":"Junhong is away on vacation. Where has he gone? Where is he now?","it":"Junhong è via, in vacanza. Dov'è andato? Dov'è adesso?","ipa":"(…) ɛ̣ vịa, in vakạnʦa. dovɛ̣ andạto? dovɛ̣ adɛ̣sːo?"},{"n":902,"zh":"","en":"Have you met my brother, or should I introduce you?","it":"Conosci mio fratello o devo presentartelo?","ipa":"konọʃi mịo fratɛ̣lː‿ o dẹvo prezentạrtelo?"},{"n":903,"zh":"","en":"I was a very slow typist in college, but I've gotten faster.","it":"Ero un dattilografo molto lento all'università, ma sono diventato più veloce.","ipa":"ẹro un datːilɔ̣ɡrafo mọlto lɛ̣nto alːuniversitạ, ma sọno diventạto piụ velọʧe."},{"n":904,"zh":"","en":"Where's your key? — I've lost it. I lost it.","it":"Dov'è la tua chiave? — L'ho persa.","ipa":"dovɛ̣ la tụa kjạve? — lɔ pɛ̣rsa."},{"n":905,"zh":"","en":"Is Oliver here? — No, he's gone home. He went home.","it":"Oliver è qui? — No, è andato a casa.","ipa":"ɔ̣liver ɛ̣ kwị? — nɔ, ɛ̣ andạto a kạza."},{"n":906,"zh":"","en":"We've bought a new car. We bought a new car.","it":"Abbiamo comprato una macchina nuova.","ipa":"abːjạmo komprạto ụna mạkːina nwɔ̣va."},{"n":907,"zh":"","en":"I lost my keys yesterday.","it":"Ho perso le [mie] chiavi ieri.","ipa":"ɔ pɛ̣rso le [mịe] kjạvi jẹri."},{"n":908,"zh":"","en":"I lost my keys last week.","it":"Ho perso le [mie] chiavi settimana scorsa.","ipa":"ɔ pɛ̣rso le [mịe] kjạvi setːimạna skọrsa."},{"n":909,"zh":"","en":"I've lost my keys five (5) times this month.","it":"Ho perso le [mie] chiavi cinque (5) volte questo mese.","ipa":"ɔ pɛ̣rso le [mịe] kjạvi ʧịŋkwe (5) vɔ̣lte kwɛ̣sto mẹze."},{"n":910,"zh":"","en":"We bought a new car yesterday.","it":"Ieri, abbiamo comprato una macchina nuova.","ipa":"jẹri, abːjạmo komprạto ụna mạkːina nwɔ̣va."},{"n":911,"zh":"","en":"We bought a new car last week.","it":"Settimana scorsa, abbiamo comprato un'auto nuova.","ipa":"setːimạna skọrsa, abːjạmo komprạto unạwto nwɔ̣va."},{"n":912,"zh":"","en":"We've bought two (2) new cars in the last three (3) years.","it":"Abbiamo comprato due (2) macchine nuove negli ultimi tre (3) anni.","ipa":"abːjạmo komprạto dụe (2) mạkːine nwɔ̣ve nɛ̣ʎːi ụltimi trɛ (3) ạnːi."},{"n":913,"zh":"","en":"Serge isn't here. He went home. > He's already gone home.","it":"Sergio non è qui. È andato a casa. È già andato a casa.","ipa":"sɛ̣rʤo non ɛ̣ kwị. ɛ̣ andạto a kạza. ɛ̣ ʤạ andạto a kạza."},{"n":914,"zh":"","en":"I don't need to call them. I wrote them an email. > I've already written them an email.","it":"Non ho bisogno di chiamarli. Ho scritto loro una mail. Ho già scritto loro una e-mail.","ipa":"non ɔ bizọɲːo di kjamạrli. ɔ skrịtːo lọro ụna mạil. ɔ ʤạ skrịtːo lọro ụna (…)."},{"n":915,"zh":"","en":"Sabine's not coming to the party. She broke her arm. > She's broken her arm.","it":"Sabina non verrà alla festa. Si è rotta il braccio.","ipa":"sabịna non verːạ ạlːa fɛ̣sta. si ɛ̣ rọtːa il brạtʧo."},{"n":916,"zh":"","en":"My brother and his wife don't live here any more. They moved to Seattle. > They've moved to Seattle.","it":"Mio fratello e sua moglie non vivono più qui. Si sono trasferiti a Seattle.","ipa":"mịo fratɛ̣lːo e sụa mọʎːje non vịvono piụ kwị. si sọno trasferịti a (…)."},{"n":917,"zh":"","en":"I made a mistake. > I've made a mistake.","it":"Ho commesso un errore.","ipa":"ɔ komːɛ̣sːo un erːọre."},{"n":918,"zh":"","en":"I lost my wallet. > I've lost my wallet.","it":"Ho perso il [mio] portafoglio.","ipa":"ɔ pɛ̣rso il [mịo] portafọʎːjo."},{"n":919,"zh":"","en":"Did you see it anywhere? > Have you seen it anywhere?","it":"L'hai visto da qualche parte?","ipa":"lạj vịsto da kwạlke pạrte?"},{"n":920,"zh":"","en":"Did you hear? > Have you heard?","it":"Hai sentito?","ipa":"ạj sentịto?"},{"n":921,"zh":"","en":"Theo got married. > Theo's gotten married.","it":"Teo si è sposato.","ipa":"tẹo si ɛ̣ spozạto."},{"n":922,"zh":"","en":"I've done the shopping. > I did the shopping.","it":"Ho fatto aquisti.","ipa":"ɔ fạtːo akwịsti."},{"n":923,"zh":"","en":"Gustavo has taken my bike again without asking. > Gustavo took my bike without asking.","it":"Gustavo ha preso di nuovo la mia bici senza chiedere. Gustavo ha preso la mia bici senza chiedermelo.","ipa":"ɡustạvo a prẹzo di nwɔ̣vo la mịa bịʧi sɛ̣nʦa kjɛ̣dere. ɡustạvo a prẹzo la mịa bịʧi sɛ̣nʦa kjɛ̣dermelo."},{"n":924,"zh":"","en":"Have you told your friends the good news? > Did you tell your friends the good news?","it":"Hai raccontato ai tuoi amici la buona notizia?","ipa":"ạj rakːontạto ạj twɔ̣j amịʧi la bwɔ̣na notịʦja?"},{"n":925,"zh":"","en":"We haven't paid the electric bill yet. > We didn't pay the electric bill.","it":"Non abbiamo ancora pagato la bolletta della luce. Non abbiamo pagato l'elettricità.","ipa":"non abːjạmo aŋkọra paɡạto la bolːɛ̣tːa dɛ̣lːa lụʧe. non abːjạmo paɡạto leletːriʧitạ."},{"n":926,"zh":"","en":"Are Vincent and Valerie here? — Yes, they just arrived.","it":"Vincenzo e Valeria sono qui? — Sì, sono appena arrivati.","ipa":"viɲʧẹnʦo e valẹrja sọno kwị? — sị, sọno apːẹn‿ arːivạti."},{"n":927,"zh":"","en":"Are you hungry? — No, I just had dinner.","it":"Hai fame? — No, ho appena cenato.","ipa":"ạj fạme? — nɔ, ɔ apːẹna ʧenạto."},{"n":928,"zh":"","en":"Is Niraj here? — No, he just left.","it":"Niraj è qui? — No, è appena andato via.","ipa":"(…) ɛ̣ kwị? — nɔ, ɛ̣ apːẹn‿ andạto vịa."},{"n":929,"zh":"","en":"What time are Nikolai and Victoria coming? — They've already arrived.","it":"A che ora vengono Nicola e Vittoria? — Sono già arrivati.","ipa":"a ke ọra vẹŋɡono nikɔ̣la e vitːɔ̣rja? — sọno ʤạ arːivạti."},{"n":930,"zh":"","en":"It's only nine o'clock (9:00) and Ines has already gone to bed.","it":"Sono solo le nove (9:00) e Ines è già andata a letto.","ipa":"sọno sọlo le nɔ̣ve (9:00) e ịnes ɛ̣ ʤạ andạt‿ a lɛ̣tːo."},{"n":931,"zh":"","en":"This is Yvonne. — Yes, we've already met.","it":"Lei è Ivonne. — Sì, ci siamo già incontrati (conosciuti).","ipa":"lɛ̣j ɛ̣ ivɔ̣nːe. — sị, ʧi sjạmo ʤạ iŋkontrạti (konoʃụti)."},{"n":932,"zh":"","en":"Are Isidor and Sandra here? — No, they haven't arrived yet.","it":"Isidoro e Sandra sono qui? — No, non sono ancora arrivati.","ipa":"izidɔ̣ro e sạndra sọno kwị? — nɔ, non sọno aŋkọra arːivạti."},{"n":933,"zh":"","en":"Does Yannick know that you're going away? — No, I haven't told him yet.","it":"Yannick sa che stai andando via? — No, non gliel'ho ancora detto.","ipa":"janːịkk sa ke stạj andạndo vịa? — nɔ, non ʎːjelɔ aŋkọra dɛ̣tːo."},{"n":934,"zh":"","en":"Dora has bought a new dress, but she hasn't worn it yet.","it":"Dora ha comprato un nuovo vestito, ma non l'ha ancora indossato.","ipa":"dọra a komprạto un nwɔ̣vo vestịto, ma non l‿ aŋkọra indosːạto."},{"n":935,"zh":"","en":"Have Chandra and Indira arrived yet? — No, not yet. We're still waiting for them.","it":"Chandra e Indira sono già arrivate? — No, non ancora. Le stiamo ancora aspettando.","ipa":"(…) e indịra sọno ʤạ arːivạte? — nɔ, non aŋkọra. le stjạmo aŋkọra aspetːạndo."},{"n":936,"zh":"","en":"Has Zinaida started her new job yet? — No, she's starting next week.","it":"Zinaida ha già iniziato il suo nuovo lavoro? — No, inizierà settimana prossima.","ipa":"ʦinạid‿ a ʤạ iniʦjạto il sụo nwɔ̣vo lavọro? — nɔ, iniʦjerạ setːimạna prɔ̣sːima."},{"n":937,"zh":"","en":"This is my new dress. — It's nice, have you worn it yet?","it":"Questo è il mio vestito nuovo. — È carino, l'hai già indossato?","ipa":"kwɛ̣sto ɛ̣ il mịo vestịto nwɔ̣vo. — ɛ̣ karịno, lạj ʤạ indosːạto?"},{"n":938,"zh":"","en":"What time is Stan arriving? — He's already arrived.","it":"A che ora arriva Stan? — È già arrivato.","ipa":"a ke ọra arːịva (…)? — ɛ̣ ʤạ arːivạto."},{"n":939,"zh":"","en":"Do your friends want to see the movie? — No, they've already seen it.","it":"I tuoi amici vogliono vedere il film? — No, l'hanno già visto.","ipa":"i twɔ̣j amịʧi vɔ̣ʎːjono vedẹre il film? — nɔ, lạnːo ʤạ vịsto."},{"n":940,"zh":"","en":"Don't forget to call Vadim. — I've already called him.","it":"Non scordarti di chiamare Vadim. — L'ho già chiamato.","ipa":"non skordạrti di kjamạre (…). — lɔ ʤạ kjamạto."},{"n":941,"zh":"","en":"When is Hideki going to work? — He's already gone to work.","it":"Quando andrà a lavorare Hideki? — È già andata a lavorare.","ipa":"kwạndo andrạ a lavorạre idẹki? — ɛ̣ ʤạ andạt‿ a lavorạre."},{"n":942,"zh":"","en":"When does Hanako start her new job? — She's already started it.","it":"Hakano, quando inizierà il suo nuovo lavoro ? — Ha già iniziato.","ipa":"akạno, kwạndo iniʦjerạ il sụo nwɔ̣vo lavọro ? — a ʤạ iniʦjạto."},{"n":943,"zh":"","en":"Has Tamara started her new job yet?","it":"Tamara, ha già iniziato il suo lavoro nuovo?","ipa":"tamạra, a ʤạ iniʦjạto il sụo lavọro nwɔ̣vo?"},{"n":944,"zh":"","en":"Have you told your father about the accident yet?","it":"Hai già raccontato a tuo padre dell'incidente?","ipa":"ạj ʤạ rakːontạto a tụo pạdre dɛlːiɲʧidɛ̣nte?"},{"n":945,"zh":"","en":"I've just eaten a big dinner, so I'm not hungry.","it":"Ho appena mangiato una cena abbondante, per questo non ho fame.","ipa":"ɔ apːẹna maɲʤạto ụna ʧẹn‿ abːondạnte, pɛr kwɛ̣sto non ɔ fạme."},{"n":946,"zh":"","en":"Mengxuan can watch TV because she's already done her homework.","it":"Mengxuan può guardare le televisione perché ha già fatto i [suoi] compiti.","ipa":"(…) pwɔ̣ ɡwardạre le televizjọne perkɛ̣ a ʤạ fạtːo i [swɔ̣j] kọmpiti."},{"n":947,"zh":"","en":"You can't go to bed. You haven't brushed your teeth yet.","it":"Non puoi andare a letto. Non ti sei ancora lavato i denti.","ipa":"non pwɔ̣j andạre a lɛ̣tːo. non ti sɛ̣j aŋkọra lavạto i dɛ̣nti."},{"n":948,"zh":"","en":"You can't talk to Vladimir because he's just gone home.","it":"Non puoi parlare con Vladimir perché è appena andato a casa.","ipa":"non pwɔ̣j parlạre kon vlạdimir perkɛ̣ ɛ̣ apːẹn‿ andạto a kạza."},{"n":949,"zh":"","en":"Ramona's just gotten out of the hospital, so she can't go to work.","it":"Ramona è appena uscita dall'ospedale, quindi non può andare a lavorare.","ipa":"ramọna ɛ̣ apːẹna uʃịta dalːospedạle, kwịndi non pwɔ̣ andạre a lavorạre."},{"n":950,"zh":"","en":"Have you given the post office our new address yet?","it":"Hai già dato all'ufficio postale il nostro nuovo indirizzo?","ipa":"ạj ʤạ dạto alːufːịʧo postạle il nɔ̣stro nwɔ̣vo indirịʦːo?"},{"n":951,"zh":"","en":"The postman hasn't come yet.","it":"Il postino non è ancora arrivato.","ipa":"il postịno non ɛ̣ aŋkọra arːivạto."},{"n":952,"zh":"","en":"I've just spoken to your sister.","it":"Ho appena parlato con tua sorella.","ipa":"ɔ apːẹna parlạto kon tụa sorɛ̣lːa."},{"n":953,"zh":"","en":"Has Jianwen bought a new computer yet?","it":"Jianwen ha già comprato un computer nuovo?","ipa":"(…) a ʤạ komprạto un kompjụter nwɔ̣vo?"},{"n":954,"zh":"","en":"Geonho and Ayeong haven't told anyone they're getting married yet.","it":"Geonho e Ayeong non hanno ancora detto a nessuno che si sposeranno.","ipa":"(…) e (…) non ạnːo aŋkọra dɛ̣tːo a nesːụno ke si spozerạnːo."},{"n":955,"zh":"","en":"We've already done our packing for our trip.","it":"Abbiamo già preparato i bagagli per il nostro viaggio.","ipa":"abːjạmo ʤạ preparạto i baɡạʎːi pɛr il nɔ̣stro vjạdʤo."},{"n":956,"zh":"","en":"I've just swum a mile and I feel great.","it":"Ho appena nuotato un chilometro e mi sento benissimo.","ipa":"ɔ apːẹna nwotạto un kilɔ̣metro e mi sɛ̣nto benịsːimo."},{"n":957,"zh":"","en":"Your friend has a new job. Ask her if she has started her new job yet.","it":"La tua amica ha un nuovo lavoro. Chiedile se ha già iniziato il suo nuovo lavoro.","ipa":"la tụa amịk‿ a un nwɔ̣vo lavọro. kjɛ̣dile se a ʤạ iniʦjạto il sụo nwɔ̣vo lavọro."},{"n":958,"zh":"","en":"Your friend has some new neighbors. Ask him if he has met his new neighbors.","it":"Il tuo amico ha dei nuovi vicini di casa. Chiedigli se ha incontrato i suoi nuovi vicini di casa.","ipa":"il tụo amịko a dẹj nwɔ̣vi viʧịni di kạza. kjɛ̣diʎːi se a iŋkontrạto i swɔ̣j nwɔ̣vi viʧịni di kạza."},{"n":959,"zh":"","en":"Your friend has to pay her phone bill. Ask her if she has paid her phone bill yet.","it":"La tua amica deve pagare la bolletta del telefono. Chiedile se ha già pagato la bolletta del telefono.","ipa":"la tụa amịka dẹve paɡạre la bolːɛ̣tːa dɛl telɛ̣fono. kjɛ̣dile se a ʤạ paɡạto la bolːɛ̣tːa dɛl telɛ̣fono."},{"n":960,"zh":"","en":"Victor was trying to sell his car. Ask him if he has sold his car yet.","it":"Vittorio stava cercando di vendere la sua autovettura. Chiedigli se ha già venduto la sua macchina.","ipa":"vitːɔ̣rjo stạva ʧerkạndo di vɛ̣ndere la sụa awtovetːụra. kjɛ̣diʎːi se a ʤạ vendụto la sụa mạkːina."},{"n":961,"zh":"","en":"I saw Malika yesterday.","it":"Ieri, ho visto Malika.","ipa":"jẹri, ɔ vịsto mạlika."},{"n":962,"zh":"","en":"Where were you on Sunday afternoon?","it":"Dov'eri domenica pomeriggio?","ipa":"dovẹri domẹnika pomerịdʤo?"},{"n":963,"zh":"","en":"We didn't take a vacation last year.","it":"L'anno scorso non siamo andati in vacanza.","ipa":"lạnːo skọrso non sjạmo andạt‿ in vakạnʦa."},{"n":964,"zh":"","en":"What did you do last night? — I stayed at home.","it":"Che cos'hai fatto ieri sera? — Sono stato a casa.","ipa":"ke kozạj fạtːo jẹri sẹra? — sọno stạto a kạza."},{"n":965,"zh":"","en":"Shakespeare was a writer and wrote many plays and poems.","it":"Shakespeare era uno scrittore e ha scritto molte opere teatrali e poesie.","ipa":"(…) ẹra ụno skritːọre e a skrịtːo mọlte ọpere teatrạli e poezịe."},{"n":966,"zh":"","en":"When did you buy your computer?","it":"Quando hai comprato il tuo computer?","ipa":"kwạndo ạj komprạto il tụo kompjụter?"},{"n":967,"zh":"","en":"What time did Jamaal go out?","it":"A che ora è uscito Jamaal?","ipa":"a ke ọra ɛ̣ uʃịto jạmaal?"},{"n":968,"zh":"","en":"Kenji went home.","it":"Kenji è andato a casa.","ipa":"(…) ɛ̣ andạto a kạza."},{"n":969,"zh":"","en":"Did you have lunch today?","it":"Hai pranzato oggi?","ipa":"ạj pranʦạt‿ ɔ̣dʤi?"},{"n":970,"zh":"","en":"The email didn't arrive at all.","it":"L'e-mail non è proprio arrivata.","ipa":"l (…) non ɛ̣ prọprjo arːivạta."},{"n":971,"zh":"","en":"Have you ever been to Spain? Did you go to Spain last year?","it":"Sei mai stato in Spagna? L'anno scorso, sei andato in Spagna?","ipa":"sɛ̣j mạj stạto in spạɲːa? lạnːo skọrso, sɛ̣j andạto in spạɲːa?"},{"n":972,"zh":"","en":"My friend has written many books. Shakespeare wrote many plays and poems.","it":"Il mio amico ha scritto molti libri. Shakespeare ha scritto molte opere teatrali e poesie.","ipa":"il mịo amịko a skrịtːo mọlti lịbri. (…) a skrịtːo mọlte ọpere teatrạli e poezịe."},{"n":973,"zh":"","en":"The email hasn't arrived yet. > The email didn't arrive today.","it":"L'e-mail non è ancora arrivata. La mail, oggi, non è arrivata.","ipa":"l (…) non ɛ̣ aŋkọra arːivạta. la mạil, ɔ̣dʤi, non ɛ̣ arːivạta."},{"n":974,"zh":"","en":"We've lived in Paris for six (6) years. > We lived in Paris for six (6) years, but now we live in Rome.","it":"Viviamo a Parigi da sei (6) anni. Abbiamo vissuto a Parigi per sei (6) anni, ma ora viviamo a Roma.","ipa":"vivjạmo a parịʤi da sɛ̣j (6) ạnːi. abːjạmo visːụto a parịʤi pɛr sɛ̣j (6) ạnːi, ma ọra vivjạmo a rọma."},{"n":975,"zh":"","en":"I had lunch an hour ago.","it":"Ho pranzato un'ora fa.","ipa":"ɔ pranʦạto unọra fa."},{"n":976,"zh":"","en":"I started my new job last week.","it":"Ho iniziato il mio nuovo lavoro la settimana scorsa.","ipa":"ɔ iniʦjạto il mịo nwɔ̣vo lavọro la setːimạna skọrsa."},{"n":977,"zh":"","en":"My friends arrived on Friday.","it":"I miei amici sono arrivati venerdì.","ipa":"i mjɛ̣j amịʧi sọno arːivạti venerdị."},{"n":978,"zh":"","en":"Keiko went out at five [o'clock] (5:00).","it":"Keiko è uscita alle cinque (5:00) [esatte].","ipa":"(…) ɛ̣ uʃịt‿ ạlːe ʧịŋkwe (5:00) [ezạtːe]."},{"n":979,"zh":"","en":"I wore my new suit yesterday.","it":"Ieri, ho indossato il mio nuovo completo.","ipa":"jẹri, ɔ indosːạto il mịo nwɔ̣vo komplẹto."},{"n":980,"zh":"","en":"Have you seen Veda? > Did you see Veda yesterday?","it":"Hai visto Veda? Hai visto Veda, ieri?","ipa":"ạj vịsto vẹda? ạj vịsto vẹda, jẹri?"},{"n":981,"zh":"","en":"I've finished my work. > I finished my work at two [o'clock] (2:00).","it":"Ho finito il mio lavoro. Ho terminato il mio lavoro alle due [precise].","ipa":"ɔ finịto il mịo lavọro. ɔ terminạto il mịo lavọro ạlːe dụe [preʧịze]."},{"n":982,"zh":"","en":"Have you finished? > What time did you finish your work?","it":"Hai finito? A che ora hai terminato il tuo lavoro?","ipa":"ạj finịto? a ke ọra ạj terminạto il tụo lavọro?"},{"n":983,"zh":"","en":"Liting isn't here; she's gone out.","it":"Liting non è qui. È uscita.","ipa":"(…) non ɛ̣ kwị. ɛ̣ uʃịta."},{"n":984,"zh":"","en":"Sanjit's grandmother has died. > Sanjit's grandmother died two (2) years ago.","it":"La nonna di Sanjit è morta. La nonna di Sanjit è morta due (2) anni fa.","ipa":"la nɔ̣nːa di (…) ɛ̣ mɔ̣rta. la nɔ̣nːa di (…) ɛ̣ mɔ̣rta dụe (2) ạnːi fa."},{"n":985,"zh":"","en":"Where have you been? > Where were you last night?","it":"Dove sei stato? Dov'eri ieri notte?","ipa":"dọve sɛ̣j stạto? dovẹri jẹri nɔ̣tːe?"},{"n":986,"zh":"","en":"My friend is a writer, and has written many books.","it":"Il mio amico è scrittore e ha scritto molti libri.","ipa":"il mịo amịko ɛ̣ skritːọre e a skrịtːo mọlti lịbri."},{"n":987,"zh":"","en":"I played tennis yesterday afternoon.","it":"Ieri pomeriggio ho giocato a tennis.","ipa":"jẹri pomerịdʤ‿ ɔ ʤokạto a tɛ̣nːis."},{"n":988,"zh":"","en":"What time did you go to bed last night?","it":"A che ora sei andato a letto ieri notte?","ipa":"a ke ọra sɛ̣j andạto a lɛ̣tːo jẹri nɔ̣tːe?"},{"n":989,"zh":"","en":"Have you ever met a famous person?","it":"Hai mai incontrato una persona famosa?","ipa":"ạj mạj iŋkontrạto ụna persọna famọza?"},{"n":990,"zh":"","en":"The weather wasn't very good yesterday.","it":"Il tempo non era molto bello ieri.","ipa":"il tẹmpo non ẹra mọlto bɛ̣lːo jẹri."},{"n":991,"zh":"","en":"Mira travels a lot. She's visited many countries.","it":"Mira viaggia molto. Ha visitato molti paesi.","ipa":"mịra vjạdʤa mọlto. a vizitạto mọlti paẹzi."},{"n":992,"zh":"","en":"I turned off the light before leaving this morning.","it":"Stamattina, prima di uscire, ho spento la luce.","ipa":"stamatːịna, prịma di uʃịre, ɔ spɛ̣nto la lụʧe."},{"n":993,"zh":"","en":"I live in New York now, but I've lived in Mexico for many years.","it":"Adesso vivo a New York, però ho vissuto in Messico molti anni.","ipa":"adɛ̣sːo vịvo a (…) (…), perɔ̣ ɔ visːụto in mɛ̣sːiko mọlti ạnːi."},{"n":994,"zh":"","en":"What's Taiwan like? Is it beautiful? — I don't know. I've never been there.","it":"Com'è Taiwan? È bella? — Non lo so, non ci sono mai stato (♀stata).","ipa":"komɛ̣ tajwạn? ɛ̣ bɛ̣lːa? — non lo sɔ, non ʧi sọno mạj stạto (♀stạta)."},{"n":995,"zh":"","en":"Have you ever been to Florida?","it":"Siete mai stati in Florida?","ipa":"sjẹte mạj stạt‿ in flɔ̣rida?"},{"n":996,"zh":"","en":"We went there on vacation two (2) years ago.","it":"Ci siamo andati in vacanza due (2) anni fa.","ipa":"ʧi sjạmo andạt‿ in vakạnʦa dụe (2) ạnːi fa."},{"n":997,"zh":"","en":"Did you have a good time?","it":"Vi siete divertiti?","ipa":"vi sjẹte divertịti?"},{"n":998,"zh":"","en":"We had a great time. It was wonderful.","it":"Ci siamo divertiti molto. È stato fantastico.","ipa":"ʧi sjạmo divertịti mọlto. ɛ̣ stạto fantạstiko."},{"n":999,"zh":"","en":"What does your girlfriend do?","it":"Che cosa fa la tua ragazza?","ipa":"ke kɔ̣za fa la tụa raɡạʦːa?"},{"n":1000,"zh":"","en":"She's a painter. She's won many prizes for her paintings.","it":"È pittrice. Ha vinto molti premi per i suoi dipinti.","ipa":"ɛ̣ pitːrịʧe. a vịnto mọlti prẹmi pɛr i swɔ̣j dipịnti."}]}]};
